pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals in [1, 12] are nearly unusable (min item = 1,
    // but small gaps rarely match future demand) -> strong penalty.
    if post_residual > 0 && post_residual <= 12 {
        score += (13 - post_residual) as f64 * 18.0;
    }
    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 25.0 * fill_ratio;
    }

    // Penalize leaving a gap just below next_item_size (blocks lookahead item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }
    // Reward if post_residual exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Open-bin pressure: prefer spreading load when many bins are open,
    // but discourage opening new bins when few exist.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make fresh bins attractive only when the
    // item is large relative to remaining capacity of open bins, or when
    // mean residual across open bins is small (poor fits everywhere).
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).max(0.0);
        // Default neutral-ish score; open only if open bins are nearly full.
        score = bin_capacity as f64 * 0.5 + (1.0 - pressure) * 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size && pressure > 0.5 {
            score -= 15.0; // pair large items into a fresh bin
        }
    }

    // Mild stream-progression tilt: later in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for ANY item are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 40.0; // perfect fit, ideal
    } else if post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Penalize gaps that the lookahead item cannot use either.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            // residual can host the next item: reward usable continuation
            score -= 4.0;
        }
    }

    // Reward tight fits relative to residual (waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Open-bin pressure: with many bins open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    // (large item, high mean residual elsewhere).
    if bin_residual == bin_capacity {
        let poor_fits = (bin_residual - item_size) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // Base penalty so new bins open only when justified.
        score += 30.0;
        // Reward opening when the item would leave a big awkward gap anyway
        // and open bins are already slack-heavy.
        score -= poor_fits * 0.25 + pressure * 20.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1..10 range guard: treat < 10 as unusable dead space) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize very small but potentially usable gaps proportionally harder.
    if post_residual > 0 && post_residual < 20 {
        score += 20.0;
    }

    // Reward tight fits (post_residual near zero is ideal).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading items out.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing
    // bins would leave bad dead space or no bin fits well.
    if bin_residual == bin_capacity {
        // Neutral baseline for a new bin; slight penalty so tight fits in
        // existing bins win, but small enough that poor fits lose to it.
        score += 15.0;
    }

    // Lookahead coupling: if the next item could exactly fill this bin's
    // post-residual, reward leaving that gap; if next item cannot use the
    // post-residual at all, penalize it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 10.0;
        }
    }

    // Mean-residual coupling: when open bins are generally roomy, slightly
    // prefer filling them rather than the tightest one only.
    let mean_r = mean_residual;
    if (post_residual as f64) > mean_r {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space quadratically (small residuals are bad).
    let mut score = 100.0 * (1.0 - x) * (1.0 - x) + 10.0 * x;

    // Smooth non-linear coupling of fit quality with stream progress:
    // early on, prefer tight fits; late, tolerate slack to keep bins closing.
    let progress_weight = t * t * (3.0 - 2.0 * t); // smoothstep
    score += 20.0 * progress_weight * x * (1.0 - x);

    // Coupling with mean residual: avoid bins far from the fleet average.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev - 3.0 * dev * progress_weight;

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress_weight + 0.5 * progress_weight);
    }

    // Lookahead: reward post residual that can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for proliferating bins.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress_weight);

    // New-bin candidate: keep it neutral-ish, slightly favored only when
    // current bin fit is very poor and stream is early.
    if bin_residual == bin_capacity {
        score = 40.0 + 20.0 * progress_weight - 15.0 * (1.0 - x * 0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = post_norm.powf(1.5 + 1.5 * progress);

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in the stream, small residuals are worth more (tighter packing)
    let coupling = post_norm * (1.0 - post_norm) * (0.25 + 0.75 * progress);
    score += 2.0 * coupling;

    // Penalize residuals that are too large to be useful later, scaled by progress
    let dead = (post_norm - 0.5).powi(2);
    score += 1.5 * dead * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 0.8 + 0.6 * (nxt / cap) * (1.0 - progress);
        } else {
            score += 0.4 * (1.0 - post / nxt.max(1.0)) * (0.5 + progress);
        }
    }

    // Mild penalty for spreading across many open bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress) / (1.0 + mean_residual / cap);

    // New-bin candidate: keep it attractive only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 1.2 - 0.8 * progress;
        if fitting_bins_count <= 1 {
            score -= 1.5;
        }
    }

    score
}

