pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the next item
    // (and too small to be useful) are heavily penalized.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space relative to the lookahead item: penalize proportionally
            let dead = (next_item_size - post_residual) as f64;
            score += 3.0 * dead;
        } else {
            // Gap still usable by next item: reward slightly
            score -= 2.0;
        }
    }

    // Unusable tiny gaps (below minimum plausible item size) are pure waste
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Tightness reward: fraction of residual consumed by this item
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few bins are open, allow opening new bins more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure
        score = 60.0 + pressure * 2.0 - (mean_residual / bin_capacity as f64) * 10.0;
        // If no open bin fits well, opening a new bin is cheap
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Using an existing bin reduces pressure slightly
        score -= pressure * 0.5;
        // Favor bins with residuals close to the mean (balanced packing)
        score += 0.2 * ((bin_residual as f64 - mean_residual).abs());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity wasted after placement

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small residual classes: post_residual in low harmonic bands are "dead space"
    // (1..=9 nearly unusable, 10..=19 usable only by smallest items).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Modulo-class: residuals that are multiples of common item granularities
    // (10s and 20s) are more reusable -> reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: does next_item_size fit in the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chain continues in this bin.
            score -= 30.0 + 0.3 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize proportional to how much
            // the leftover is stranded relative to the next item.
            let gap = next_item_size as f64 - pr;
            score += 0.5 * gap.min(40.0);
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.1 * pr;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large and would leave a well-structured residual elsewhere,
    // or when existing residuals are fragmented.
    if bin_residual == bin_capacity {
        // Fresh bin: baseline slight penalty so tight fits in open bins win,
        // but reward when open bins are few-residual / fragmented.
        score += 45.0;
        let fragmentation = (mean_residual - pr).abs();
        if mean_residual < 15.0 {
            score -= 70.0; // open bins nearly full -> open new bin
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // fresh bin can host the next item too
        }
        let _ = fragmentation;
    }

    // Progress-aware pressure: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - frac);

    // Prefer filling bins below mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Mild penalty on wasting large fractions of capacity.
    score += 40.0 * frac * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio weighted non-linearly.
    let waste = post_residual as f64;
    let tight_bonus = (waste / bin_capacity as f64).powi(3) * 60.0;
    score -= tight_bonus;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // strongly reward this placement (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_fit = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 40.0 * (1.0 - chain_fit);
        } else {
            // Next item won't fit here anyway; slight penalty for fragmenting.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, use it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer new bins only when existing fits are terrible
    // or the stream is early (future flexibility matters).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let flexibility = 1.0 - progress;
        score = 100.0 - 45.0 * flexibility
            + if fitting_bins_count > 0 { 10.0 } else { -50.0 };
    }

    // Global state: many open bins with high mean residual -> encourage consolidation.
    if bin_residual != bin_capacity {
        let consolidation = (mean_residual - bin_residual as f64) / bin_capacity as f64;
        score += consolidation * 20.0;
        score += open_bins_count as f64 * 0.5;
    }

    // Time horizon: late in the stream, prioritize filling bins completely.
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps below the minimum item size (1..100 interface, min item = 1) that cannot
    // hold the lookahead item are dead space; penalize quadratically.
    let progress = step_index as f64 / (total_items.max(2) as f64);
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 2.5 * dead * (1.0 + progress);
    }

    // Reward near-perfect fits strongly (post_residual small relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 4.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins late in stream.
    score += 0.35 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: penalize unless item is large relative to capacity or
    // current bin fits are poor (post_residual large).
    if bin_residual == bin_capacity {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 12.0 - 0.05 * item_size as f64 - 0.15 * spread;
        if post_residual as f64 > mean_residual + 10.0 {
            score -= 4.0;
        }
    }

    // Mild preference for bins tighter than the mean residual.
    if (bin_residual as f64) < mean_residual {
