    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that no item can use are heavily penalized.
    let min_gap = if next_item_size > 0 { next_item_size.min(80).max(1) } else { 1 };
    if post_residual > 0 && post_residual < min_gap.max(10) {
        // Unusable sliver: penalize proportionally to how much capacity is wasted.
        score += 40.0 + (min_gap.max(10) - post_residual) as f64 * 3.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residual exactly matching the lookahead item (chain planning).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        // Gap just barely too small for lookahead: dead space ahead, penalize.
        score += 15.0;
    }

    // Tight-fit reward: fraction of bin used by this item.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize placements that leave many bins open with slack.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is already below mean (consolidate slack).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or fit is terrible.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64);
        let bad_fit = post_residual as f64 > 60.0;
        if fitting_bins_count == 0 || (bad_fit && crowded > 2.0) {
            score -= 45.0;
        } else {
            // Discourage opening new bins when decent fits exist.
            score += 50.0;
        }
    }

    // Mild late-stream tightening: waste less as the stream nears its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the typical minimum item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    } else if post_residual < 35 {
        score += 3.0;
