    // Perfect fit reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Exact match with the next item's size: reserve the gap productively.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 5.0;
    }
    // Gap cannot fit the next item but is not zero: mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    // (lower post_residual already does this); when few bins are open,
    // tolerate spreading to keep residuals balanced.
    let bin_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += bin_pressure * (post_residual as f64) * 0.5;

    // Prefer bins whose residual is below mean (tighter bins) when many bins open.
    score += bin_pressure * (bin_residual as f64 - mean_residual) * 0.3;

    // Early in the stream, mildly encourage opening fresh bins for flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if it keeps a large, flexible residual
        // and current bins are congested.
        score = 40.0 - 12.0 * bin_pressure - 5.0 * (1.0 - progress) + 0.3 * post_residual as f64;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 3.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
