    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize wasting a nearly-full bin on a tiny item
    if (item_size as f64) < (bin_residual as f64) * 0.2 && bin_residual < bin_capacity {
        score += 30.0;
    }

    // Slight preference for keeping few bins open
    score += open_bins_count as f64 * 0.5;

    score
}

