    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += 0.05 * pr as f64 * progress;
    }

    // Modulo tiebreaker on item_size classes (harmonic packing flavor):
    // items in mid classes (30-60) pack best into bins whose residual is a
    // multiple of 10 offset from the item size.
    if pr % 10 == 0 && pr > 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 40.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += (21.0 - post_residual as f64) * 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if post_residual == 0 {
        score -= 120.0; // perfect fill
    } else {
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= tightness * 30.0;
    }

    // Open-bin pressure: discourage scattering when many bins are open,
    // but encourage using existing bins when few are open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 90.0;
    }
    // If next item cannot fit in post residual, mildly penalize leaving a gap.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: neutral baseline with mild early-stream preference,
    // penalized as stream progresses / when open bins exist and can absorb.
    if bin_residual == bin_capacity {
        score = 60.0 + (step_index as f64 / total_items.max(1) as f64) * 40.0
            + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream processed (dynamic time horizon).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    score = post_residual as f64 * (1.0 + 0.02 * post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward this placement (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well the next item would fill the gap.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // Next item won't fit here; penalize leaving a gap just above next size.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(30.0);
        }
    } else {
        // Last item: any residual is pure waste; push toward zero-waste.
        score += post_residual as f64 * 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 * (1.0 - t * 0.5);
    }

    // New-bin candidate: penalize opening a new bin, more so early/late in stream
    // and when many bins are already open; relax mid-stream for exploration.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 45.0 + 8.0 * open_pressure - 25.0 * (1.0 - t);
        // If no existing bin fits well, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    // Global state: prefer bins with residuals far from the mean (keep variety
    // of residual classes), but prefer bins close to mean when stream is ending.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * (0.3 - 0.25 * t);

    // Prefer bins whose residual is small relative to capacity (best-fit bias).
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Late-stream urgency: consolidate aggressively as the stream ends.
    score -= 20.0 * t * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: post-residual, polynomially coupled with stream progress.
    // Early on, waste matters less; later, minimize residual aggressively.
    let progress_coupling = 1.0 + 1.5 * progress * progress + 0.8 * progress;
    let mut score = post * progress_coupling;

    // Super-linear penalty for dead space (quartic on normalized residual):
    // small residuals are fine, large residuals become increasingly costly.
    score += 40.0 * norm_post * norm_post * norm_post * norm_post;

    // Smooth reward for near-perfect fits (post_residual close to 0 or small).
    let tightness = (-2.5 * norm_post).exp();
    score -= 25.0 * tightness;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * (1.0 - norm_post);
    }

    // Lookahead: reward if the next item fits into the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // next item fits: reward, stronger the better it fills leftover space
            let fill = nxt / post.max(1.0);
            score -= 15.0 * fill * fill;
        } else {
            // next item does not fit: penalize proportionally to how far off
            let gap = (nxt - post) / cap;
            score += 12.0 * gap;
        }
    }

    // Mild penalty proportional to number of open bins to discourage sprawl,
    // slightly relaxed early in the stream.
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins whose post-residual stays
    // harmonized with the fleet mean (smooth quadratic coupling).
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: make it moderately attractive only when the fit into
    // any open bin would leave large dead space; otherwise keep it costly.
    if bin_residual == bin_capacity {
        score += 35.0 - 25.0 * (1.0 - norm_post);
        // early stream: new bins are cheaper to open
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity wasted after placement

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small residual classes: post_residual in low harmonic bands are "dead space"
    // (1..=9 nearly unusable, 10..=19 usable only by smallest items).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Modulo-class: residuals that are multiples of common item granularities
    // (10s and 20s) are more reusable -> reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: does next_item_size fit in the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chain continues in this bin.
            score -= 30.0 + 0.3 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize proportional to how much
            // the leftover is stranded relative to the next item.
            let gap = next_item_size as f64 - pr;
            score += 0.5 * gap.min(40.0);
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.1 * pr;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large and would leave a well-structured residual elsewhere,
    // or when existing residuals are fragmented.
    if bin_residual == bin_capacity {
        // Fresh bin: baseline slight penalty so tight fits in open bins win,
        // but reward when open bins are few-residual / fragmented.
        score += 45.0;
        let fragmentation = (mean_residual - pr).abs();
        if mean_residual < 15.0 {
            score -= 70.0; // open bins nearly full -> open new bin
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // fresh bin can host the next item too
        }
        let _ = fragmentation;
    }

    // Progress-aware pressure: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - frac);

    // Prefer filling bins below mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Mild penalty on wasting large fractions of capacity.
    score += 40.0 * frac * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space penalty: gaps that no plausible item can use ---
    if post_residual > 0 {
        // Dead space: residual too small to hold even the smallest item (<=10)
        if post_residual < 10 {
            score += 60.0; // fully wasted gap -> heavily penalize
        } else if post_residual < 20 {
            score += 25.0; // near-dead gap: only tiny items could fit
        } else if post_residual < 35 {
            score += 8.0; // marginal gap
        }
    } else {
        // Perfect fill: subtract to strongly prefer exact closures
        score -= 30.0;
    }

    // --- Tightness reward: fraction of bin consumed by this item ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // --- Lookahead: does the next item fit the resulting gap? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains nicely into the leftover space
            let chain_tightness = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * chain_tightness;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Gap blocks the next item: penalize proportionally to how close
            score += 6.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        }
    }

    // --- Open-bin pressure: with many open bins, prefer reusing existing bins
    //     and avoid opening new ones; with few bins, opening is cheaper ---
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open
        score += 18.0 + 1.2 * open_pressure;
    } else {
        // Reward reusing an existing bin, scaled by how many are open
        score -= 1.0 + 0.35 * open_pressure;
    }

    // --- Last-chance bonus: this is the only bin that can fit the item ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // --- Alignment with mean residual: prefer bins whose leftover moves
    //     the average residual downward (consolidation) ---
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= 5.0 * (mean_residual - post_f).min(50.0) / 50.0;
    } else {
        score += 3.0 * (post_f - mean_residual).min(50.0) / 50.0;
    }

    // --- Mild late-stream tightening: near the end, close bins out ---
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 4.0 * progress * (post_f / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this is a great chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportional closeness of the follow-up fit.
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            // Penalize leaving residual too small to be useful for the next item.
            if post_residual < next_item_size && post_residual < 10 {
                score += 20.0;
            }
        } else {
            // Next item cannot use this bin's remainder: penalize proportionally.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.5 * overshoot.min(30.0);
        }
    } else {
        // Last item: just prefer tightest fit.
        score -= 10.0;
    }

    // Compare against mean residual: placing into a bin with residual near the
    // item size (tight relative fit) is good; huge-residual bins can absorb
    // big items later, so mildly penalize wasting a large residual.
    if (bin_residual as f64) > mean_residual + 15.0 && post_residual > 20 {
        score += 8.0;
    }
    if (bin_residual as f64) < mean_residual - 15.0 {
        score -= 5.0; // consolidate fragmented bins
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: opening a new bin should only win when no open bin
    // gives a decent fit. Penalize it unless the item is large relative to
    // what open bins offer (post_residual here equals capacity - item_size).
    if bin_residual == bin_capacity {
        let base = 25.0 + 0.3 * open_bins_count as f64;
        // If the item is big, a fresh bin is attractive (post_residual small).
        let big_item_bonus = if item_size >= 70 { 40.0 } else if item_size >= 50 { 15.0 } else { 0.0 };
        score = post_residual as f64 + base - big_item_bonus;
        // Early in the stream, keep bins open longer; late, allow new bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize large waste relative to current item size.
    score += 0.35 * post_residual as f64 / (item_size as f64 + 1.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many fitting bins -> less urgency, slight penalty to spread load evenly.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: if next item fits into post_residual exactly or well, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - next_fit / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that next item cannot use: penalize.
        score += 8.0;
    }

    // Prefer filling bins below mean residual (consolidation).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: early on, be more willing to open new bins (explore);
    // later, consolidate more aggressively.
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when open bins fit well.
        let mut new_bin_penalty = 18.0 + 30.0 * progress;
        if fitting_bins_count > 0 {
            new_bin_penalty += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Early exploration discount.
        new_bin_penalty -= 12.0 * (1.0 - progress);
        score = new_bin_penalty + 0.1 * item_size as f64;
    }

    // Late stream: penalize leaving residuals that are hard to fill (> half).
    if progress > 0.7 && post_residual > bin_capacity / 2 {
        score += 6.0;
    }

    // Mild penalty proportional to open bin count to discourage proliferation.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post-residual (dead space), scaled by stream progress
    let mut score = pr * (1.0 + 0.8 * progress) + 60.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: cubic reward as post_residual approaches zero
    score -= 45.0 * (1.0 - norm_pr).powi(3) * (0.6 + 0.8 * progress);

    // Penalize bins that leave a gap that can't host the next item (lookahead coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (pr - nxt) / cap;
        } else {
            score += 10.0 * (nxt - pr) / cap * (0.5 + progress);
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    }

    // Mild penalty when many bins are open and this bin is wasteful
    score += 0.05 * open_bins_count as f64 * norm_pr * (1.0 - progress);

    // Mean-residual coupling: prefer bins near the mean residual (balanced packing)
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: neutral base, penalized relative to good fits in existing bins
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: items sized 1..100, capacity 100.
    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    // Class 1: post_residual small (< 10) -> dead space, penalize hard.
    // Class 2: post_residual in "reusable" band [10, 30] -> mild reward.
    // Class 3: post_residual in [31, 60] -> neutral-ish.
    // Class 4: post_residual > 60 -> bin nearly full, mildly good.
    let post = post_residual as f64;
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 30 {
        score -= 15.0;
    } else if post_residual <= 60 {
        score -= 2.0;
    } else {
        score -= 8.0;
    }

    // Integer-division harmonic buckets of post_residual (mod arithmetic):
    // leftovers divisible by common item sizes (10, 20, 25, 50) are reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            // next item leaves another harmonic leftover
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 12.0;
            }
            if nxt_post < 10 {
                score += 10.0; // chain of dead space
            }
        } else {
            // next item cannot use this bin's leftover: leftover likely wasted
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a bin is fine early, wasteful late
    // or when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if fitting_bins_count > 0 {
            score += 80.0 + 120.0 * progress;
        } else {
            score += 20.0 * (1.0 - progress);
        }
    }

    // Prefer tighter bins overall (small deviation from mean residual).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Slight preference for bins that are already committed (avoid bin sprawl).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual) more aggressively than linear.
    if post_residual <= 5 {
        score -= 30.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open bins pressure: penalize using bins when many are open,
    // encouraging consolidation and delaying new bin creation.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise item forces a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: make empty bins mildly unattractive
    // unless the item would leave a very poor gap in existing bins.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 25.0;
        // if no other bin fits well, this becomes attractive via fitting_bins_count
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // Lookahead: if next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= (next_item_size as f64) {
        score -= 15.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual && post_residual > 0 {
        // next item cannot use the gap: penalize creating dead space
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates from mean
    // (use the bin that is already tight, keep loose bins loose).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fit (no dead space).
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this is an ideal chaining placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild bonus proportional to tightness of the chain.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Next item does NOT fit: post_residual becomes dead space.
            // Penalize proportionally to how much is wasted.
            score += 0.5 * post_residual as f64;
        }
    }

    // Compare against mean residual: placing into a bin with residual far from
    // the mean is either exploiting slack (good) or fragmenting a full bin (bad).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that can fit the item, prefer it
    // strongly to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when open bins exist and item fits reasonably.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // New bin is penalized unless it enables a perfect 2-step chain.
            if !(next_item_size > 0 && post_residual == next_item_size) && post_residual != 0 {
                score += 60.0;
            }
        }
        // A fresh bin is attractive if the item is large (leaves small residual).
        score += 0.3 * item_size as f64;
    }

    // Slight preference for tighter fits overall.
    score += 0.2 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.06;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Smooth normalized quantities
    let x = pr / cap;                       // normalized post residual
    let fit_frac = item_size as f64 / cap;  // normalized item size
    let next_frac = next_item_size as f64 / cap;

    // Base: reward tight fits (low post_residual), with a non-linear
    // polynomial shaping that penalizes both large and mid-range slack,
    // emphasizing small residuals more strongly late in the stream.
    let tightness = 1.0 - x;
    let poly = x * x * (1.0 + progress) - 0.5 * x * x * x; // smooth coupling
    let mut score = pr * (1.0 + 0.6 * poly) + 20.0 * (1.0 - tightness) * progress;

    // Penalize dead space: residual too small for the smallest plausible item,
    // using a smooth bump instead of a hard threshold.
    let dead = (10.0_f64.min(pr as f64) / 10.0) * (1.0 - (pr as f64 / 10.0).min(1.0));
    score += 8.0 * dead * (0.5 + progress);

    // Lookahead coupling: reward bins whose post-residual can still take the
    // next item (smooth logistic-like term, no piecewise constants).
    if next_item_size > 0 {
        let gap = pr - next_frac * cap;
        let compat = 1.0 / (1.0 + (-gap / 15.0).exp());
        score -= 6.0 * compat * next_frac;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate handling: normally penalized, but the penalty decays
    // smoothly with stream progress and with how poor the average fit is.
    if is_new_bin {
        let avg_fit = mean_residual / cap;
        let relief = (progress * 0.8 + avg_fit * 0.4).min(1.0);
        score += 25.0 * (1.0 - relief);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (>= 10 fits the smallest item) are worth keeping tight.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect closure, highly desirable
    } else if pr < 10 {
        score += 25.0; // dead space below minimum item size
    } else {
        // coarse class by integer division: 0=snug(10-24),1=mid(25-49),2=roomy(50+)
        let class = pr / 25;
        score -= class as f64 * 8.0;
        // exact half-capacity leftover is a harmonic sweet spot
        if pr == bin_capacity / 2 {
            score -= 12.0;
        }
        if pr % 10 == 0 {
            score -= 4.0; // round residual pairs well with decimal item sizes
        }
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual
    if next_item_size > 0 && next_item_size <= pr {
        let gap = (pr - next_item_size) as f64;
        score -= 15.0 - gap * 0.3; // best when next item closes this bin
    } else if next_item_size > pr && next_item_size > 0 {
        score += 5.0; // this bin cannot host the next item anyway
    }

    // Last chance: strongly prefer using the only bin that fits, avoid new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current bin is a bad fit
    if bin_residual == bin_capacity {
        // opening fresh is penalized mildly; offset by tight-fit benefits elsewhere
        score += 20.0 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin guarantees future flexibility
        }
    }

    // Tight fit reward: small post_residual relative to item size
    let fill_ratio = item_size as f64 / cap;
    score -= fill_ratio * 10.0;

    // Stream progression: late in stream, prefer closing bins aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (pr as f64) * 0.15;

    // Discourage spreading residual mass: bins far above mean residual are
    // better targets (consolidate emptiness)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fit, best possible
    } else if post_residual <= 10 {
        score += 60.0; // tiny gap, almost certainly dead space
    } else if post_residual <= 25 {
        score += 25.0;
    } else if post_residual <= 50 {
        score += 5.0;
    }

    // Reward tight fits (small relative waste).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from many open bins: prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for leaving large-but-unusable-for-next gaps.
        score += 8.0;
    }

    // Mean residual coupling: bins far below mean residual are good consolidation targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: make it moderately attractive only when item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        if item_size >= 70 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the lookahead item exactly fills the post-residual (perfect 2-step match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0); // exact match => -40, degrading with slack
    }

    // Penalize leaving dead space that no plausible next item can use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0; // blocks the lookahead item
    }

    // Relative-to-mean adjustment: bins tighter than average are good targets.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when residuals are large/fragmented,
    // but generally keep it slightly worse than a decent fit.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;

    // Base: penalize leftover dead space, with a superlinear penalty for
    // small, hard-to-fill residuals (wasted space that is nearly unusable).
    let mut score = post * (1.0 + 1.5 * (1.0 - post / cap).powi(3));

    // Tight fits are golden: reward small post_residual strongly.
    score -= 20.0 * (-post / 15.0).exp();

    // Lookahead: if the next item fits exactly into this bin's post_residual,
    // this is a perfect pair placement -- reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 12.0 * (-gap / 10.0).exp();
        }
        // If next item cannot fit in any residual after this placement,
        // penalize slightly to avoid trapping the stream.
        if nxt > post && nxt > mean_residual {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins => competition, mild preference for best fit only;
    // few fitting bins => conserve options, penalize using scarce fits lightly.
    if fitting_bins_count > 2 {
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // Global fragmentation pressure: if mean residual across open bins is
    // already low, opening a new bin is attractive; if mean residual is high,
    // prefer packing into existing space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New-bin candidate: subtract an offset that grows with fragmentation
        // pressure and stream progress (late in stream, consolidation matters).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let frag = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score -= 18.0 + 10.0 * frag + 8.0 * progress;
        // Don't open a new bin for small items that easily fit elsewhere.
        score += 0.25 * item;
        // If many bins already fit the item, opening new bins is wasteful.
        if fitting_bins_count > 0 {
            score += 6.0 * (fitting_bins_count as f64).min(5.0);
        }
    } else {
        // Reward filling bins whose residual is close to the item size
        // (residual utilization), scaled by how "full" the bin already is.
        let fill = 1.0 - resid / cap;
        score -= 8.0 * fill;
        // Mild penalty per open bin: consolidation pressure.
        score += 0.3 * (open_bins_count as f64).ln().max(0.0);
    }

    // Time horizon: early in the stream keep flexibility (prefer balanced
    // residuals), late in the stream prioritize closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0 * (post / cap - 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let t = item_size as f64 / cap;
    let p = step_index as f64 / (total_items.max(1) as f64);

    let mut score = r;

    // Reward tight fits: quadratic coupling between item size and residual shrinkage.
    score -= 45.0 * t * (1.0 - r / cap);

    // Penalize dead space quadratically (smooth, non-linear).
    score += 0.35 * r * r / cap;

    // Smooth stream-progress coupling: late in the stream, prefer filling bins tighter.
    score *= 1.0 + 0.25 * p * (1.0 - p);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * p;
    }

    // Lookahead: reward bins where the next item would also fit (chaining).
    if next_item_size > 0 && (next_item_size as f64) <= r {
        score -= 12.0 * (1.0 - (next_item_size as f64) / cap);
    }

    // Mild pull toward bins whose residual differs from the mean (avoid fragmentation).
    score += 0.08 * (mean_residual - r).abs();

    // New-bin candidate: penalize slightly so it is chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - p);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 define "dead space classes".
    // Residues 1..9 (non-decade) are harder to fill later; decade residuals (0 mod 10)
    // align with common item granularity and are rewarded.
    let pr = post_residual;
    let residue = (pr % 10) as f64;
    if pr > 0 {
        score += residue * 0.6;
    }

    // Integer-division thresholds: classify post_residual into harmonic bands.
    // Small residuals (< 20) are nearly dead space -> heavy penalty.
    if pr < 20 {
        score += 15.0;
    } else if pr < 40 {
        score += 5.0;
    } else if pr < 60 {
        score -= 3.0;
    } else {
        score -= 6.0;
    }

    // Perfect fit reward: exact decade closure or zero residual.
    if pr == 0 {
        score -= 40.0;
    } else if pr % 10 == 0 {
        score -= 8.0;
    }

    // Lookahead coupling: does post_residual accommodate next item harmonically?
    if next_item_size > 0 && pr >= next_item_size {
        // post_residual mod next_item_size small => next item likely closes the bin.
        let gap = pr - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else {
            score += (gap % 10) as f64 * 0.4;
        }
        // Reward bins whose residual stays in a "fillable" band for the lookahead.
        if pr - next_item_size <= 20 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Cannot host next item: penalize proportionally to how far off we are.
        score += (next_item_size - pr) as f64 * 0.15;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive
    // only when the item fits poorly everywhere (large dead-space creation here).
    if bin_residual == bin_capacity {
        // Base mild penalty so tight fits in open bins win.
        score += 5.0;
        // But if placing here would leave a bad harmonic class in any open bin,
        // empty bin becomes competitive: reward when item is large relative to capacity.
        let frac = item_size as f64 / bin_capacity as f64;
        score -= frac * 10.0;
        // If many bins are open with cluttered residuals, prefer fresh bin.
        if mean_residual > 40.0 {
            score -= 4.0;
        }
    }

    // Stream progression: early on, keep bins flexible (favor larger post_residual);
    // late in stream, aggressively close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.2 * (1.0 - progress)) * 0.1;
    score -= progress * 3.0;

    // Mean-residual coupling: if this bin's residual is far below mean, it is
    // an outlier nearly-full bin; finishing it is good.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.08;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    // Gaps below the minimum item size (1..10) are pure dead space.
    let dead = if post_residual < 10 { 60.0 } else { 0.0 };
    // Gaps below 25 are hard to fill for typical item sizes.
    let tight = if post_residual > 0 && post_residual < 25 { 15.0 } else { 0.0 };
    score += dead + tight;

    // Perfect fit bonus: strongly reward filling a bin completely.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins over new ones.
    let pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        score += pressure; // penalize new-bin candidate
    } else {
        score -= pressure * 0.5;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    }
    // If next item would NOT fit here but might fit elsewhere, mild penalty for wasting space.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Late in stream, tighten up: prefer tight fits even more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 0.0 + progress * (bin_residual - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits strongly (non-linear).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(6) * 20.0;

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= (1.0 - slack as f64 / bin_capacity as f64).powi(4) * 25.0;
        } else {
            // next item won't fit here: penalize leftover dead space
            score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;
        }
    }

    // Compare residual against mean residual of open bins: prefer filling worse-shaped bins.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item is large relative to capacity
    // or no good fit exists. Penalize opening new bins by default.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64).powi(2) * 40.0;
        score += 55.0 - large_item_bonus;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 20.0; // next item pairs well with a fresh bin
        }
    }

    // Slight preference for consolidating bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream (dynamic time horizon)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual)
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * 30.0;

    // Reward filling bins nearly exactly
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strong preference to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0 + 15.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits into the post-residual, reward leaving room
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // extra reward if next item exactly consumes remainder
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else {
            // penalize leaving a sliver the next item cannot use
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += (next_item_size as f64 - waste) * 0.35;
            }
        }
    } else {
        // last item: just fill as much as possible
        score -= 10.0;
    }

    // Global state coupling: many open bins with large mean residual -> prefer
    // consolidating into existing bins rather than opening new ones
    let crowd = open_bins_count as f64;
    let mean_r = mean_residual;
    if bin_residual == bin_capacity {
        // candidate for a NEW bin
        let consolidation_pressure = crowd * (mean_r / bin_capacity as f64);
        score += 18.0 + consolidation_pressure * 10.0;
        // opening a new bin is more acceptable early in the stream
        score -= 25.0 * (1.0 - progress);
        // never open a new bin if a perfect fit exists elsewhere is handled by score comparison
        if item_size == bin_capacity {
            score -= 200.0; // fresh bin for full-size item is perfect
        }
    } else {
        // existing bin: bonus for using bins with below-average residual (drier bins)
        let rel = bin_residual as f64 - mean_r;
        score -= rel * 0.25;
        // slight preference for bins that are already quite full
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fill * 8.0;
    }

    // Non-linear coupling: penalize mid-range dead space quadratically
    if post_residual > 0 && post_residual < 50 {
        let p = post_residual as f64;
        score += (p - 25.0) * (p - 25.0) * 0.01;
    }

    // Mild time-dependent aggression: late in stream, be greedier about tight fits
    score -= 10.0 * progress * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    let mut score = pr;

    // Smooth polynomial coupling of post residual with stream progress.
    // Early stream: prefer filling bins tightly (penalize large residuals mildly).
    // Late stream: strongly reward low post residual to consolidate.
    let poly = x * (1.0 - x); // peaks at x=0.5, zero at full/empty
    score += 18.0 * poly * (1.0 - progress) * (1.0 - progress);
    score -= 25.0 * (1.0 - x) * (1.0 - x) * progress;

    // Non-linear penalty for leaving residual close to the next item size mismatch.
    if next_item_size > 0 {
        let gap = (x * cap - next_item_size as f64).abs();
        score += 0.35 * gap * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // Mild penalty when many bins are open and this placement wastes space.
    score += 0.05 * (open_bins_count as f64) * x * x * (1.0 + progress);

    // Reward bins that become perfectly full.
    score -= 15.0 * (1.0 - x) * (1.0 - x) * (1.0 - x) * 0.0; // placeholder-free term
    score -= 12.0 * (1.0 - x).powi(3);

    // Slight preference to keep residuals away from mean (diversity of sizes).
    score += 0.02 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let class = (post_f / cap * 10.0).floor(); // 0..=10 harmonic class

    // Dead space in the smallest classes is nearly worthless -> penalize mildly.
    if class <= 1.0 {
        score += 6.0;
    } else if class <= 2.0 {
        score += 2.0;
    } else if class >= 9.0 {
        // Nearly-empty residual: excellent future flexibility.
        score -= 4.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0; // perfect pairing
        } else {
            score -= 12.0 * (1.0 - slack as f64 / cap);
        }
    } else if next_item_size > post_residual {
        // Next item can't use this residual; residual quality matters less.
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits (best-fit flavor).
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate (empty bin): penalize unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = (mean_residual / cap).max(0.0);
        score += 20.0 - 18.0 * crowding.min(1.0);
        // Early stream: opening bins is fine; late stream: conserve.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * (1.0 - progress);
    }

    // Modulo harmonic bonus: residual that is a multiple of common item
    // granularities (10/20/25) is more reusable.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 3.0;
    }

    // Slight pull toward bins below mean residual (balance residuals).
    score += 0.05 * (post_f - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size ~10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Small but still usable gaps: moderate penalty to prefer larger leftovers.
        score += 12.0;
    }

    // Reward tight fits (near-perfect packing).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).max(0.0);

    // Last-chance bin: strongly favor using the only bin that fits, to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins early on;
    // encourage closing out bins when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Compare against mean residual: penalize bins that would be left far below
    // the average residual (wasteful extraction of space from a well-filled bin).
    score += 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Lookahead: if the next item fits exactly in the post residual, reward this
    // placement (chaining good fits).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive
    // only when the item is large and no tight open fit exists.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.3 * item_size as f64;
        if fitting_bins_count == 0 {
            score = 0.0; // no alternative, new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact or near-exact match with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        // Perfect fit for the next item -> strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement: reward, scaled by tightness.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize leftover dead space, worse when gap small
            // (wasted space that almost could have held it).
            score += 10.0 + 0.5 * gap;
        }
    } else {
        // Last item: prefer minimal leftover.
        score -= 20.0;
    }

    // Relative to mean residual: bins below mean residual are already tight,
    // prefer filling them further (their post_residual is naturally small,
    // so add penalty for bins far above the mean to encourage balance).
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.15 * (res - mean_residual);
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty: discourage opening new bins when an open bin fits decently.
        score += 40.0;
        // But if existing bins would leave lots of unusable space, new bin becomes better.
        // Estimate: if the best post_residual among fitting bins is small (very tight),
        // that's fine; if all fits are poor (post_residual large relative to item),
        // open a new bin. We approximate via item vs bin_residual relationship.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            // New bin leaves residual = capacity - item; if next item fits there, mildly good.
            if post_residual >= next_item_size {
                score -= 15.0;
            }
            // If open bins are nearly exhausted (mean residual small), new bin is cheap.
            if mean_residual < item_size as f64 {
                score -= 30.0;
            }
        }
        // Late in stream with many open bins: consolidate instead of opening.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference for tighter fits overall (non-linear waste penalty).
    let waste_frac = res / bin_capacity as f64;
    score += 5.0 * waste_frac * waste_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.9 {
        score -= 40.0 * fit_ratio;
    } else if fit_ratio > 0.7 {
        score -= 20.0 * fit_ratio;
    }

    // Penalize leaving small, hard-to-use dead space (residuals 1..=10 are nearly useless).
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Dead-end for next item: penalize proportionally to how close we were.
            score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
        // Exact pairing bonus: item + next item perfectly fill residual.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty discourages opening bins unnecessarily.
        score += 30.0;
        // But if existing bins would leave lots of dead space, opening a fresh bin is fine.
        score -= 0.3 * mean_residual;
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // If many bins compete for this item, a new bin is less needed.
        score += 4.0 * fitting_bins_count as f64;
    }

    // Mild preference for bins with larger residuals among similar fits (keeps small holes consolidated).
    score -= 0.05 * bin_residual as f64;

    // Slight penalty tied to crowding of open bins to discourage spreading items too thin.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: quadratic waste penalty (tight fits win).
    let mut score = x * x;

    // Smooth non-linear coupling with stream progress: later in the stream,
    // waste becomes more costly (fewer chances to fill gaps), so inflate penalty.
    let progress_coupling = 0.35 * progress * (1.0 - x * x);
    score += progress_coupling * x;

    // Reward bins whose residual matches the item size well (smooth best-fit kernel).
    let fit_kernel = (1.0 - x).powi(2);
    score -= 0.25 * fit_kernel;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 0.8 * (1.0 - x);
    }

    // Compare with next item: if post_residual fits next item, reward (chaining);
    // if post_residual is too small for next item, penalize (dead space).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            let slack = (pr as f64 - nx) / cap;
            score -= 0.3 * (1.0 - slack).max(0.0);
        } else {
            score += 0.4 * (nx - pr as f64) / cap;
        }
    }

    // New-bin candidate handling: an empty bin has huge post_residual; make it
    // attractive only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many items remain.
        score = 0.9 + 0.3 * progress;
        // If several bins fit, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
        }
        // If mean residual is large, open bins are wasteful; opening new bin ok.
        score -= 0.2 * (mean_residual / cap).min(1.0);
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.02 * (open_bins_count as f64).sqrt() * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual (modulo arithmetic) ---
    let pr = post_residual;
    let class = pr % 10;                       // harmonic class of leftover space
    let quanta = pr / 10;                      // how many 10-units of usable space remain

    // Perfect fit: strongly reward exact closure of the bin.
    if pr == 0 {
        score -= 60.0;
    }
    // Near-perfect fits (tiny dead space classes) get graded rewards.
    match class {
        0 => score -= 18.0 + 2.0 * quanta as f64,   // class 0: residual is a clean multiple of 10
        1 | 2 => score -= 10.0,                     // nearly clean classes
        9 | 8 => score -= 8.0,                      // almost full, minimal waste
        _ => score += (class as f64) * 0.8,         // awkward middle classes: penalize
    }

    // --- Integer-division thresholds: does the lookahead item fit in the leftover? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item nests perfectly into this residual: big reward.
            score -= 25.0;
            // Extra reward if next item exactly consumes the leftover (chained perfect fit).
            if next_item_size == pr {
                score -= 20.0;
            } else {
                // Penalize by the awkwardness of the post-post residual class.
                let p2 = (pr - next_item_size) % 10;
                score += p2 as f64 * 0.5;
            }
        } else {
            // Leftover too small for lookahead: dead space risk, penalize proportionally.
            score += (next_item_size - pr) as f64 * 0.15;
        }
    } else {
        // Last item: prefer closing bins as tightly as possible.
        score -= pr as f64 * 0.5;
    }

    // --- Last-chance bin logic (fitting_bins_count == 1) ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only open bin that fits; opening a new bin is costly, so reward usage
        // unless the fit is terrible (large awkward residual).
        score -= 15.0 + 0.1 * (bin_residual - item_size) as f64;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: base cost of consuming a new unit of capacity.
        score += 45.0;
        // Late in the stream, opening new bins is more acceptable (fewer future regrets).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If many bins are open, consolidation is preferable; penalize new bins more.
        score += 2.0 * open_bins_count as f64;
        // Large items favor fresh bins (less fragmentation risk).
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        // If the next item is large too, a fresh bin can host both.
        if next_item_size > 0 && item_size + next_item_size as u32 <= bin_capacity {
            score -= 15.0;
        }
    }

    // --- Coupling with mean residual: prefer bins whose residual deviates favorably ---
    let dev = post_residual as f64 - mean_residual;
    // Prefer placing into bins with residual BELOW the mean (tighter bins get emptied),
    // but avoid creating extreme dead space far above the mean.
    if dev < 0.0 {
        score += dev * 0.3;      // negative dev lowers score -> favor tight bins
    } else {
        score += dev * 0.15;     // above-mean residual mildly penalized
    }

    // --- Small global tie-breakers on harmonic quanta ---
    score -= quanta as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1, but realistically small gaps) are wasted.
    // Penalize gaps in the "dead zone" that no typical item can use.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 40.0; // pure dead space, unusable
        } else if post_residual <= 25 {
            score += 15.0; // hard to fill
        } else if post_residual <= 40 {
            score -= 5.0; // moderately useful gap
        } else {
            score -= 10.0; // roomy residual, still valuable
        }
    } else {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 60.0;
    }

    // Reward tight fits relative to the item size (high fill ratio).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise we are forced to open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening
    // another one; prefer consolidating into existing bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 20.0 + 4.0 * open_bins_count as f64;
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 15.0;
        }
        // Late in the stream, prefer reusing bins over spawning new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    } else {
        // Existing bin: mild reward proportional to open bins count
        // (consolidation pressure), scaled by how well the residual
        // compares to the mean residual across open bins.
        if (bin_residual as f64) < mean_residual {
            score -= 8.0; // this bin is tighter than average, good
        } else {
            score += 4.0;
        }
        // Lookahead: if the next item fits the post-residual exactly-ish,
        // reward this placement for enabling a good follow-up fit.
        if next_item_size > 0 && post_residual >= next_item_size {
            let lookahead_tightness = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * lookahead_tightness;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 6.0; // next item can't use this gap
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact chaining of next item into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        // Perfect 2-item fill: post_residual == next_item_size leaves zero waste
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 40.0 - chain_waste * 0.8;
    } else if next_item_size > 0 {
        // Next item cannot chain: penalize proportionally to how far off it is
        let miss = if next_item_size > post_residual {
            (next_item_size - post_residual) as f64
        } else {
            0.0
        };
        score += miss * 0.5;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 10.0 / (1.0 + tightness);

    // Relative to mean residual: prefer bins with less residual than average
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin opening unless nothing fits well
    if bin_residual == bin_capacity {
        let base = 30.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += base - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score += 5.0; // new bin will still chain fine, less urgency
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1).
    let t = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit reward: strongly favor bins that end exactly or nearly full.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize creating "awkward" residual space: residuals that are too small
    // for typical future items but too large to ignore.
    let awkward = (post_residual as f64).tanh() * (1.0 - (post_residual as f64 / bin_capacity as f64));
    score += 8.0 * awkward;

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this placement (chaining); otherwise penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 18.0 * chain;
        } else {
            score += 6.0;
            // Extra penalty if the next item also fails to fit residual-wise
            // anywhere else, suggesting this bin should stay flexible.
            if next_item_size > bin_residual {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // favor using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * (1.0 - t);
    }

    // Reward filling bins that are already well-used (low residual relative to mean).
    if bin_residual < bin_capacity {
        let tightness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 15.0 * tightness * tightness;
    }

    // Penalize spreading across many open bins: encourage consolidation when
    // the number of open bins is large relative to stream progress.
    let pressure = open_bins_count as f64 / (1.0 + t * 10.0);
    score += pressure * 0.8;

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (keeps the bin pool homogeneous), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate handling: an empty bin should win only when no open
    // bin gives a decent fit, or when the item is large and open bins are scarce.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0 && mean_residual > item_size as f64 * 1.2;
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if decent_fit_exists && !large_item {
            // Open bins can absorb it: discourage new bin.
            score += 25.0;
        } else {
            // Encourage opening a fresh bin for a clean start.
            score -= 12.0 + 10.0 * (1.0 - t);
        }
        // Late in the stream, prefer consolidating into existing bins.
        score += 20.0 * t;
    }

    // Mild global noise-free smoothing: scale everything by a small factor
    // to keep scores in a comparable range across phases.
    score *= 1.0 + 0.1 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: reward tight fits quadratically (small post residual is good).
    let mut score = pr as f64;

    // Smooth non-linear coupling: waste penalty grows as stream progresses
    // (late in the stream, residual space is less likely to be used).
    let urgency = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 60.0 * urgency * x * x;

    // Perfect fit bonus: strongly favor filling a bin exactly.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead coupling: if the next item cannot fit the post residual,
    // this placement likely strands space; penalize smoothly.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 40.0 * gap * (1.0 + urgency);
        // Bonus when the next item fits snugly into the post residual.
        if next_item_size <= post_residual {
            let snug = 1.0 - ((pr - next_item_size as f64) / cap);
            score -= 25.0 * snug * snug;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin for a marginal gain.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: neutral-ish baseline; discourage early opening,
    // but allow it late when existing residuals are large and fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).min(1.0);
        score = 30.0 + 70.0 * (1.0 - urgency) - 50.0 * urgency * fragmentation * fragmentation;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 30.0 * urgency; // existing bins can't take the next item either
        }
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    // (encourage consolidation around average fill).
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (open_bins_count as f64).sqrt().ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over

    // Integer-division thresholds on post_residual: bins are "harmonically useful"
    // if leftover can host a future small item (residual >= 10..=50 useful band).
    let useful = if post_residual >= 50 { 2.0 } else if post_residual >= 20 { 1.0 } else if post_residual == 0 { 3.0 } else { 0.0 };

    // Reward exact fits and harmonic completions (post_residual divides capacity evenly)
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else if bin_capacity % post_residual.max(1) == 0 && post_residual <= 50 {
        score -= 15.0; // harmonic subdivision possible (e.g. 50, 25, 20, 10)
    }

    // Modulo-class coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // lookahead fit: strong reward, weighted by how snugly it fits
        let snug = (post_residual - next_item_size) as f64;
        score -= 25.0 + 20.0 * (1.0 - snug / cap);
    } else if next_item_size > 0 {
        // next item cannot use this leftover: penalize dead space quadratically in the
        // unusable band (residual < smallest plausible item)
        if post_residual < 10 {
            score += 30.0 * (1.0 - frac);
        } else {
            score += 5.0 * (1.0 - frac);
        }
    }

    // Last-chance bin: if only one bin fits, strongly prefer using it over opening new
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: fresh empty bin gets neutral baseline; discourage
    // opening new bins when current fit is decent, encourage when fit is terrible.
    if bin_residual == bin_capacity {
        // baseline for a new bin: its post_residual equals capacity; compare against
        // quality of the current placement via the useful band.
        score = 0.5 * cap; // neutral reference
        if useful >= 2.0 {
            score += 10.0; // current bin placement leaves large useful residual -> prefer it
        }
        if fitting_bins_count <= 1 && bin_residual < bin_capacity {
            score -= 20.0; // (defensive; not triggered here)
        }
        // early stream: allow new bins more freely
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    } else {
        // Prefer bins with low residual relative to mean (tight packing)
        score += 3.0 * (mean_residual - pr) / cap;
        // Small penalty for spreading across many bins
        score += 0.3 * open_bins_count as f64;
    }

    // Tight-fit bonus: item fills bin to within a small harmonic window
    if post_residual <= 10 && post_residual > 0 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
    // smallest plausible item (<= 10) are wasted forever.
    if post_residual < 10 {
        score += 60.0;
    }

    // Mild penalty for residuals that fit only very few future items
    // (unusable gap in the 10..=20 range).
    if post_residual >= 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward tight fits strongly: perfect or near-perfect fill.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement is excellent (chained fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize leaving a gap that neither fits the next item nor is useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many
    // bins are already open; opening a new bin is penalized proportionally.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 20.0 + 3.0 * open_bins_count as f64;
        // Late in the stream, avoid opening new bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // Slight reward for packing into existing bins as open count grows.
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is already below average (well-filled bins):
    // placing into them preserves larger residuals elsewhere.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Prefer the bin that leaves post_residual closest to a "reusable" size
    // divisible into common item ranges (multiples of 10).
    let waste = post_residual % 10;
    score += waste as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Perfect chaining bonus
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Penalize residuals too small for next item (dead space for lookahead)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize residuals below the minimum item size (unusable dead space)
    if post_residual < 1 && post_residual > 0 {
        score += 50.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect closure
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a great
    // lookahead match; slightly discourage when open bins are getting full.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64;
        if next_item_size > 0 {
            let chain_gap = (bin_capacity as f64 - item_size as f64 - next_item_size as f64).abs();
            score -= 25.0 * (1.0 - chain_gap / bin_capacity as f64).max(0.0);
        }
        if fitting_bins_count > 0 {
            score += 10.0; // discourage opening when any bin fits
        }
        if mean_residual > item_size as f64 {
            score += 5.0;
        }
    }

    // Mild preference for fuller bins relative to the fleet mean residual
    score += 0.3 * (mean_residual - post_residual as f64);

    // Early stream: be a bit more conservative (keep bins open for flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Reward using residual that matches item size relative to bin fill.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // Lookahead: if the next item fits in the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 10.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
    } else if next_item_size > 0 {
        // Penalize leaving residual that no future item can use well.
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins exist and could fit,
    // unless residual fragmentation is severe.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let frag = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin more attractive late in stream or when mean residual is small.
        score += 25.0 - 20.0 * frag - 10.0 * progress;
        if post_residual as f64 > mean_residual {
            score -= 8.0; // fresh bin keeps large usable residual
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = fitting_bins_count as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let base = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm) * 16.0; // bump peaking at half-full
    let coupling = base * (1.0 + 3.0 * progress * progress) * 2.0;
    score -= coupling;

    // Lookahead: reward residual that still fits the next item, smoothly scaled
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = ((pr - nxt) / cap).powi(2);
            score -= (1.0 - slack) * (6.0 + 8.0 * progress);
        } else {
            let gap = ((nxt - pr) / cap).powi(2);
            score += gap * 10.0 * (1.0 + progress);
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= (1.0 - pr_norm) * 20.0;
    }

    // Penalize when many bins fit (competition) mildly; reward scarce-fit bins
    if fit >= 1.0 {
        score += (fit - 1.0).ln().max(0.0) * 3.0;
        if fit <= 2.0 {
            score -= 5.0 * (2.0 - fit) * (0.5 + progress);
        }
    }

    // Mean-residual drift: penalize bins far from the fleet mean residual (outliers waste space)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 8.0 * (1.0 - progress);

    // New-bin candidate: make empty-bin attractive only when current item is large
    // and post_residual would be very small (good utilization) or stream is early
    if bin_residual == bin_capacity {
        let util = item_size as f64 / cap;
        score -= 12.0 * util * util * (1.0 + 2.0 * (1.0 - progress));
        score += 6.0 * progress * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 as "dead-space classes".
    // Residuals that are small multiples of 10 are more reusable by typical items.
    let residue_class = post_residual % 10;
    let harmonic_bonus = match residue_class {
        0 => 6.0,          // perfectly harmonic residual
        1 | 9 => 3.0,
        2 | 8 => 1.5,
        5 => 2.0,          // half-class, moderately reusable
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Integer-division threshold: how many "unit slots" of size 10 remain
    let slots = post_residual / 10;
    score -= slots as f64 * 1.2;

    // Tight fit reward: post_residual below 10 is near-perfect packing
    if post_residual < 10 {
        score -= 15.0;
    } else if post_residual < 20 {
        score -= 8.0;
    } else if post_residual > 60 {
        score += 10.0; // huge leftover: wasteful placement
    }

    // Lookahead coupling: if next item fits exactly (or well) into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_tight = (post_residual - next_item_size) as f64;
        score -= 12.0 - next_tight * 0.15;
        // harmonic exactness for the pair
        if (post_residual - next_item_size) % 5 == 0 {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this bin's leftover: mild penalty scaled by leftover size
        score += post_residual as f64 * 0.05;
    }

    // Last-chance bin: only bin that fits the item -> strong reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: empty bin. Post_residual = capacity - item_size.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when item is large and leftovers elsewhere are bad
        let pressure = (mean_residual - post_residual as f64).max(0.0);
        score += 5.0 + pressure * 0.3;
        // large items into fresh bins is fine; small items waste capacity
        if item_size < 30 {
            score += 25.0;
        } else if item_size >= 60 {
            score -= 5.0;
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Mild preference for filling bins that are already low relative to mean residual
    let frac = post_residual as f64 / bin_capacity as f64;
    score += (frac - 0.5) * 4.0;

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are nearly worthless.
    if post_residual < 10 {
        score += 40.0; // tiny unusable gap -> strong penalty
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    } else {
        // Larger residuals are useful; reward proportionally.
        score -= 0.05 * (post_residual as f64 - 35.0);
    }

    // Reward tight fits (post_residual small relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // over opening new ones (only when this bin is a genuine candidate).
    if bin_residual != bin_capacity {
        score -= 0.8 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item can fit into the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit but post_residual is small dead space, extra penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // Mean residual context: if this bin is much emptier than average,
    // it is a good consolidation target.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Slight preference to fill bins earlier in the stream to close them out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * fill_ratio;

    // New-bin candidate: keep it competitive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward if next item exactly fills post_residual ---
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            // Perfect 2-step pairing: both items consume this bin exactly.
            score -= 60.0;
        } else if slack <= 10.0 {
            // Near-perfect pairing.
            score -= 25.0 * (1.0 - slack / 10.0);
        } else {
            // Mild reward proportional to how much of post_residual next item absorbs.
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: post_residual is likely dead space.
        // Penalize small unusable leftovers relative to the minimum item size.
        if post_residual < 10 {
            score += 30.0 * (10.0 - post_residual as f64) / 10.0;
        }
    }

    // --- Mean-residual coupling: prefer bins whose residual tracks the fleet mean ---
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // --- Last-chance bin: strongly favor using the only bin that fits ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no open bin offers a good fit.
        // Base cost of consuming fresh capacity; slight decay late in the stream
        // (open bins are cheap to keep filling when few remain).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 25.0 * (1.0 - progress);
        // If the next item is large, a fresh bin gives flexibility.
        if next_item_size > 50 {
            score -= 12.0;
        }
        // If many bins are open, discourage spreading further.
        score += 2.0 * open_bins_count as f64;
        // If this bin is the only fitting option, new bin loses to it.
        if fitting_bins_count == 1 {
            score += 45.0;
        }
    }

    // --- Waste shaping: quadratic penalty on tiny leftovers (dead space) ---
    if post_residual > 0 && post_residual < 5 {
        score += 8.0 * (5 - post_residual) as f64;
    }

    // --- Prefer tighter fits generally: reward high fill ratio ---
    let fill = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fit is a jackpot.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tightness = next_item_size as f64 / post_residual as f64;
        score -= 18.0 * chain_tightness;
    }
    // If next item cannot fit in post-residual but could fit elsewhere, mild penalty for wasting space.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate logic: opening a new bin wastes capacity when decent fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins more early on (many future items to fill them) unless item is huge.
        let item_burden = item_size as f64 / bin_capacity as f64;
        score += 20.0 * (1.0 - progress) - 15.0 * item_burden;
        // If no existing bin fits at all, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        // Few open bins and large mean residual elsewhere: discourage hoarding a new bin.
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Global state coupling: prefer bins whose residual deviates from the mean when we are filling well.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late-stream urgency: consolidate more aggressively as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 12.0 * progress * fit_ratio;

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = post_norm.powf(1.5 + 1.5 * progress);

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in the stream, small residuals are worth more (tighter packing)
    let coupling = post_norm * (1.0 - post_norm) * (0.25 + 0.75 * progress);
    score += 2.0 * coupling;

    // Penalize residuals that are too large to be useful later, scaled by progress
    let dead = (post_norm - 0.5).powi(2);
    score += 1.5 * dead * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 0.8 + 0.6 * (nxt / cap) * (1.0 - progress);
        } else {
            score += 0.4 * (1.0 - post / nxt.max(1.0)) * (0.5 + progress);
        }
    }

    // Mild penalty for spreading across many open bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress) / (1.0 + mean_residual / cap);

    // New-bin candidate: keep it attractive only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 1.2 - 0.8 * progress;
        if fitting_bins_count <= 1 {
            score -= 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 (dead-space classes)
    let res_mod = post_residual % 10;
    let res_class: f64 = match res_mod {
        0 => -6.0,          // perfectly divisible residual: highly reusable
        1 | 9 => 1.5,       // near-full dead slivers
        2 | 8 => 0.5,
        3 | 7 => -0.5,
        4 | 6 => -1.0,
        _ => 0.0,           // 5: half-class, neutral
    };
    score += res_class;

    // Integer-division thresholds on post_residual
    let q = post_residual / 10; // how many 10-slots remain
    score -= (q as f64).powf(0.85) * 2.2;

    // Tight fit reward: post_residual small relative to item
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= (1.0 / (1.0 + tightness)) * 4.0;

    // Harmonic coupling with next item: does post_residual admit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // bonus scaled by how much slack remains after the next item too
            let post2 = post_residual - next_item_size;
            score -= 5.0 + (post2 % 10) as f64 * 0.15;
            // extra harmonic bonus if post2 lands on a divisible class
            if post2 % 10 == 0 { score -= 2.0; }
            if post2 % 5 == 0 { score -= 1.0; }
        } else {
            // next item won't fit here: penalize proportional to leftover gap
            let gap = next_item_size - post_residual;
            score += (gap as f64).sqrt() * 1.8;
        }
    } else {
        // last item: prefer filling bins as tightly as possible
        score -= 3.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    } else if fitting_bins_count > 1 {
        score += 0.4 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 12.0;
        // open a new bin when existing residuals are poor harmonic matches
        let frac = mean_residual / cap;
        if frac < 0.25 { score -= 6.0; }               // existing bins nearly full anyway
        if next_item_size > 0 && next_item_size >= post_residual { score += 2.0; }
        // early stream: more willing to open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 2.0;
        // many open bins: discourage spreading
        score += 0.5 * (open_bins_count as f64).log2().max(0.0);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += (bin_residual as f64 - mean_residual) * 0.03;

    // Capacity-fraction class of the item itself
    let item_frac = item_size as f64 / cap;
    if item_frac > 0.8 { score -= 1.0; }   // huge items: place anywhere it fits
    else if item_frac < 0.2 { score += 0.8; } // tiny items: keep big slots free

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Non-linear penalty on tiny gaps relative to item size scale.
    if post_residual > 0 && post_residual < item_size as f64 * 0.25 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual) with a superlinear bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else {
        score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new one is cheaper.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when there are already many open bins.
        score += 5.0 + 10.0 * pressure;
        // But if the item is large relative to typical residuals, opening fresh is fine.
        if item_size as f64 > mean_residual {
            score -= 12.0;
        }
        // If next item would fit in the fresh bin alongside, mild bonus.
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= bin_capacity as f64 {
            score -= 5.0;
        }
    } else {
        // Existing bin: slight reward when pressure is high (reuse bins).
        score -= 3.0 * pressure.min(3.0);
        // Lookahead: if next item fits exactly in post_residual, big bonus.
        if next_item_size > 0 && next_item_size as u32 == post_residual {
            score -= 35.0;
        } else if next_item_size > 0 && next_item_size as u32 > post_residual {
            // Next item won't fit here; penalize leaving a gap next item can't use.
            score += 8.0;
        }
    }

    // Mean residual coupling: prefer bins whose post_residual stays near the mean
    // (keeps bin population homogeneous and usable).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Late in the stream, tighten up: avoid leaving any residual.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact / near-exact match of post_residual
    // with the next item's size (chains placements perfectly).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // perfect chain: bin becomes exactly reusable
        } else if diff <= 5.0 {
            score -= 40.0 - 4.0 * diff;
        } else {
            // penalize post_residual that is uselessly larger than next item
            score += diff.min(30.0) * 0.6;
        }
        // if next item cannot fit in post_residual at all, slight penalty
        if post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Reward very tight fits (small dead space) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: bins with residual well below mean are
    // "almost full" -> good to fill them now.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 20.0 * rel;

    // New-bin candidate: it has full residual; make it unattractive unless
    // item is huge relative to capacity (then opening fresh is fine).
    if bin_residual == bin_capacity {
        score += 35.0 - 0.25 * item_size as f64;
        // late in the stream, prefer consolidating into open bins
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // mild pressure to keep number of open bins in check
    score += 1.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Exact fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose leftover can host the next item exactly or well
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0; // chain exact fit
        } else if post_residual >= next_item_size {
            let nl = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * nl * nl;
        } else {
            // leftover too small for next item: penalize proportional to wasted space
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Penalize small unusable leftovers (< 10) that block future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer new bin only when open bins fit poorly
    if bin_residual == bin_capacity {
        // Baseline cost of opening a bin
        let mut new_bin_score = 55.0 + post_residual as f64;
        // Early in stream: cheaper to open bins (build diversity of residual sizes)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score -= 30.0 * (1.0 - progress);
        // If many open bins with slack, opening new is less attractive
        new_bin_score += 2.0 * (open_bins_count as f64).ln().max(0.0);
        // If mean residual is large (lots of slack around), opening new bins is wasteful
        new_bin_score += 0.4 * mean_residual;
        // If item is large relative to capacity, a fresh bin is fine
        new_bin_score -= 0.3 * item_size as f64;
        score = score.max(new_bin_score) * 0.0 + if bin_residual == bin_capacity { new_bin_score } else { score };
    }

    // Mild penalty for spreading across too many bins when many are open
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let norm = pr / bin_capacity as f64;
    let poly = norm * norm * (1.0 + progress) + norm * (1.0 - progress);
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses.
    let tightness = 1.0 - norm;
    score -= 25.0 * tightness * (1.0 + progress * progress);

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (pr - nx) < 0.0 && pr > 0.0 {
            score += 15.0 * (pr / nx) * (1.0 + progress);
        } else {
            score -= 8.0 * (1.0 - (pr - nx) / bin_capacity as f64);
        }
    }

    // Last-chance bin bonus.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += (open_bins_count as f64).ln() * 2.0 * progress;

    // Deviation from mean residual: prefer bins near mean to balance load.
    score += 0.3 * ((pr - mean_residual) / (mean_residual + 1.0)).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: modular arithmetic on capacity fractions ---
    // Residuals divisible by 10 (harmonic with the classic item grid) are more reusable.
    let h10 = (post_residual % 10) as f64;
    score += h10 * 1.5; // penalize non-harmonic leftovers

    // Residuals divisible by 20 are even better (coarser harmonic class)
    if post_residual % 20 == 0 {
        score -= 4.0;
    }
    // Perfect fill is ideal
    if post_residual == 0 {
        score -= 15.0;
    }

    // Integer-division threshold classes on post_residual
    let class = post_residual / 10; // 0..=10
    score += (class as f64).powi(2) * 0.35; // quadratic waste penalty

    // --- Lookahead coupling: does next item fit into the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or nearly: strong reward
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - slack * 0.25;
        } else if next_item_size <= bin_residual {
            // next fits only if we do NOT place here -> penalize this placement
            score += 6.0;
        }
    }

    // --- Last-chance bin: if this is the only bin that fits, prefer using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost plus pressure to reuse open bins
        score = (bin_capacity as f64) * 0.9 + open_bins_count as f64 * 0.5;
        // Late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
        // If item is huge relative to capacity, new bin is more acceptable
        score -= (item_size as f64 / bin_capacity as f64) * 4.0;
        // If mean residual is small, open bins are nearly full anyway
        if mean_residual < item_size as f64 {
            score -= 6.0;
        }
    } else {
        // Reward tightness relative to mean residual: prefer bins tighter than average
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    // Small bonus for filling larger fraction of the bin
    score -= (item_size as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=100,
    // but conservatively < 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small to fit the lookahead item (k=2) are likely dead space too.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over
    // opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another one.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to number of open bins and progress.
        score += 15.0 + 3.0 * open_bins_count as f64 + 20.0 * progress;
        // But if the current bin would leave a dead gap, opening a new bin becomes attractive.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 35.0;
        }
    } else {
        // Mild pressure to consolidate into fewer bins when many are open.
        score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        // Perfect 2-chain: residual exactly fits next item -> huge reward.
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Next item fits, but leaves slack; reward proportional to how snug.
            let slack_after_next = post - nxt;
            score -= 20.0 - 0.35 * slack_after_next;
            // Extra reward if the chain is tight (slack small).
            if slack_after_next < 10.0 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here: penalize more when post_residual is small
            // (wasted dead space that nothing useful can use).
            let gap = nxt - post;
            score += 0.30 * gap;
        }

        // Coupling with mean residual: prefer bins whose post-residual tracks
        // the fleet average (keeps bin pool homogeneous for future items).
        let dev = (post - mean_residual).abs();
        score += 0.10 * dev;
    } else {
        // Last item: just minimize waste, mild.
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when open bins
    // look bad; scale penalty down as stream matures or bins pile up.
    if bin_residual == bin_capacity {
        let maturity = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(1.0);
        score += 25.0 - 8.0 * maturity - 1.5 * pressure;
        // If no open bin can fit at all, opening is fine: cancel penalty.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild preference for tighter existing bins overall.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let residual = bin_residual as f64;
    let fill_ratio = item_size as f64 / residual.max(1.0);
    score -= 25.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: reward if the next item fits exactly in the post-residual,
    // penalize if post-residual is awkward relative to the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post_residual as f64 - nxt;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // post-residual too small for next item: penalize proportionally to waste
            score += 8.0 * (1.0 - post_residual as f64 / nxt.max(1.0));
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Many open bins: discourage spreading across too many bins (encourage consolidation).
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Compare residual to mean residual: placing in a below-average-residual bin
    // (tighter bin) is good; placing in a very loose bin wastes capacity.
    if bin_residual != bin_capacity {
        score += 3.0 * (residual - mean_residual) / bin_capacity as f64;
    }

    // Time horizon: late in the stream, be more conservative with new bins;
    // early on, opening bins is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure that grows with progress
        // and with the number of already-open bins.
        score += 15.0 + 25.0 * progress + 1.5 * open_bins_count as f64;
        // If no open bin fits at all (this is the only candidate), it must be chosen.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        // Early stream with few bins: opening a fresh bin is more acceptable.
        if progress < 0.3 && open_bins_count < 3 {
            score -= 10.0;
        }
    }

    // Small dead-space penalty scaled by how unusable the leftover is for
    // typical item sizes (min item size 1..100 unknown; assume ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer smaller post-residual, with non-linear waste penalty.
    let mut score = post + 0.35 * (post * post) / cap;

    // Tight-fit reward: smooth polynomial coupling of fill ratio.
    let fill = item / cap;
    score -= 18.0 * fill * fill * (1.0 - fill);

    // Stream-progress coupling: as stream advances, demand tighter fits.
    let tightness = (post / cap).powi(2);
    score += 12.0 * progress * tightness;

    // Penalize bins far from the mean residual (avoid fragmenting outliers).
    score += 0.15 * (post - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        // Penalize leaving a residual that wastes space for the lookahead item.
        score += 4.0 * (1.0 - (post / cap));
    }

    // New-bin candidate: neutral-ish baseline, penalized when good fits exist,
    // favored late in the stream when open bins are fragmented.
    if bin_residual == bin_capacity {
        score = 30.0 + 10.0 * (1.0 - progress) - 2.0 * (post / cap);
        if fitting_bins_count > 0 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over common item divisors
    let pr = post_residual;
    let perfect_fit_bonus = if pr == 0 { 60.0 } else { 0.0 };
    score -= perfect_fit_bonus;

    // Small dead-space classes: residuals in 1..=10 are nearly useless
    if pr > 0 && pr <= 10 {
        score += 25.0;
    }
    // Residuals that are multiples of 10 align with typical item granularity
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    // Residuals that are multiples of 5 slightly favored
    if pr % 5 == 0 && pr > 0 && pr % 10 != 0 {
        score -= 3.0;
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // next item fits here: reward, scaled by how tightly
            let tightness = (next_item_size as f64) / (pr as f64);
            score -= 15.0 + 10.0 * tightness;
            // harmonic class: next_item divides residual nicely
            if pr % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit: penalize leaving large unusable gaps
            let gap = next_item_size - pr;
            score += (gap as f64) * 0.4;
            // if next item would fit a fresh bin anyway, mild penalty
            score += 5.0;
        }
    }

    // Integer-division thresholds on residual
    let third = bin_capacity / 3;
    let half = bin_capacity / 2;
    if pr >= half {
        score -= 5.0; // half-full or better bins are valuable
    } else if pr >= third {
        score -= 2.0;
    } else if pr > 0 {
        score += 4.0; // less than a third left: poor bin
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish baseline
    if bin_residual == bin_capacity {
        // baseline: opening new bin costs ~ residual potential
        score = 55.0 + (mean_residual / bin_capacity as f64) * 20.0;
        if next_item_size > 0 && next_item_size >= item_size.min(bin_capacity) {
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            score -= 20.0; // no good alternative: open new bin
        }
        // late in stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mean residual context: if open bins are generally full, avoid wasting this bin's space
    if bin_residual < bin_capacity {
        let waste_penalty = (post_residual as f64 / bin_capacity as f64) * (mean_residual / bin_capacity as f64) * 12.0;
        score += waste_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any plausible
    // future item are heavily penalized (non-linearly).
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: the smaller post_residual is relative to capacity, the better.
    score -= (bin_capacity - post_residual) as f64 * 0.25;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another one.
    if bin_residual == bin_capacity {
        score += 15.0 + 4.0 * open_bins_count as f64;
        // But if placing here would leave a dead gap, a fresh bin is fine.
        if (post_residual as f64) < dead_threshold && post_residual > 0 {
            score -= 20.0;
        }
    } else {
        // Mild pressure to prefer bins with small residuals when many bins are open.
        score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item cannot fit in post_residual but fits elsewhere, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Early in the stream, be slightly more willing to open bins (build good structure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is already small (consolidate fullness).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong tightness reward: squared post-residual dominates.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: reward if next item fits exactly or snugly into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain fit gets a big discount.
            if slack == 0.0 {
                score -= 60.0;
            } else if slack <= 10.0 {
                score -= 30.0 - slack * 2.0;
            } else {
                score -= 10.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: penalize leaving a large unusable gap.
            let gap = (post_residual - 0) as f64;
            score += gap * 0.3;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are preferred.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let ratio = res / mean_residual;
        score += (ratio - 1.0) * 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across too many bins when few remain tight.
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate: make it attractive only when no open bin is a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 40.0;
        // But if the item is large and next item is large too, opening may be better.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: near-perfect fits get strong discount.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight * tight;

    // Lookahead: if the next item exactly fits the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 14.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space relative to lookahead item penalized.
        score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: only attractive when no existing bin fits or all fits are terrible.
    if bin_residual == bin_capacity {
        let min_open_penalty = if fitting_bins_count == 0 { 0.0 } else {
            (fitting_bins_count as f64).ln() * 5.0
        };
        let early = 1.0 - (step_index as f64 / (total_items.max(1) as f64));
        score += 30.0 + min_open_penalty - 10.0 * early * (1.0 - tight);
        // Big items benefit from a fresh bin early on.
        if item_size > bin_capacity / 2 {
            score -= 8.0 * early;
        }
    }

    // Global state coupling: many open bins with large mean residual -> prefer consolidation.
    if bin_residual != bin_capacity {
        score -= 0.15 * mean_residual * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
    }

    // Progress horizon: late in stream, discourage opening new bins further.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, slightly compressed by progress (later => prefer tight fills more)
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Non-linear polynomial coupling of residual with progress
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);
    score += 25.0 * norm_pr * norm_pr * norm_pr * (1.0 + progress);

    // Reward near-perfect fits smoothly
    let fit_quality = 1.0 - norm_pr;
    score -= 30.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        if diff >= 0.0 {
            let x = diff / cap;
            score -= 20.0 * (1.0 - x) * (1.0 - x);
        } else {
            score += 8.0 * (-diff / cap);
        }
    }

    // Penalty for spreading across many open bins late in stream
    score += (open_bins_count as f64).ln() * 3.0 * progress;

    // Slight preference to deviate from mean residual (avoid homogeneous waste)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: small remainders are "tight" fits.
    let pr = post_residual;
    let class = pr / 10; // integer-division harmonic class (0..10)
    // Reward tight fits: subtract more as class decreases.
    score -= (10 - class.min(10)) as f64 * 6.0;

    // Modulo-5 arithmetic: residuals divisible by 5 align with common item sizes.
    if pr % 5 == 0 && pr > 0 {
        score -= 4.0;
    }
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits but not perfectly: mild reward scaled by waste
            score -= 12.0 - ((pr - next_item_size) as f64) * 0.3;
        } else {
            // next item won't fit here: penalize slightly, more if residual tiny
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to remaining open-bin space (keeps bins consolidated).
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac < 0.5 && pressure > item_size as f64 {
            score += 30.0; // plenty of room in open bins; don't open new bin
        } else if item_frac >= 0.7 {
            score -= 10.0; // big item: fresh bin is fine
        }
    }

    // Penalize dead space below the smallest plausible item (unusable sliver).
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64 - mean_residual / 10.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (>=1, typically >=10)
    // can ever use are pure waste. Penalize small unusable gaps hard.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // completely dead space
        } else if post_residual <= 20 {
            score += 25.0; // nearly dead, few items fit
        } else if post_residual <= 35 {
            score += 8.0; // moderately poor fit
        }
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        let pressure = 12.0 + 4.0 * (open_bins_count as f64).ln().max(0.0);
        score += pressure;
        // But if no existing bin fits well, a fresh bin is fine.
        if fitting_bins_count <= 1 && bin_residual != bin_capacity {
            score -= 10.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 18.0; // next item fills this bin nicely
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0; // blocks next item in a dead gap
    }

    // Mild preference for bins tighter than average (compact packing).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // residual can still hold next item; penalize leftover slack
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.3;
        } else {
            // next item cannot fit here; penalize dead space relative to next size
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.5;
        }

        // Two-step chain: residual after hypothetically placing next item
        if post_residual >= next_item_size {
            let chain_residual = post_residual - next_item_size;
            if chain_residual == 0 {
                score -= 200.0;
            }
            score += chain_residual as f64 * 0.1;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is below mean (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize new-bin opening unless current bin fit is very poor
    if bin_residual == bin_capacity {
        // new bin candidate: baseline is its post residual, add penalty
        // that shrinks if no good fitting option exists
        let pressure = if fitting_bins_count <= 1 { 0.0 } else { 80.0 };
        score += pressure;
        // early stream: prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 20.0;
    }

    // Mild penalty for many open bins (encourage filling existing bins)
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
