        score += 6.0 * dead;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 9.0 + 0.05 * next_item_size as f64;
    }
    // Penalize if next item almost fits but not quite (creates trap residual).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score += 18.0;
        // More open bins with slack => prefer reusing them.
        score += 1.5 * open_bins_count as f64;
        // If mean residual is large, opening new bins is wasteful.
        score += 0.35 * mean_residual;
        // Early in the stream, be more willing to open bins (exploration).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If the item exactly fills a fresh bin, opening is great.
        if item_size == bin_capacity {
            score -= 40.0;
        }
    }

    // Mild preference for bins with below-average residual (compact usage).
    score += 0.08 * (mean_residual - bin_residual as f64);

    // Late-stream consolidation: as the stream ends, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space, quadratically to punish large dead space
    let mut score = pr + 8.0 * norm_pr * norm_pr * cap;

    // Non-linear coupling: late in the stream, tight fits matter more
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * progress * tightness * tightness * cap;

    // Reward near-perfect packing more strongly as stream progresses
    let perfect = (pr as i64 == 0) as i32 as f64;
    score -= 12.0 * perfect * (0.5 + progress);

    // Lookahead: bonus if the next item fits the post residual exactly or well
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_ratio = nx / pr.max(1.0);
            score -= 5.0 * fit_ratio * (1.0 + progress);
        } else {
            score += 2.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 + progress);
    }

    // Slight penalty for spreading across many open bins when residuals are large
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).abs();

    // New-bin candidate: make it moderately attractive only early or when nothing fits well
    if bin_residual == bin_capacity {
        score = 0.45 * cap + 20.0 * progress * cap - 3.0 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: perfect-fit residuals are ideal
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item
    // granularities (10, 20, 25) are reusable; odd/prime-ish residuals are waste.
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 20 == 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 {
        score -= 5.0;
    }
    if pr % 10 != 0 && pr < 10 {
        score += 6.0; // tiny dead space
    }

    // Integer-division thresholds: classify residual into usability bands
    let band = pr / 10; // 0..10
    score += match band {
        0 => 12.0,                    // 1-9: nearly dead
        1 => 4.0,                     // 10-19
        2 | 3 => -2.0,                // 20-39: good for medium items
        4..=7 => -5.0,                // 40-79: versatile
        _ => -1.0,                    // near-full residual (new bin case)
    };

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 20.0 - (slack as f64).min(20.0);
            if slack % 10 == 0 {
                score -= 5.0;
            }
        } else {
            score += 3.0;
        }
    }

    // New-bin candidate handling: prefer keeping a new empty bin pristine;
    // only open a new bin when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 200.0; // forced open
        } else if fitting_bins_count == 1 {
            // compare: existing bin's post_residual vs fresh 100 - item
            let fresh_pr = bin_capacity - item_size;
            if post_residual <= 5 || next_item_size > 0 && (bin_residual - item_size) < next_item_size {
                score += 30.0;
            }
            let _ = fresh_pr;
            score += 15.0; // slight penalty so existing single fitting bin wins if decent
        } else {
            score += 60.0; // plenty of options, don't open new bin
        }
    }

    // Last-chance bin: strong reward to use it rather than leave it fragmenting
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
        if post_residual < 10 {
            score -= 15.0; // finishing off a bin cleanly
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 10.0;

    // Mean-residual context: if this bin is far below mean residual, it's a
    // fragment; use it for small items.
    if (bin_residual as f64) < mean_residual - 15.0 {
        score -= 4.0;
    }

    // Stream progression: late in stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 {
        score -= (progress - 0.7) * 30.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Avoid leaving many nearly-empty open bins
    if open_bins_count > 4 && post_residual > 60 && !is_new_bin {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (items are >= 1, but gaps < ~10 are practically unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 60.0;
    } else if post_residual >= 10 {
        // Usable leftover space: mild reward proportional to how well it could
        // accommodate a typical next item.
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly;
    // if it fits at all, mild reward; if it would waste this bin, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than spreading; with few open bins, opening new bins is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // Last-chance bin: if this is the ONLY bin that fits the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: brand-new empty bin. Only attractive when existing
    // bins would leave large dead space or the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened frivolously.
        score += 35.0;
        // But if the item is large and mean residual is small, opening fresh is fine.
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 30.0;
        }
        // Late in the stream, avoid proliferation of nearly-empty bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
    } else {
        // Favor bins whose residual is close to the item (tight fit) beyond raw post_residual.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 15.0;
        // Slightly prefer bins with below-average residual (nearly-full bins get used up).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual (best-fit core).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: strongly reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact or near-exact chain match is gold.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 25.0 + 15.0 * (1.0 - chain_slack / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
        // If the next item can ONLY go here (this bin is its only host after placement),
        // reward heavily to preserve feasibility.
        if post_residual >= next_item_size && fitting_bins_count == 1 {
            score -= 20.0;
        }
    } else {
        // Last item: pure best-fit.
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins tighter than average are more precious;
    // filling them is good, but leaving them with useless crumbs is bad.
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel > 1.0 {
            score -= 2.0 * (rel - 1.0).min(3.0); // prefer using looser bins first
        } else {
            score += 3.0 * (1.0 - rel).min(2.0); // protect tight bins unless fit is great
        }
    }

    // Last-chance bonus: if this is the only open bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && open_bins_count > 0 {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // gives a good fit (post_residual small relative to capacity).
    if bin_residual == bin_capacity {
        // Neutral reference with a mild inertia cost, reduced late in the stream
        // (fewer chances left to consolidate).
        score = 0.55 * bin_capacity as f64 - 10.0 * progress;
        // If next item is large and this item is small, a fresh bin is attractive.
        if next_item_size > 60 && item_size < 30 {
            score -= 15.0;
        }
    }

    // Late-stream consolidation pressure: discourage spreading across many bins.
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64 - 4.0).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize small unusable dead space (too small for any item >= 1... but
    // small slivers below typical item scale waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward leaving a gap that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap_fit = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - gap_fit / (bin_capacity as f64));
        } else {
            // Dead space for the next item: mild penalty scaled by proximity.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.15 * miss;
        }
        // If next item fits exactly after this placement, big reward.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else {
        // Last item: just minimize residual.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidating
    // into bins with above-average residual usage.
    let usage = (bin_capacity - bin_residual) as f64;
    let mean_usage = (bin_capacity as f64) - mean_residual;
    if open_bins_count > 1 {
        score -= 0.05 * (usage - mean_usage);
    }

    // Time horizon: early in the stream, be conservative about filling bins
    // (keep flexibility); late, push toward closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;
    score += 5.0 * (1.0 - progress) * (post_residual as f64) / (bin_capacity as f64);

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // If this bin is the only fitting option, opening fresh is cheap.
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count == 1 {
            // Existing last-chance bin: make new bin less attractive.
            score += 30.0;
        }
        // Late in the stream, opening new bins wastes capacity — penalize.
        score += 25.0 * progress;
        // Large items may justify a fresh bin to avoid fragmentation.
        if item_size > 60 {
            score -= 10.0;
        }
    }

    // Mild bonus for filling bins that are already well-used.
    score -= 0.05 * usage;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += poly * 30.0;

    // Reward tight fits, smoothly scaled by progress.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Last-chance bin: penalize opening new bins, more so late in stream.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 25.0 * progress;
    }

    // New bin candidate: mildly penalize early, allow late when residuals are poor.
    if bin_residual == bin_capacity {
        let mean_ratio = mean_residual / cap;
        score += 5.0 - 10.0 * progress * mean_ratio;
    }

    // Lookahead: reward leaving room for next item.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= (gap / cap) * 8.0 * (1.0 - progress);
        } else {
            score += (-gap / cap) * 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into coarse buckets.
    // Residuals <= 10 are near-perfect closures -> heavy reward (subtract).
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score -= 4.0;
    } else if post_residual <= 50 {
        score += 6.0; // half-empty bin: mediocre
    } else {
        score += 14.0; // large hole: undesirable unless nothing better
    }

    // Integer-division threshold classes on post_residual (mod-10 harmonic bands)
    let band = post_residual / 10;
    score -= (band % 3) as f64 * 2.0; // small periodic modulation

    // Lookahead coupling: reward bins whose residual can host the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits snugly: reward tightness of that fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0) * 0.5;
        } else {
            // next item cannot use leftover: penalize proportionally
            score += 5.0;
        }
        // if next item exactly fills current residual after this placement chain
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening new bins when good fits exist
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline is its full residual; add penalty scaled
        // by how many open bins could fit, and by stream progression.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin would be very flexible; slight reward
            score -= 5.0;
        }
        if fitting_bins_count > 0 {
            score += 8.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (res_f - mean_residual) * 0.15;
    }

    // Slight preference for fewer open bins (consolidation)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically < 10 are near-dead) are heavily penalized.
    if post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    } else if post_residual < 20 {
        score += 6.0 * (20 - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: penalize using open bins when many are open,
    // encouraging consolidation; but relieve pressure when this is the
    // only fitting bin (last-chance placement).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (1.0 - progress);
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement; if next item would fit nowhere else,
    // keep residual large enough for it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual < next_item_size && post_residual >= 1 {
            score += 10.0; // residual too small for next item: dead space
        }
    }

    // New-bin candidate: brand-new empty bin should be chosen only when
    // no open bin offers a decent fit; give it a moderate baseline penalty
    // so good fits in open bins win, but it beats badly fragmented bins.
    if bin_residual == bin_capacity {
        score += 35.0 + 1.5 * open_bins_count as f64;
    }

    // Slight preference for bins with residuals close to the mean (stable packing).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when next item exactly fills post_residual (perfect 2-step match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how tightly the next item fits.
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack_after_next as f64 / post_residual.max(1) as f64);
        } else {
            // Next item cannot follow: penalize dead space creation.
            score += 15.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest packing.
        score -= 10.0;
    }

    // Penalize residual far below mean residual (wasting a nearly-full bin is fine,
    // but leaving a large residual in an average bin creates fragmentation).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count > 0 && next_item_size > 0 {
            // Slight extra penalty if open bins exist that could still host future items.
            score += 5.0;
        }
    }

    // Late in the stream, tighten packing (less tolerance for loose residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of the bin's residual consumed by this item
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward tight fits: subtract proportional to how much of residual is used
    let tightness_bonus = (item_size as f64 / bin_residual.max(1) as f64) * 30.0;
    score -= tightness_bonus;

    // Penalize leaving dead space that the next item cannot use
    if next_item_size > 0 {
        let gap = post_residual as f64;
        if gap > 0.0 && (next_item_size as f64) > gap {
            // Dead space until a future item: penalize more as stream progresses
            score += (gap / bin_capacity as f64) * (10.0 + 40.0 * progress);
        } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            // Next item fits perfectly in the leftover: strong reward
            let perfect = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - perfect / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize waste
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 30.0 * (1.0 - progress);
    }

    // Many open bins: prefer consolidating into existing bins
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score -= pressure * 8.0 * fill_ratio;

    // Global residual state: if mean residual is low, keep bins tight
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 6.0 * (1.0 - rel);
        } else {
            score += 4.0 * (rel - 1.0).min(2.0);
        }
    }

    // Penalize opening new bins mid-stream unless residual is very small
    if bin_residual == bin_capacity {
        let new_bin_penalty = 15.0 + 25.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 3.0;
        // But allow new bin if existing fit would be terrible
        let fit_quality = item_size as f64 / bin_capacity as f64;
        score += new_bin_penalty - 40.0 * fit_quality * progress;
    }

    // Nonlinear squashing of extreme waste
    if post_residual > 50 {
        score += (post_residual - 50) as f64 * 0.6 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: prefer tight fills mildly (post_residual dominates).
    // Late in the stream: penalize residual super-linearly to squeeze bins shut.
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * norm_pr * norm_pr * (progress * 2.0);
    score += 60.0 * poly;

    // Smooth interaction: reward filling a bin deeply when many bins are open.
    let fill_ratio = 1.0 - norm_pr;
    score -= 8.0 * fill_ratio * fill_ratio * (open_bins_count.min(64) as f64).sqrt();

    // Penalize if this bin's residual deviates strongly from mean residual (imbalance).
    score += 0.15 * (pr - mean_residual).abs().sqrt() * (0.5 + progress);

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - (pr - nxt) / cap;
            score -= 12.0 * snug * snug;
        } else {
            // Next item won't fit here: mild penalty scaled by progress.
            score += 6.0 * progress * (nxt / cap);
        }
    } else {
        // Last item: reward closing bins completely.
        score -= 10.0 * fill_ratio * fill_ratio * fill_ratio;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Slight bias toward reusing existing bins over opening new ones,
    // weakening late in the stream when consolidation matters more.
    if bin_residual == bin_capacity {
        score += 4.0 + 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of the post-fit residual: classify by capacity eighths.
    // Residuals in [1..12] are "dead space" (below min item size 10..12 zone),
    // heavily penalize unless it's exactly a tight fit.
    if post_residual == 0 {
        score -= 50.0; // perfect fill — best possible outcome
    } else if post_residual < 10 {
        score += 25.0; // dead space: nothing can ever use it
    } else if post_residual <= 25 {
        score -= 5.0; // small-but-usable residual is good (tight packing)
    }

    // Modulo-arithmetic harmonic classes on post_residual: residuals that are
    // multiples of common item sizes (10, 20, 25, 50) are more reusable.
    let r = post_residual;
    if r % 10 == 0 { score -= 6.0; }
    if r % 25 == 0 { score -= 3.0; }
    if r % 50 == 0 { score -= 3.0; }

    // Lookahead (k=2): reward bins whose residual can also host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 + 0.3 * next_item_size as f64;
        if slack < 10.0 {
            score -= 6.0; // near-exact two-item chain
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; penalize proportionally to wasted potential.
        score += 4.0 + 0.1 * (next_item_size as f64 - post_residual as f64).min(50.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless residual would be dead space).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: opening a bin is expensive when alternatives exist,
    // but attractive when all existing fits would create dead space.
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 30.0; // default: prefer reusing open bins
            // But if the only fits leave dead space (<10), allow the new bin.
            if post_residual < 10 || (next_item_size > 0 && post_residual < next_item_size && post_residual < 10) {
                score -= 40.0;
            }
        }
        // Early in the stream, seeding bins is cheaper; late, be conservative.
        score += 10.0 * progress;
        // Many open bins with high mean residual: don't add another.
        if mean_residual > 30.0 && open_bins_count > 3 {
            score += 10.0;
        }
    } else {
        // Prefer bins tighter than the current mean residual (best-fit flavor).
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // Mild pressure to close out bins as the stream progresses.
    if post_residual > 0 && post_residual < item_size {
        score += 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (cannot fit even the smallest plausible item) are heavily penalized.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Medium gaps: mildly penalize, since they may still be usable.
    if post_residual >= dead_threshold && post_residual < 30 {
        score += 4.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 3.0; // next item won't reuse this space
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage proliferation of bins when residual is generous.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score += open_bins_count as f64 * 0.8 * (1.0 - progress * 0.5);
    } else {
        // New-bin candidate: penalize slightly unless current bins fit poorly.
        score += 10.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 20.0; // nothing fits elsewhere, new bin is necessary
        }
    }

    // Prefer bins whose residual is close to the item (tight fit).
    score += (bin_residual as f64 - item_size as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (-diff / 12.0).exp(); // smooth match bonus, strongest at exact fit
        // Penalize post_residual that is small but unusable for the next item.
        if post_residual < next_item_size {
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Tight-fit preference: reward small post_residual relative to bin capacity.
    score += 1.5 * (post_residual as f64 / bin_capacity as f64);

    // Contextual coupling with mean residual across open bins.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Late in stream, prefer filling existing bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins
    // when all open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.3 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward (relative waste)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness * tightness;

    // Penalize small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 120.0;
        } else if next_item_size <= bin_residual {
            score += 30.0; // consuming space the next item could have used
        }
    }

    // New-bin candidate: penalize opening a bin unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 150.0
            - 100.0 * (1.0 - tightness)
            + (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 50.0;
        }
    }

    // Global state coupling: prefer filling bins when many open bins have large residuals
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * (mean_residual / bin_capacity as f64) * (1.0 - progress);

    // Late stream: consolidate aggressively
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fits mildly; late, penalize waste strongly.
    let pr_norm = pr / cap;
    let prog_sq = progress * progress;
    score += 40.0 * pr_norm * pr_norm * (0.5 + prog_sq);

    // Reward filling a bin nearly completely, smoothly.
    let fill = it / cap;
    score -= 25.0 * fill * fill * (1.0 - progress * 0.5);

    // Lookahead: if next item fits into post_residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            // penalize leaving residual that cannot host the next item
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (pr - mean_residual);

    // New-bin candidate: mild penalty so we prefer reusing open bins,
    // but relax late in the stream when open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity-fraction classes
    let item_class = item_size / 10;           // 1..=10 harmonic class
    let next_class = next_item_size / 10;      // 0 => no next item

    // Best-fit core: prefer small post_residual
    score = post_residual as f64;

    // Reward tight fits strongly (post_residual is dead space)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Perfect fit: absolute reward
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Harmonic class matching: if next item's class fits exactly in post_residual,
    // this placement chains beautifully.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
        // Exact class match between item and next item: prefer keeping same-class bins together
        if next_class == item_class {
            score -= 3.0;
        }
        // Modulo coupling: post_residual divisible by next_item_size class size
        if next_class > 0 && post_residual % (next_class * 10) == 0 {
            score -= 4.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover: penalize creating dead space
        score += 4.0 + 0.15 * (post_residual as f64);
    }

    // Integer-division thresholds on post_residual: small leftovers are
    // either dead or perfect for tiny classes.
    let dead_threshold = 9; // smallest possible item size
    if post_residual > 0 && post_residual < dead_threshold {
        score += 12.0; // unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: only open a new bin when no existing bin
    // offers a decent fit (residual would be large) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base handicap: existing bins should usually win
        score += 20.0;
        // But if all fitting bins would leave big dead space, new bin becomes attractive
        if post_residual > 0 {
            // For the new bin, post_residual = capacity - item_size
            let waste_existing = (mean_residual - item_size as f64).max(0.0);
            if waste_existing > 0.5 * (bin_capacity as f64) {
                score -= 18.0;
            }
        }
        // Early in the stream, opening bins is cheap
        if progress < 0.2 {
            score -= 5.0;
        }
        // Many open bins with large mean residual: consolidate instead
        if open_bins_count > 3 && mean_residual > 30.0 {
            score += 10.0;
        }
    }

    // Mild penalty for spreading across many bins
    score += 0.3 * open_bins_count as f64;

    // Mean residual coupling: prefer bins whose residual is below average
    // (fill fuller bins first, keep emptier bins flexible)
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold any future item are pure waste.
    let min_item = 1u32;
    let usable_gap = post_residual >= min_item;
    if !usable_gap {
        score += 1000.0; // perfect fill, strongly favored
    } else {
        // Penalize gaps that cannot fit the lookahead item (likely dead space)
        if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0 + 0.05 * post_residual as f64;
        }
        // Penalize gaps too small for the minimum plausible item
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Tight-fit reward: fraction of residual consumed
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_frac;

    // Last usable bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer packing over opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: only attractive when item barely fits nowhere well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 }
            else if next_item_size > 0 && post_residual < next_item_size { 5.0 }
            else { 25.0 };
        score += desperation + 0.3 * mean_residual;
        score -= 5.0 * (1.0 - progress);
    }

    // Reward leaving a gap that exactly fits the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fill (small post_residual).
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fits the post residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 1.0 {
            // Perfect chaining: this bin will be exactly filled next step.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild reward proportional to how well it chains.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.5 * chain_waste;
        } else {
            // Next item will NOT fit in this bin: penalize leaving a gap that
            // is too small for the next item (dead space).
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap;
        }
    }

    // Relative to mean residual: bins with residuals far above mean are
    // less "valuable" targets; prefer consuming below-average-residual bins
    // so the population of open bins stays homogeneous.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.35 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only bin that can fit, strongly favor it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Penalize opening a new bin unless the current item nearly fills it
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive for large items or when the
        // item would leave a huge dead space in existing bins.
        score = (bin_capacity - item_size) as f64;
        if item_size >= 60 {
            score -= 30.0; // big items deserve fresh bins
        }
        if next_item_size > 0 && (item_size + next_item_size) as f64 <= bin_capacity as f64 {
            score -= 10.0; // room for the next item too
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer closing out
    // existing bins rather than spreading across many.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 {
        score += 5.0 * (1.0 - progress) * (pr / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tight * (20.0 + 40.0 * progress);

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't chain here; mild penalty scaled by wasted space.
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global state: many open bins with low mean residual -> prefer filling existing bins.
    if open_bins_count > 2 && mean_residual < (bin_capacity as f64 * 0.25) {
        score -= 8.0;
    } else if open_bins_count > 6 {
        score -= 3.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base penalty so a decent existing fit usually wins.
        score += 10.0;
        // But if the item leaves a very tight fit in an open bin, or few bins fit,
        // opening fresh is attractive (perfect residual for next item).
        if fitting_bins_count <= 2 {
            score -= 6.0 * (2.0 - fitting_bins_count as f64);
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0;
        }
        // Early in stream, opening bins is cheap and builds packing flexibility.
        if progress < 0.3 {
            score -= 5.0 * (1.0 - progress / 0.3);
        }
    }

    // Mild preference for bins with residual close to item_size (exactness).
    let slack = (bin_residual as f64 - item_size as f64).abs();
    score += 0.02 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: normalized post-residual, warped non-linearly by stream progress.
    // Early on, residual waste matters less; late, penalize it more strongly.
    let progress_warp = 0.5 + 0.5 * progress * progress;
    let mut score = norm_pr * (1.0 + 2.0 * progress_warp);

    // Smooth polynomial coupling between post_residual and progress:
    // cubic interaction term amplifying large dead space late in the stream.
    score += 3.0 * norm_pr * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Tightness reward: bins nearly filled get a smooth quadratic discount.
    let fill = 1.0 - norm_pr;
    score -= 1.5 * fill * fill * (1.0 - progress * 0.5);

    // Mean-residual coupling: prefer bins deviating below the mean residual
    // (more filled than average), smoothly via normalized difference.
    let dev = (mean_residual - pr) / cap;
    score += 0.4 * dev * dev * dev.abs().signum();

    // Last-chance bin: strong smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 - progress * 0.3);
    } else {
        // Mild penalty for many alternatives to encourage consolidation.
        score += 0.05 * (fitting_bins_count as f64).sqrt();
    }

    // Lookahead: if the next item fits the post-residual, reward this placement
    // with a smooth quadratic term.
    if next_item_size > 0 {
        let fits_next = if (pr >= next_item_size as f64) { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 1.2 * fits_next * (1.0 - gap * gap);
    }

    // New-bin candidate handling: neutral-to-slightly-high base so it is chosen
    // only when all open bins score poorly (large residuals late in stream).
    if bin_residual == bin_capacity {
        score = cap * (0.8 + 0.6 * progress) - 0.5 * norm_pr;
        // If the next item is large, opening a fresh bin is more attractive.
        if next_item_size > 0 {
            score -= 0.3 * (next_item_size as f64 / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: residues mod 10 define "dead space" quality.
    let cls = post_residual % 10;
    // Perfect closure (0 residual) is ideal; small residues (1..9) are dead space.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // near-closure: unusable sliver, but at least it's tiny
        score -= 10.0 - cls as f64;
    } else {
        // mid-range residuals: penalize by how little a future item could use them.
        // harmonic class: residual in [10,30) is reusable, [30,60) semi, >=60 bad
        if post_residual < 30 {
            score -= 6.0;
        } else if post_residual < 60 {
            score += 4.0;
        } else {
            score += 12.0;
        }
        // modulo threshold coupling: residual divisible by 10 aligns with common item classes
        if cls == 0 {
            score -= 3.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt_gap = post_residual - next_item_size;
        if nxt_gap == 0 {
            score -= 45.0;
        } else if nxt_gap < 10 {
            score -= 18.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize proportionally
        score += (next_item_size as f64 - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        // late in stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Prefer filling bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Mild penalty per open bin to discourage sprawl.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space penalty: residuals in (0, 10) are essentially unusable
    // (min item size is 1, but tiny gaps waste capacity structurally).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect-fit lookahead: if next item exactly fills post_residual, big bonus.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Penalize if next item cannot use this bin's leftover at all.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    if is_new_bin {
        // Opening a new bin is costly; discourage unless current fits are bad.
        // Cost grows with number of open bins (bin pressure) and stream progress.
        let open_pressure = 6.0 + (open_bins_count as f64).sqrt() * 4.0;
        let progress_pressure = progress * 20.0;
        score += open_pressure + progress_pressure;

        // If other bins can fit the item, opening a new bin should be rare;
        // make it attractive only when the new bin leaves a large, reusable gap
        // (i.e., item is small relative to capacity).
        if fitting_bins_count > 0 {
            score += 30.0;
            // Large post_residual in a fresh bin = versatile future space.
            score -= (post_residual as f64) * 0.15;
        } else {
            // Last-chance fallback: fresh bin is fine.
            score -= 10.0;
        }
    } else {
        // Slight preference to fill bins with lower residual (best-fit flavor)
        // and to keep the number of open bins from exploding.
        score += (open_bins_count as f64) * 0.5;

        // Last usable bin before opening a new one: reward using it.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Penalize leaving residual that is smaller than the next item but
        // close to it (near-miss waste), unless residual is tiny.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // next item can also go here: good flexibility
        }
    }

    // Mild tie-break toward bins below mean residual (fill emptier bins less,
    // keep fuller bins tight — prefer bins with residual near item size).
    let ideal = mean_residual * 0.5;
    score += ((bin_residual as f64) - ideal).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: bin closes exactly after next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial reward: next item fits with small leftover.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - leftover_after_next / bin_capacity as f64);
    }
    // Penalize if next item would not fit in the resulting residual.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Prefer bins whose residual is tighter than average (good fits).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Penalize bins far above mean residual (they hoard space).
    if (bin_residual as f64) > mean_residual {
        score += 0.5 * (bin_residual as f64 - mean_residual);
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when item is large relative to typical residual
    // or no real benefit from open bins; otherwise keep it mildly unattractive.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > mean_residual * 0.9;
        if big_item {
            score -= 30.0;
        } else {
            score += 12.0;
        }
        // More open bins -> prefer reusing existing bins.
        score += 2.0 * open_bins_count as f64;
    }

    // Slight late-stream tightening: near end, prefer fuller bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus when post residual is small.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Perfect fill gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize leaving dead space that no plausible item can use:
    // items are 1..=100, but small residuals below ~15 are hard to fill.
    if post_residual > 0 && post_residual < 15 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin; if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size > post_residual {
            score += 4.0;
        } else {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / (bin_capacity as f64));
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is discouraged unless current
    // fit is poor or the stream is early and bins are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = 1.0 / (1.0 + open_bins_count as f64);
        score += 14.0 - 10.0 * scarcity - 6.0 * progress;
        // If the item is large relative to mean residual, opening fresh is fine.
        let mean_fit = mean_residual / (bin_capacity as f64);
        if (item_size as f64) > mean_fit * (bin_capacity as f64) {
            score -= 5.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing
    // existing capacity (penalize new bins implicitly, reward this bin).
    let pressure = mean_residual * (open_bins_count as f64) / (bin_capacity as f64);
    score -= 2.0 * pressure.min(3.0);

    // Slight preference to balance residuals toward the mean (avoid fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space quadratically (small residuals are bad).
    let mut score = 100.0 * (1.0 - x) * (1.0 - x) + 10.0 * x;

    // Smooth non-linear coupling of fit quality with stream progress:
    // early on, prefer tight fits; late, tolerate slack to keep bins closing.
    let progress_weight = t * t * (3.0 - 2.0 * t); // smoothstep
    score += 20.0 * progress_weight * x * (1.0 - x);

    // Coupling with mean residual: avoid bins far from the fleet average.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev - 3.0 * dev * progress_weight;

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress_weight + 0.5 * progress_weight);
    }

    // Lookahead: reward post residual that can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for proliferating bins.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress_weight);

    // New-bin candidate: keep it neutral-ish, slightly favored only when
    // current bin fit is very poor and stream is early.
    if bin_residual == bin_capacity {
        score = 40.0 + 20.0 * progress_weight - 15.0 * (1.0 - x * 0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls on "useful"
    // class boundaries (multiples of small denominators) are preferred.
    let pr = post_residual;
    if pr > 0 {
        // reward residuals that divide capacity evenly (harmonic with C)
        if bin_capacity % pr == 0 {
            score -= 6.0;
        }
        // reward small-residual classes lightly (tight fits are good)
        let cls = pr / 10; // integer division threshold class
        match cls {
            0 => score -= 4.0,          // pr in 1..10 : near-perfect fill
            1 => score -= 2.0,          // 10..20
            2 => score -= 1.0,          // 20..30
            3 => score += 1.0,          // 30..40 : dead-ish space
            4 => score += 2.0,
            _ => score += 3.0,          // >=50 : half-empty bin
        }
        // modulo-5 / modulo-10 structure: residuals matching common item
        // granularities are more likely reusable by future items.
        if pr % 10 == 0 {
            score -= 2.5;
        } else if pr % 5 == 0 {
            score -= 1.0;
        }
    } else {
        // perfect fill
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly
    // or well, this placement chains nicely.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 8.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 3.0 * (1.0 - slack as f64 / cap);
            if slack % 10 == 0 { score -= 1.5; }
        } else {
            // next item cannot use this residual: penalize large leftover
            score += 0.02 * (pr as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: only attractive when item is large relative to
    // capacity and open bins are crowded with big residuals.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        let crowded = (open_bins_count as f64) * (mean_residual / cap);
        if frac > 0.6 || crowded > 2.0 {
            score -= 4.0 + 3.0 * frac;
        } else {
            score += 6.0; // prefer existing bins early on
        }
    }

    // Slight global pressure: as stream progresses, tighten fills.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * t * (1.0 - post_residual as f64 / cap);

    // Tie-break toward bins below mean residual (consolidate emptier bins).
    score += 0.05 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    let min_item = 1u32;
    let dead_threshold: f64 = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Tightness reward: relative fill of the bin with this item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: strongly favor using it, else bin count grows.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins and avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.5;

    // New-bin candidate: only attractive when mean residual across open bins
    // is small relative to the item (nothing fits well) or no bin fits well.
    if bin_residual == bin_capacity {
        let mean_bad = mean_residual < item_size as f64 * 0.5;
        let base = 55.0 + pressure;
        if mean_bad {
            score = base - 20.0;
        } else {
            score = base + (bin_capacity as f64 - mean_residual) * 0.3;
        }
    }

    // Lookahead: if the next item fits into the post residual, reward leaving
    // that gap; otherwise penalize leaving a gap that wastes capacity.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 {
            score += (post_residual as f64) * 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Exact 2-step lookahead match: the next item fills this bin perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    }
    // Next item fits into the post residual (chainable bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + post_residual as f64 * 0.5;
    }
    // Next item does NOT fit: post residual becomes dead space unless tiny.
    if next_item_size > 0 && next_item_size < post_residual {
        // usable gap remains
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 80.0 * (1.0 - post_residual as f64 / 100.0);
    }

    // Penalize tiny unusable residuals (dead space < min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 150.0;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // Late in the stream, prefer reusing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Prefer bins tighter than the mean residual (best-fit bias).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Reward fuller bins.
    score -= (bin_capacity - bin_residual) as f64 * 0.2;

    // Many open bins: discourage spreading; few open bins: encourage reuse.
    if open_bins_count > 5 {
        score += open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - tight) * (1.0 - tight) * tight;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: only bin that fits -> strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: penalize bins whose post-residual fits the next item poorly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.35 * gap;
        if post_residual >= next_item_size {
            score -= 12.0; // chain placement possible
        }
        // If next item can't fit anywhere after this placement, prefer tight bins.
        if post_residual < next_item_size {
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate: penalize opening a new bin, more when many bins open
    // or when residual capacity is plentiful; relax late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = mean_residual / bin_capacity as f64;
        score += 25.0 + 2.0 * open_bins_count as f64 + 20.0 * (1.0 - waste) - 15.0 * progress;
        // If the item is huge, a fresh bin is actually attractive.
        if item_size >= 70 {
            score -= 30.0;
        }
    }

    // Mild penalty for leaving residuals in awkward mid-range dead zones.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-dead space, better to consume it now
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 3.0; // awkward zone
    }

    // Prefer bins with below-average residual (consolidate emptiness).
    score += 0.1 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = 1.0 - (item_size as f64 / cap);

    // Smooth non-linear coupling: reward tight fits more strongly as stream progresses
    let tightness = (1.0 - norm_pr).powi(2);
    score -= progress * tightness * 30.0;

    // Polynomial penalty on mid-range wasted residuals (dead space), smoothed via cubic
    let waste = norm_pr * norm_pr * (1.0 - norm_pr);
    score += waste * 40.0;

    // Interaction with mean residual: prefer bins below mean (pack big into empty-ish)
    let mr = mean_residual / cap;
    score += (norm_pr - mr).powi(3) * 10.0;

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for the next item (smooth quadratic)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = ns - pr;
        if gap <= 0.0 {
            let fit_q = (ns / cap).powi(2);
            score -= 8.0 * fit_q * (1.0 - progress);
        } else {
            score += (gap / cap) * 5.0;
        }
    }

    // Mild penalty for too many open bins, smoothed by progress
    score += open_bins_count as f64 * progress * 0.5;

    // Reward high fill ratio polynomially
    score -= fill * fill * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets create discrete
    // "harmonics" of usable space. Small post_residual (< 10) is dead space
    // for items >= 10; penalize heavily.
    let dead_class = post_residual % 10;
    if post_residual < 10 {
        score += 25.0; // unusable residual under the min item size
    } else {
        score -= (dead_class as f64) * 0.6; // reward residuals in "round" classes
    }

    // Capacity-fraction harmonics: reward post_residual landing in useful
    // fractional bands of the bin (1/4, 1/2, 3/4).
    let frac = post_residual as f64 / cap;
    if (frac - 0.25).abs() < 0.02 || (frac - 0.5).abs() < 0.02 || (frac - 0.75).abs() < 0.02 {
        score -= 8.0;
    }

    // Exact fill reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Integer-division threshold: post_residual / next_item_size quotient.
    if next_item_size > 0 && post_residual >= next_item_size {
        let quotient = post_residual / next_item_size;
        score -= (quotient.min(3)) as f64 * 4.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual cannot host the next item: mild dead-space penalty,
        // stronger if next item is large.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it attractive only when current bin fit is poor
    // (large post_residual) or bin is nearly full.
    if bin_residual == bin_capacity {
        // Base competitiveness of a fresh bin.
        score = cap - item_size as f64;
        if item_size >= 60 {
            score -= 10.0; // big items deserve a fresh bin
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 6.0; // room to pair with the next item
        }
        if fitting_bins_count == 1 {
            score += 40.0; // don't abandon the only fitting bin
        }
    } else {
        // Prefer fuller bins (best-fit bias) modulated by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 3.0;
        // Penalize bins far below mean residual (fragmentation avoidance).
        if (mean_residual - post_residual as f64).abs() > cap * 0.4 {
            score += 5.0;
        }
    }

    // Modulo harmonic on item class vs residual class: matching residue
    // classes (item_size % 10 == bin_residual % 10) yields near-exact fits.
    if item_size % 10 == bin_residual % 10 && item_size <= bin_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that no item can use are heavily penalized.
    let min_gap = if next_item_size > 0 { next_item_size.min(80).max(1) } else { 1 };
    if post_residual > 0 && post_residual < min_gap.max(10) {
        // Unusable sliver: penalize proportionally to how much capacity is wasted.
        score += 40.0 + (min_gap.max(10) - post_residual) as f64 * 3.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residual exactly matching the lookahead item (chain planning).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        // Gap just barely too small for lookahead: dead space ahead, penalize.
        score += 15.0;
    }

    // Tight-fit reward: fraction of bin used by this item.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize placements that leave many bins open with slack.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is already below mean (consolidate slack).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or fit is terrible.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64);
        let bad_fit = post_residual as f64 > 60.0;
        if fitting_bins_count == 0 || (bad_fit && crowded > 2.0) {
            score -= 45.0;
        } else {
            // Discourage opening new bins when decent fits exist.
            score += 50.0;
        }
    }

    // Mild late-stream tightening: waste less as the stream nears its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight superlinearity
    // to strongly punish leaving awkward dead space.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: if the next item exactly fills the post
    // residual, this is a perfect chain fit -> heavily reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits inside this bin's leftover: mild reward scaled
            // by how snugly it nests.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this leftover: penalize proportionally to
            // how far the leftover falls short of the next item.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.35 * miss.min(bin_capacity as f64);
        }
    } else {
        // Last item: any residual is pure waste; reward tightest fit more.
        score += 10.0;
    }

    // Compare against mean residual across open bins: placing into a bin
    // whose residual deviates strongly from the mean is either a good
    // consolidation (small residual bin) or fragmentation (large residual).
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        // Below-average leftover = good packing density.
        score -= 0.5 * (-dev);
    } else {
        // Above-average leftover = creating more dead space than typical.
        score += 0.3 * dev;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless the current
    // fit is really bad (large post_residual relative to next item needs).
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the mean residual of all open bins.
        score += 30.0 + 0.4 * mean_residual;
        // But if lookahead shows the next item would pair well in a fresh bin
        // with this item, allow it: fresh bin post_residual = capacity - item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - pair_waste / bin_capacity as f64);
        }
    }

    // Mild stream-progression term: later in the stream, prefer closing out
    // bins tightly (waste becomes harder to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty for scattering across many open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio penalization (quadratic in small residuals)
    if post_residual == 0 {
        score -= 50.0; // perfect fill is highly desirable
    } else if post_residual <= 10 {
        score -= 20.0 - (post_residual as f64) * 1.5;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack * 0.3; // prefer chains that leave little slack after next item
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space that cannot host the next item: penalize proportionally
        score += (post_residual as f64) * 0.25;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin wastes capacity; only attractive
    // if the item would leave a very bad fit everywhere else (large post_residual
    // in existing bins) or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Large items open bins more naturally; small items should reuse bins.
        score += 60.0 * (1.0 - item_frac);
        // Late in the stream, prefer closing out existing bins over opening new ones.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
        // Many open bins with slack: discourage opening yet another.
        score += (open_bins_count as f64).min(10.0) * 2.0;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += mean_residual * 0.4;
        // But if next item is huge and this item is huge, a fresh bin chains well.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Mild preference for bins already below mean residual (consolidate emptier bins)
    if bin_residual as f64 > mean_residual && bin_residual != bin_capacity {
        score += 3.0;
    } else if bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Early stream: keep scores slightly compressed to encourage exploration of fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling: as stream progresses, penalize residual more (less time to fill gaps)
    score += 40.0 * progress * norm_pr * norm_pr * norm_pr;

    // Dead-space penalty for residuals too small for typical items
    if pr > 0 {
        score += 12.0 * (1.0 - (pr / 10.0).min(1.0) as f64) * (1.0 - progress);
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 5.0 * progress;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Slight preference for tighter bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 3.0;

    // Mild penalty for deviating far from mean residual (keeps balance)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: keep it neutral-to-slightly-high unless residuals are fragmented
    if bin_residual == bin_capacity {
        score = cap * (1.0 + norm_pr) * (0.9 + 0.4 * progress) + 20.0 * (1.0 - (fitting_bins_count as f64).recip());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes mod 10.
    // Small leftovers (dead space) get strong penalties; "harmonic" leftovers that pair
    // with common item sizes get rewards.
    let post_class = post_residual % 10;
    match post_class {
        0 => score -= 8.0,                 // perfect multiple of 10: excellent
        5 => score -= 3.0,                 // half class: pairs with 5-multiples
        2 | 8 => score -= 1.5,             // near-harmonic
        1 | 9 => score += 6.0,             // nearly dead space
        3 | 7 => score += 2.0,
        4 | 6 => score += 0.5,
        _ => {}
    }

    // Integer-division thresholds: leftover capacity fraction classes.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac <= 0.1 {
        score += 5.0; // tight fill is good, but only if not dead space class... balance
    } else if frac >= 0.6 {
        score -= 4.0; // plenty of room left: keep bin flexible
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 6.0;
            } else {
                score += gap as f64 * 0.15;
            }
        } else {
            // next item cannot follow here: mild penalty scaled by overshoot
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize slightly unless current bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 15.0 {
            score -= 5.0; // all bins nearly full: open a new one
        } else {
            score += 10.0 + 5.0 * (1.0 - progress);
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += ((bin_residual as f64 - mean_residual) * 0.3).max(0.0);

    // Crowding: many open bins favors consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" zone
    // (small leftovers that most future items can't exploit) are heavily penalized.
    let dead_zone: f64 = 20.0; // gaps below ~20 units are near-useless
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 3.0;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: fraction of the bin's residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins;
    // opening yet another bin becomes progressively more expensive.
    let pressure = 1.0 + (open_bins_count as f64 / 8.0);
    if bin_residual == bin_capacity {
        // Candidate is a brand-new empty bin: penalize it by open-bin pressure,
        // but relax the penalty late in the stream or when it's a last resort.
        let mut new_bin_penalty = 18.0 * pressure;
        if fitting_bins_count <= 1 {
            new_bin_penalty *= 0.3;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty *= 1.0 - 0.4 * progress;
        score += new_bin_penalty;
    } else {
        // Existing bin that fits: mild reward, stronger if it's the only fitting bin.
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Prefer bins whose residual is below average (tighter bins first),
        // keeping large-residual bins available for big future items.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Lookahead: if the next item would fit exactly in the post-residual,
    // reward leaving that gap; if the next item is large and the gap is
    // too small for it, penalize creating a stranded gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            let waste = post_residual as f64 / (next_item_size as f64).max(1.0);
            score += waste * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus: strongly prefer leaving zero waste.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness: reward small post_residual relative to capacity.
        score += (post_residual as f64 / bin_capacity as f64) * 20.0;
    }

    // 2-step lookahead: if the next item exactly matches the post_residual,
    // this is a perfect chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if post_residual > 0 && next_item_size < post_residual {
            // Next item still fits after this placement: mild bonus scaled by fit quality.
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit: penalize creating dead space that blocks it.
            score += 40.0;
        }
    }

    // Compare against mean residual: placing into a below-average-residual bin
    // preserves larger residual bins for harder items.
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the
    // current placement is very wasteful.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if no open bin fits well, allow opening: the fitting_bins_count
        // penalty above already pushed open bins down when wasteful.
        if post_residual == 0 {
            score -= 200.0; // never open a bin for an exact fit
        }
    }

    // Late-stream consolidation: prefer existing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0;

    // Slight preference to reduce bin count pressure.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Reward bins whose residual was already small (best-fit bias beyond raw post_residual).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Lookahead: if the next item fits exactly into post_residual, heavily favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            // Next item fits but leaves more dead space; mild penalty proportional to leftover.
            let chain_waste = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score += chain_waste * 12.0;
        } else {
            // Next item won't fit here; penalize bins whose residual is just below next item size
            // (unusable dead space for the lookahead).
            let gap = (next_item_size - post_residual) as f64;
            if gap > 0.0 && post_residual > 0 {
                score += (gap / next_item_size as f64) * 8.0;
            }
        }
    } else {
        // Last item: only the immediate fit matters.
        score += 5.0 * (1.0 - tightness);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Many options: prefer the tightest, add mild spread penalty.
        score += 2.0;
    }

    // Prefer bins below mean residual when they still fit well (balance residual distribution).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.03;

    // Time horizon: early in the stream, be conservative about filling bins (keep flexibility);
    // late in the stream, prioritize immediate tightness more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * (1.0 - progress);

    // New-bin candidate: only attractive when item is large relative to capacity
    // (a fresh bin gives a full 100 residual for future items) or when current bins are crowded.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 30.0;
        let crowd_penalty = open_bins_count as f64 * 1.5;
        score += 20.0 - large_item_bonus + crowd_penalty;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, with smooth non-linear penalty for tiny leftovers
    let mut score = pr as f64;

    // Dead-space penalty: smooth quartic-ish blowup for very small post_residual
    let dead = (1.0 - norm_pr).powi(2);
    score += 30.0 * dead * (1.0 - norm_pr);

    // Progress coupling: as stream progresses, prefer tighter fits more aggressively
    score -= (1.0 - progress) * 8.0 * norm_pr;
    score += progress * 12.0 * norm_pr * norm_pr;

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = (pr - nxt).max(0.0);
        let fits = if pr >= nxt { 1.0 } else { 0.0 };
        score -= fits * (12.0 - 6.0 * (fit_next / cap));
        // penalize leaving space that neither helps nor is usable
        score += (1.0 - fits) * 6.0 * (1.0 - norm_pr);
    }

    // Mild dispersion penalty: bins far from mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Slight preference to consolidate when many bins open
    score += (open_bins_count as f64).ln() * 0.5 * (1.0 - norm_pr);

    // Smooth polynomial coupling of progress with item size ratio
    let ir = item_size as f64 / cap;
    score -= 10.0 * progress * ir * (1.0 - norm_pr) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // "harmonic bands" using integer division thresholds on capacity.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual_frac = post / cap; // 0..1 fraction of capacity left over

    // Harmonic class index: floor of capacity fraction in eighths.
    // Class 0 = perfect fit (dead space < 12.5% of capacity) -> strong reward.
    let class = (post_residual * 8 / bin_capacity) as f64;

    // Reward small dead space non-linearly (quadratic in fraction).
    score -= (1.0 - residual_frac) * (1.0 - residual_frac) * 10.0;

    // Penalize "awkward" harmonic classes: leftovers that few item sizes can use.
    // Items are 1..100; residuals in (0, item_min) are pure waste.
    if post_residual < 1 {
        score -= 50.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else {
        // Mid-range leftovers: mod-5 arithmetic — multiples of 5 are more
        // likely matchable if item sizes cluster on multiples of 5.
        let mod5 = post_residual % 5;
        if mod5 == 0 {
            score -= 6.0;
        } else {
            score += mod5 as f64 * 1.5; // penalize odd leftover classes
        }
        // Harmonic band penalty: class 3-5 (37%-75% leftover) is actually
        // reusable by mid items — mild reward; class 6-7 too big to waste but
        // still fine; class 1-2 (12.5%-37%) is the dead zone.
        if class >= 1.0 && class < 3.0 {
            score += 12.0; // dead zone: too small for most items
        } else if class >= 3.0 && class < 6.0 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: leftover after chain matters.
            let chain_left = post_residual - next_item_size;
            score -= 10.0 + (chain_left as f64).min(15.0);
        } else {
            // Next item won't fit here: leftover becomes waste unless another
            // future item uses it. Penalize proportionally to leftover size.
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the item is
    // large or existing bins are nearly full on average.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 8.0;
        // But if mean residual of open bins is small (they're packed tight),
        // opening fresh is good.
        score -= (mean_residual / cap) * 20.0;
        // Large items prefer fresh bins.
        score -= (item_size as f64 / cap) * 10.0;
        // Early in stream, opening bins is cheap (many items to come).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 6.0;
    }

    // Slight preference for fuller bins among equals (tighter packing).
    score -= (bin_residual - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead_threshold = 9.0; // gaps below smallest item (1..100 range) are risky
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 12.0;
        }
        // Mid-range gaps that fit nothing likely from the stream: mild penalty
        let prog = step_index as f64 / (total_items.max(1) as f64);
        let gap_useless = (post_residual as f64) < mean_residual * 0.25;
        if gap_useless {
            score += 8.0 * (0.5 + prog);
        }
    } else {
        // Perfect fill: strong reward
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to capacity)
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;

    // Open bins pressure: discourage spreading when many bins already open
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 6.0;
    }

    // New-bin candidate: only attractive when current bin would leave a big messy gap
    if bin_residual == bin_capacity {
        let avg_gap_penalty = mean_residual * 0.8;
        score += 20.0 - avg_gap_penalty;
        if post_residual == bin_capacity {
            // empty-bin baseline; make it expensive unless open bins are hopeless
            score += 30.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled.
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward bins whose post_residual can host next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // reward proportional to how closely post_residual matches next item
            let match_quality = 1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64);
            score -= 30.0 * match_quality;
        } else {
            // dead space relative to next item: penalize unusable remainder
            let dead = nxt - post_residual as f64;
            score += 0.5 * dead;
        }
    }

    // Compare against mean residual: bins with residual far below mean are "tight",
    // filling them is good (reduces fragmentation); penalize filling already-tight bins poorly.
    let res = bin_residual as f64;
    let dev = res - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item fits
    // very poorly everywhere (post_residual very large relative to capacity).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // opening a new bin is only attractive for large items or when no good fit exists
        if fill_ratio > 0.75 {
            score -= 25.0;
        } else {
            score += 20.0;
        }
    }

    // Late in the stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let residual_f = bin_residual as f64;
    let fill_ratio = item_size as f64 / residual_f.max(1.0);
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize large dead space after placement, but only if it is truly unusable
    // (smaller than the smallest plausible item ~ 1..100 stream, so below ~10).
    if post_residual < 10 {
        score -= 25.0; // perfect closure — great outcome
    } else if post_residual > 50 {
        score += 8.0 * (post_residual as f64 - 50.0) / 50.0; // wasteful leftover
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (sets up a perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let chain_tightness = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * chain_tightness;
        } else {
            // next item cannot follow here; slight penalty proportional to overshoot
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is justified when the item
    // fits poorly everywhere else or when existing residuals are highly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if mean_residual > 0.0 {
            (mean_residual - item_size as f64).abs() / mean_residual.max(1.0)
        } else {
            1.0
        };
        // Base cost of a fresh bin; discounted when open bins are fragmented or few.
        score += 35.0 - 10.0 * fragmentation.min(1.0);
        if open_bins_count == 0 {
            score -= 100.0; // nothing open: must use new bin
        }
        if next_item_size > 0 && next_item_size >= 60 && item_size >= 60 {
            score -= 25.0; // two big items pair well in a fresh bin
        }
    }

    // Time-horizon modulation: early in the stream, be conservative with existing
    // bins (keep flexibility); late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // Mild penalty for spreading across many open bins: encourage consolidation
    // when mean residual is large relative to item size.
    if bin_residual < bin_capacity && mean_residual > item_size as f64 * 2.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 + progress) - prn * progress * (1.0 - progress);
    score += 12.0 * poly;

    // Reward tight fits, stronger as stream progresses
    score -= (item_size as f64 / cap) * (1.0 + 3.0 * progress) * 8.0;

    // Penalize residual that fails to hold the lookahead item (smooth quadratic gate)
    if next_item_size > 0 {
        let fit = (pr / (next_item_size as f64).max(1.0)).min(1.0);
        score -= 6.0 * fit * fit * (1.0 + progress);
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty when bin residual deviates from mean residual across open bins
    score += 0.05 * (pr - mean_residual).abs();

    // Slight new-bin aversion growing with number of open bins
    if bin_residual == bin_capacity {
        score += 2.0 + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common item sizes) are preferred.
    let classes: [u32; 6] = [10, 20, 25, 30, 40, 50];
    let mut class_bonus = 0.0;
    for c in classes.iter() {
        if post_residual >= *c && post_residual % c == 0 {
            class_bonus += 8.0;
        }
    }
    score -= class_bonus;

    // Penalize tiny dead space (waste) strongly.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits (small post_residual) with extra pull.
    if post_residual <= 15 {
        score -= 10.0;
    }

    // Integer-division threshold: post_residual / next_item_size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let fits_next = post_residual / next_item_size;
            score -= fits_next as f64 * 4.0;
            // Exact match: next item fills bin perfectly
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Next item cannot fit here; penalize if we still leave medium gap
            if post_residual >= 10 {
                score += 5.0;
            }
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New empty bin candidate: make it attractive only when current fit is bad
    // or many open bins already have large residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_pressure = mean_residual / bin_capacity as f64;
        // Prefer new bin when open bins are fragmented (high mean residual)
        // and item is large-ish.
        if item_size > 50 || waste_pressure > 0.5 {
            score -= 20.0 + 30.0 * waste_pressure;
        } else {
            score += 15.0 + 20.0 * (1.0 - progress);
        }
    }

    // Prefer filling bins that are already relatively full.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fullness * 12.0;

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals in [1, 12] are nearly unusable (min item = 1,
    // but small gaps rarely match future demand) -> strong penalty.
    if post_residual > 0 && post_residual <= 12 {
        score += (13 - post_residual) as f64 * 18.0;
    }
    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 25.0 * fill_ratio;
    }

    // Penalize leaving a gap just below next_item_size (blocks lookahead item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }
    // Reward if post_residual exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Open-bin pressure: prefer spreading load when many bins are open,
    // but discourage opening new bins when few exist.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make fresh bins attractive only when the
    // item is large relative to remaining capacity of open bins, or when
    // mean residual across open bins is small (poor fits everywhere).
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).max(0.0);
        // Default neutral-ish score; open only if open bins are nearly full.
        score = bin_capacity as f64 * 0.5 + (1.0 - pressure) * 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size && pressure > 0.5 {
            score -= 15.0; // pair large items into a fresh bin
        }
    }

    // Mild stream-progression tilt: later in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.93;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (1.0 - progress) * (1.0 - progress);
    score -= 12.0 * poly * (1.0 + norm_pr);

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize large dead space late in the stream (quadratic in progress).
    score += 20.0 * norm_pr * norm_pr * progress;

    // Last-chance bin: strong smooth reward.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_ratio = next_item_size as f64 / cap;
        score -= 6.0 * (1.0 - (fit_ratio - norm_pr).abs()) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Smooth penalty for wasted space relative to lookahead need.
        let gap = (post_residual as f64 - next_item_size as f64).abs() / cap;
        score += 4.0 * gap * gap;
    }

    // Coupling with mean residual: prefer bins deviating smoothly from the mean.
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Mild penalty for many open bins, scaled smoothly by progress.
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets penalize "awkward" leftovers
    let post_class = post_residual % 10;
    if post_class > 0 && post_class < 5 {
        score += 4.0; // small awkward remainder (dead space risk)
    } else if post_class >= 5 && post_class < 9 {
        score -= 1.5; // medium remainder, still usable for mid items
    } else if post_class == 0 {
        score -= 3.0; // perfectly divisible residual, ideal harmonic state
    }

    // Integer-division thresholds: residual in quarter-bands
    let quarter = post_residual / (bin_capacity / 4).max(1);
    score += match quarter {
        0 => 6.0,   // <25% left: nearly sealed bin, low utility
        1 => 0.0,
        2 => -2.0,
        _ => -1.0,
    };

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic bonus scaled by how well next item divides the leftover
            let after_next = post_residual - next_item_size;
            if after_next % 10 == 0 {
                score -= 5.0;
            } else {
                score -= 2.0;
            }
        } else {
            score += 3.0; // next item won't chain here
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 4.0;
    }

    // New-bin candidate: only attractive when no good harmonic fit exists
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a bin
        } else if post_class != 0 && quarter >= 2 {
            // an open bin leaves a clean divisible residual -> prefer it
            score += 2.0;
        } else {
            score += 8.0; // discourage wasting fresh bins early
        }
    }

    // Stream progression: late in stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for deviating from mean residual (balance open bins)
    score += 0.3 * ((post_residual as f64 - mean_residual).abs() / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1..10 range guard: treat < 10 as unusable dead space) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize very small but potentially usable gaps proportionally harder.
    if post_residual > 0 && post_residual < 20 {
        score += 20.0;
    }

    // Reward tight fits (post_residual near zero is ideal).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading items out.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing
    // bins would leave bad dead space or no bin fits well.
    if bin_residual == bin_capacity {
        // Neutral baseline for a new bin; slight penalty so tight fits in
        // existing bins win, but small enough that poor fits lose to it.
        score += 15.0;
    }

    // Lookahead coupling: if the next item could exactly fill this bin's
    // post-residual, reward leaving that gap; if next item cannot use the
    // post-residual at all, penalize it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 10.0;
        }
    }

    // Mean-residual coupling: when open bins are generally roomy, slightly
    // prefer filling them rather than the tightest one only.
    let mean_r = mean_residual;
    if (post_residual as f64) > mean_r {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), scaled by progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Chain fit: subtract a bonus proportional to how well the next item also fits.
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 40.0 + 0.5 * chain_waste * (1.0 - progress);
    } else if next_item_size > 0 {
        // Next item won't chain: penalize dead space, especially large leftovers.
        let dead = post_residual as f64;
        score += 0.3 * dead * (0.5 + progress);
        // Extra penalty if leftover is below the minimum item size (true dead space).
        if post_residual < 10 && post_residual > 0 {
            score += 25.0;
        }
    }

    // Relative-to-mean coupling: prefer bins that are already more filled than average.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.4 * (mean_residual - residual_f);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless nothing decent exists.
    if bin_residual == bin_capacity {
        score += 60.0 + 0.2 * open_bins_count as f64;
        // If next item is large, opening fresh may be reasonable.
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Last-chance bonus: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + (post_residual - next_item_size) as f64 / 8.0;
    }
    // If next item would exactly fill the bin, big reward (perfect pairing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0;
    }
    // Penalize creating dead space smaller than the minimum plausible next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 8.0;
    }

    // New-bin candidate handling: opening a bin is fine early or when open bins are fragmented,
    // but costly when a decent fit exists among open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // Prefer new bin when open bins have little usable room relative to item.
        score += 18.0
            - 30.0 * (1.0 - fragmentation)
            - 10.0 * (1.0 - progress)
            + (open_bins_count as f64) * 0.4;
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin can fit: must open new bin
        }
    } else {
        // Slight preference for filling bins with larger residuals (keep small residuals consolidated).
        score -= (bin_residual as f64) * 0.05;
        // Early in the stream, favor spreading across bins to build flexibility.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.2 {
            score += 3.0 * (1.0 - progress * 5.0);
        }
    }

    // Mild penalty when this bin's residual is far below the mean (already well-used bin).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Penalize small-but-nonzero residuals (dead space) via smooth quadratic bowl
    let dead = (norm_pr - 0.05).abs();
    score += 20.0 * dead * dead * cap;

    // Reward tight fits (small post_residual) with smooth exponential discount
    score -= 15.0 * (-norm_pr * 12.0).exp() * (1.0 + progress);

    // Last-chance bin: strongly reward using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 6.0 * (gap / cap) * (1.0 - progress);
        } else {
            score += 4.0 * (-gap / cap);
        }
    }

    // Mild penalty for proliferation of open bins
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // Mean-residual coupling: prefer bins near the mean residual (smooth deviation)
    score += 0.15 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // New-bin candidate: keep it neutral-to-slightly-high unless residuals are large
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (perfect fill is ideal).
    if post_residual == 0 {
        score -= 30.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 6.0 * tightness * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 22.0;
    }
    if next_item_size > 0 && next_item_size > post_residual {
        // Dead space that next item cannot use: mild penalty scaled by gap size.
        score += 0.15 * (post_residual as f64).sqrt();
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize relative to open-bin pressure, but allow
        // when all existing fits would be terrible (large dead space avoided).
        score += 12.0 + 5.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        score -= 2.0 * pressure;
    }

    // Prefer bins with residual below mean (compact bins), discourage dumping into large-residual bins.
    if (bin_residual as f64) > mean_residual {
        score += 0.5 * ((bin_residual as f64) - mean_residual).sqrt();
    } else {
        score -= 0.5 * (mean_residual - bin_residual as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Two-step lookahead: reward near-perfect chains (post_residual ~ next_item_size)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap == 0 {
            score -= 60.0; // exact 2-item chain: residual fully consumed next step
        } else {
            score += gap as f64 * 0.6; // penalize mismatch proportionally
        }
        // If next item cannot fit into post_residual, dead space risk
        if (next_item_size as u32) > post_residual {
            score += (next_item_size as f64 - post_residual as f64) * 0.35;
        }
    }

    // Reward tight fits now
    score -= (bin_residual - post_residual) as f64 * 0.25;

    // Penalize residuals far below mean (fragmented bin) mildly
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin when open bins fit,
    // unless the current item would leave a huge unusable residual everywhere.
    if bin_residual == bin_capacity {
        let base_penalty = if fitting_bins_count > 0 { 18.0 } else { -5.0 };
        score += base_penalty;
        // Early stream: keep bins open, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 6.0;
        // Late stream: new bin is fine
        score -= progress * 4.0;
    }

    // Slight bonus for using bins with low residual (best-fit flavor)
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio weighted non-linearly.
    let waste = post_residual as f64;
    let tight_bonus = (waste / bin_capacity as f64).powi(3) * 60.0;
    score -= tight_bonus;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // strongly reward this placement (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_fit = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 40.0 * (1.0 - chain_fit);
        } else {
            // Next item won't fit here anyway; slight penalty for fragmenting.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, use it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer new bins only when existing fits are terrible
    // or the stream is early (future flexibility matters).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let flexibility = 1.0 - progress;
        score = 100.0 - 45.0 * flexibility
            + if fitting_bins_count > 0 { 10.0 } else { -50.0 };
    }

    // Global state: many open bins with high mean residual -> encourage consolidation.
    if bin_residual != bin_capacity {
        let consolidation = (mean_residual - bin_residual as f64) / bin_capacity as f64;
        score += consolidation * 20.0;
        score += open_bins_count as f64 * 0.5;
    }

    // Time horizon: late in the stream, prioritize filling bins completely.
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / cap;

    // Reward tight fits: polynomial decay of residual, stronger as stream progresses.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Perfect-fit bonus, amplified late in the stream.
    if post_residual == 0 {
        score -= 25.0 + 20.0 * progress;
    }

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        let gap = post_residual as f64;
        let nxt = next_item_size as f64;
        if gap > 0.0 && gap < nxt {
            score += 6.0 + 8.0 * (nxt - gap) / cap * (1.0 + progress);
        }
        // Reward residuals that still accommodate the next item smoothly.
        if gap >= nxt {
            score -= 4.0 * (1.0 - (gap / cap)) * (0.3 + 0.7 * progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize mildly early, more when many bins open or mean residual is high.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.35 * open_bins_count as f64 + 0.05 * mean_residual;
        // Opening fresh is attractive when nothing fits well (large item relative to residuals).
        if item_size as f64 > mean_residual {
            score -= 4.0;
        }
    }

    // Smooth non-linear coupling: residual^2 normalized, scaled by stream progress.
    score += 0.0015 * (post_residual as f64).powi(2) * (0.5 + 0.5 * progress);

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in "useful"
    // residue classes (multiples of common item sizes) are worth keeping.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // Residuals that are multiples of 10 pair well with sizes 10..80 grid
        if class == 0 {
            score -= 6.0;
        } else if class == 5 {
            score -= 2.0;
        } else {
            score += (10 - class) as f64 * 0.8;
        }
    } else {
        // Perfect fit: strongest reward
        score -= 25.0;
    }

    // Integer-division threshold: small post_residual (<=5) is near-dead space
    if pr > 0 && pr <= 5 {
        score += 8.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0 + (next_item_size as f64) * 0.05;
        } else {
            // waste gap relative to next item
            score += (next_item_size - pr) as f64 * 0.15;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: keep it attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // If mean residual across open bins is small, opening fresh bin is good
        score = 40.0 - pressure * 30.0 + open_bins_count as f64 * 0.5;
    }

    // Slight preference to fill bins with smaller residuals first
    score += (bin_residual as f64) * 0.02;

    // Late-stream consolidation: as stream progresses, tighten packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if no plausible future item (min size 1, but realistically
    // small items) can use it; treat gaps below a threshold as waste.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward bins whose leftover can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Leaving a gap that neither fits the next item nor is useful: penalize.
            score += (post_residual as f64) * 0.5;
        }
    }

    // Open-bin pressure: discourage opening new bins when many bins exist,
    // encourage consolidation when few bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when the item fits
    // poorly everywhere else; default slight penalty so existing bins win ties.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If no existing bin fits, the new-bin call is the only candidate anyway;
        // if mean residual is high (fragmented bins), opening fresh is better.
        score -= mean_residual * 0.1;
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match of post_residual with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else {
            // penalize post_residuals that leave next item unplaceable
            let next_fits = post_residual >= next_item_size;
            if !next_fits {
                // dead space unless next item could use another bin anyway
                score += 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
            } else {
                // near-match bonus, decaying with distance
                score -= 30.0 * (1.0 - diff as f64 / bin_capacity as f64);
            }
        }
    }

    // Favor leaving residuals near mean (keeps bin population homogeneous)
    score += 0.6 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // spread load: slight penalty for hoarding into crowded-choice bins
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when current bins have poor residuals
    if bin_residual == bin_capacity {
        let poor_fits = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        // base cost of opening a new bin, discounted late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 45.0 - 15.0 * progress;
        // a fresh bin perfectly chains with next_item_size if it matches capacity
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64).abs() <= 5 {
            new_bin_score -= 20.0;
        }
        new_bin_score += poor_fits * -10.0; // poor fits elsewhere make new bin better
        score = new_bin_score + post_residual as f64 * 0.05;
    }

    // Prefer tighter fills overall
    score -= 20.0 * (item_size as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Penalize dead space relative to smallest expected future item (>=1).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if the next item can fit in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
            // Extra reward for chaining fits.
            if post_residual - next_item_size <= 10 {
                score -= 25.0;
            }
        } else {
            // Penalize leaving residual that just barely fails the next item.
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > -20.0 && gap < 0.0 {
                score += 20.0;
            }
        }
    }

    // Time horizon: early in the stream, be more conservative about opening new bins;
    // late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as i32;
    if new_bin == 1 {
        // New bin attractiveness decreases as stream progresses.
        score -= 40.0 * (1.0 - progress);
        // But if no open bin fits well (large item), opening a fresh bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    } else {
        // Favor existing bins more strongly as stream progresses.
        score -= 10.0 * progress;
    }

    // Global state coupling: many open bins with high mean residual -> prefer reusing bins.
    if open_bins_count > 4 && mean_residual > item_size as f64 {
        score -= 15.0;
    }
    // Penalize opening new bins when mean residual across open bins is large (fragmentation).
    if new_bin == 1 && mean_residual > 40.0 {
        score += mean_residual - 40.0;
    }

    // Mild preference for tighter bins (waste-aware best-fit flavor).
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening
    let mut score = norm_pr * norm_pr * 60.0 + norm_pr * 20.0;

    // Stream-progress coupling: later in the stream, tolerate larger post_residual less
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Dead-space penalty: post_residual that cannot fit the next item is wasted
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 25.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            // reward bins whose leftover still fits the lookahead
            score -= 10.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Mean-residual interaction: when open bins are already loose, discourage loosening more
    let mean_norm = mean_residual / cap;
    score += 8.0 * norm_pr * mean_norm * mean_norm;

    // Prefer reusing bins when many are open (avoid bin proliferation)
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // New-bin candidate: make empty bins mildly attractive only for large items
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        score = 15.0 - 20.0 * tightness * tightness + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is "dead space"
    // (below the minimum item size) are heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 0.0; // perfect fill, nothing to add
    }

    // Dead-space penalty: leftover too small for next item (if known)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // next item fits here: strong reward
        } else if post_residual >= (next_item_size / 2).max(min_item) {
            score += 4.0; // half-class: partial future usability
        }
    }

    // Modulo-class penalty: residuals that waste capacity in awkward
    // fractions of the bin are less reusable.
    let pr = post_residual as f64;
    let frac = pr / cap;
    if frac > 0.0 {
        if frac < 0.1 {
            score += 10.0; // tiny unusable sliver
        } else if frac < 0.25 {
            score += 3.0;
        } else if frac < 0.5 {
            score -= 2.0; // quarter-class: decent reuse potential
        } else {
            score -= 5.0; // large residual keeps bin flexible
        }
    }

    // Integer-division threshold class on next_item_size
    if next_item_size > 0 {
        let nxt_class = next_item_size / 20; // classes: 0..5
        let fits_exact = post_residual == next_item_size;
        if fits_exact {
            score -= 20.0; // perfect pairing with lookahead
        }
        match nxt_class {
            0 => score -= 1.0,          // tiny next item: any bin works
            1 => score += 0.5,
            2 => score += 0.0,
            3 => score -= 1.5,          // medium next: worth reserving space
            _ => score -= 2.5,          // large next: keep roomy bins
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // open bins are nearly full (small mean residual) or many bins exist.
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin, modulated by stream progress
        // and congestion among open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let congestion = if open_bins_count > 0 {
            mean_residual / cap
        } else {
            1.0
        };
        score += 25.0 - 10.0 * progress - 12.0 * (1.0 - congestion);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0; // fresh bin can host next item too
        }
    } else {
        // Prefer tighter fits among open bins: reward small post_residual
        // relative to what's already committed.
        let tightness = 1.0 - (post_residual as f64) / cap;
        score -= 5.0 * tightness;
    }

    // Mild penalty for spreading across too many bins when residuals are high
    if open_bins_count > 4 && mean_residual > 0.5 * cap && bin_residual < bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
