pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: item exactly fills the bin -> strongest reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward residuals that exactly match next item,
    // reward small residuals relative to next item, penalize large leftovers.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - nxt).abs() < 0.5 {
            score -= 400.0; // exact chain: next item seals this bin
        } else if pr < nxt {
            // leftover cannot fit next item; penalize proportionally to wasted space
            score += 0.5 * pr;
        } else {
            // leftover can host next item; reward closeness of fit
            score -= 1.5 * (nxt - (pr - nxt));
            if (pr - nxt) < 10.0 {
                score -= 100.0; // near-perfect two-item chain
            }
        }
    }

    // Penalize dead space: residuals too small for the minimum item size
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 300.0 };
        score += pressure + 50.0 * (open_bins_count as f64).min(10.0);
        // opening a new bin is fine when residual would be tiny elsewhere anyway
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 100.0;
        }
    } else {
        // Reward tightness relative to mean residual of open bins
        if (mean_residual - post_residual as f64) > 0.0 {
            score -= 0.8 * (mean_residual - post_residual as f64).min(50.0);
        }
        // Reward using bins that are already mostly full
        score -= 0.3 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for the smallest plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // nearly unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0; // awkward gap
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 6.0;
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled by wasted space.
            score += 3.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the current
    // bin's fit is poor. Base new-bin score is post_residual == capacity (large), so
    // adjust based on global state.
    if bin_residual == bin_capacity {
        // Early in stream, keep bins open (avoid bin proliferation).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 - 15.0 * progress;
        // If many open bins with slack, discourage new bin.
        score += 0.5 * open_bins_count as f64;
        // If mean residual is high (bins are roomy), opening new bin is wasteful.
        score += 0.3 * mean_residual;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size > 60 {
            score -= 10.0;
        }
    } else {
        // Favor bins whose residual is close to item_size (best fit coupling).
        let gap = (bin_residual - item_size) as f64;
        score -= 4.0 * (1.0 - gap / bin_capacity as f64);

        // Slight preference for fuller bins when many bins are open (consolidation).
        if open_bins_count > 3 {
            score -= 0.2 * (1.0 - bin_residual as f64 / bin_capacity as f64) * open_bins_count as f64;
        }
    }

    // Late-stream tightening: prioritize filling existing bins completely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: prefer small post_residual, with smooth non-linear shaping.
    let x = pr / cap; // normalized post residual in [0,1]
    let mut score = 10.0 * x + 20.0 * x * x;

    // Smooth coupling with stream progress: early on, tolerate loose fits;
    // late in the stream, tighten the penalty on wasted space.
    score *= 1.0 + 1.5 * progress * x;

    // Penalize dead space relative to the mean residual across open bins.
    score += 0.05 * (pr - mean_residual).abs();

    // Last-chance bonus: if this is the only bin that fits, reward using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 0.5 {
        score -= 6.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        // Partial reward proportional to how well next item uses leftover space.
        let use_ratio = next_item_size as f64 / pr.max(1.0);
        score -= 4.0 * use_ratio * use_ratio;
    }

    // New-bin candidate: penalize smoothly, scaled by how many bins already exist
    // and stream progress, so a new bin is only chosen when open bins fit poorly.
    if is_new_bin {
        let open = open_bins_count as f64;
        score += 15.0 + 0.5 * open + 10.0 * progress;
        // But if post residual of a new bin is tiny (item nearly fills a fresh bin),
        // opening a new bin is excellent.
        score -= 25.0 * (1.0 - x) * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod capacity fractions
    let post = post_residual;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Penalize residuals in awkward harmonic classes (small but unusable slivers)
    if post > 0 && post < 10 {
        score += 30.0; // dead space
    } else if post < quarter {
        score += (quarter - post) as f64 * 0.5;
    }

    // Reward residuals in "useful" harmonic classes: multiples of 10 or 20
    if post % 10 == 0 && post > 0 {
        score -= 6.0;
    }
    if post % 20 == 0 && post > 0 {
        score -= 4.0;
    }

    // Perfect fit bonus via integer division thresholds
    if post == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // Reward if next item lands in a harmonic-friendly leftover
            let leftover = post - next_item_size;
            if leftover % 10 == 0 {
                score -= 8.0;
            }
            score -= leftover as f64 * 0.3;
        } else {
            // Next item won't fit here; penalize proportionally to overshoot
            score += (next_item_size - post) as f64 * 0.4;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let frag = (mean_residual - post as f64).abs() / cap_f;
        score += 20.0 + frag * 40.0 - progress * 10.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Mild preference for tight bins (small residual before placement)
    score += (bin_residual as f64 / cap_f) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Reward tight fits relative to bin size.
    score -= 15.0 * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strong preference to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    score += 3.0 * open_bins_count as f64;
    score += 2.0 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when item is huge and no good fit exists.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill > 0.7 {
            score -= 20.0 * fill;
        } else {
            score += 30.0;
        }
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item's size (perfect chained fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 30.0; // perfect two-item chain
        } else if post_residual >= next_item_size {
            // penalize leftover after hypothetical next placement
            let chained = pr - nxt;
            score += 0.35 * chained;
        } else {
            // next item cannot follow in this bin: penalize by the gap
            score += 0.6 * (nxt - pr);
        }
    }

    // Dead-space penalty: tiny post residuals are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Prefer tight fits relative to mean residual of open bins.
    score += 0.25 * (pr - mean_residual).max(0.0);
    score -= 0.1 * (mean_residual - pr).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0; // fresh bin still allows chaining
        }
    }

    // Early in stream: be more willing to open bins for good structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score -= 2.0 * (1.0 - progress * 3.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Exact or near-exact fill gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Dead space for the known next item: penalize proportionally to waste.
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            score += 8.0 * gap / bin_capacity as f64;
        }
    }

    // Prefer fuller bins over emptier ones among open bins.
    let fullness = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= 12.0 * fullness;

    // Global residual pressure: if mean residual is low, avoid fragmenting further.
    let pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += 10.0 * pressure * fit_ratio;

    // Time horizon: early in the stream, tolerate opening new bins (explore);
    // late in the stream, squeeze into existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 20.0 + 60.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening a new bin is more attractive when many bins are already fragmented
        // and the item is large.
        score -= 0.05 * open_bins_count as f64 * (item_size as f64 / bin_capacity as f64);
    }

    // Mildly discourage bin proliferation.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let fit_ratio = item_size as f64 / cap;
    let nx = next_item_size as f64 / cap;

    // Base: penalize leftover space, with quadratic dead-space term
    let mut score = pr + 0.015 * pr * pr / cap;

    // Smooth non-linear coupling: post_residual shaped by stream progress
    // Early on, keep bins tight; late, tolerate residuals less (favor tight fits harder)
    let prog_shape = 0.5 + 0.5 * (progress * std::f64::consts::PI).sin();
    score += 2.0 * prog_shape * pr / cap;

    // Interaction: fit tightness vs next item lookahead
    let tightness = 1.0 - (pr / cap);
    let lookahead_bonus = if nx > 0.0 {
        // reward if next item fits into post_residual smoothly
        let fits_next = ((pr as f64) - nx).max(0.0) / cap;
        -1.5 * (1.0 - fits_next) * tightness
    } else {
        0.0
    };
    score += lookahead_bonus;

    // Reward using nearly-full bins (small post_residual) with cubic sharpening
    score -= 3.0 * (1.0 - pr / cap).powi(3) * fit_ratio;

    // Last-chance bin pressure: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - fit_ratio) * (1.0 + progress);
        // but allow new bin if it would waste almost nothing and current mean residual is fragmented
        score -= 2.0 * fit_ratio * (mean_residual / cap);
    }

    // Mild penalty proportional to number of open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Classify post_residual into harmonic bands via integer division on capacity/10.
    let band = post_residual / 10; // 0..=9 usable bands
    let band_penalty = match band {
        0 => 0.0,        // 1..9 dead space: small
        1 => 2.0,        // 10..19
        2 => 5.0,        // 20..29
        3 => 9.0,
        4 => 14.0,
        5 => 20.0,
        6 => 27.0,
        7 => 35.0,
        8 => 44.0,
        _ => 40.0,       // near-full bins (90..99) actually fine
    };
    score += band_penalty;

    // Reward bins whose post_residual can host the lookahead item exactly or well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 500.0; // chainable perfect fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / cap);
        } else {
            // lookahead cannot fit here: penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.3 * gap;
        }
    } else {
        // Last item: any bin that fits is fine; prefer tightest (post_residual small already).
        score -= 200.0;
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin gets baseline tied to mean residual.
    if bin_residual == bin_capacity {
        score = cap * 0.75 + 0.5 * mean_residual + 10.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // new bin also fits the lookahead
        }
        if fitting_bins_count == 1 {
            score += 200.0; // never open new bin when only one open bin fits
        }
    } else {
        // Mild preference for bins below mean residual (consolidate fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Stream progression: early on, slightly favor opening new bins (exploration);
    // late in stream, strongly avoid new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress) - 40.0 * progress;
    }

    // Modulo tiebreakers on post_residual for harmonic smoothness.
    let m = post_residual % 10;
    score += 0.1 * m as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Mid-range dead space (unlikely to fit typical items) mild penalty.
    if post_residual >= 10 && post_residual < 25 {
        score += 0.35 * (post_residual as f64 - 10.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: prefer using existing bins over spawning new ones.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor placing here before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward it.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if next item cannot fit in the residual (wasted pairing opportunity).
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Slight preference for bins with larger residuals when mean residual is low.
    score -= 0.1 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when all open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 25.0 + 3.0 * open_bins_count as f64 };
        score += pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but avoid dead space < 10 (min item).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable dead space penalty
    }

    // 2-step lookahead: reward if the next item fits exactly/nicely in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 10.0 - (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += 6.0; // next item won't fit here; keep residual flexible
        }
    }

    // Prefer bins whose residual is close to mean (balanced usage), unless perfect fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit
    // (i.e., post_residual in a fresh bin is large and current item is big).
    if bin_residual == bin_capacity {
        // Fresh bin baseline: raw capacity minus item; discourage unless item is large
        // or no good alternative exists.
        if item_size <= 50 && fitting_bins_count > 1 {
            score += 30.0; // keep using existing bins for small items
        }
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) < 10.0 {
            score += 20.0;
        }
        // Early stream: slightly encourage opening bins to build flexibility.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress) * (item_size as f64 / 100.0);
    }

    // Mild bonus for many open bins to consolidate when fragmentation is high.
    if open_bins_count > 5 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving large dead space.
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Many open bins with high mean residual => prefer consolidating into fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > 0.0 {
        let fullness_gap = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 10.0 * fullness_gap * (0.5 + progress);
    }

    // Penalize opening a new bin, more so as the stream progresses or bins are few.
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        // But if no open bin fits well (this call only happens for the new-bin candidate anyway),
        // relax the penalty when the item is large relative to capacity.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Small bonus for placing larger items early (big-first tendency).
    score -= 0.1 * item_size as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 40.0 * poly;

    // Penalize small residuals more as stream progresses (dead space matters late)
    let small = 1.0 - (norm_pr * 2.0).min(1.0);
    score += 25.0 * small * small * progress;

    // Reward tight fits
    let tight = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tight * tight;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let gap = pr as i64 - next_item_size as i64;
        if gap >= 0 {
            score -= 15.0 * (1.0 - (gap as f64 / cap)).abs();
        } else {
            score += 8.0 * (-gap) as f64 / cap;
        }
    }

    // Mild penalty for proliferating open bins when residuals are large
    score += (open_bins_count as f64).ln() * mean_residual * 0.05 * (1.0 - progress);

    // New-bin candidate: neutral baseline with slight progress-dependent cost
    if bin_residual == bin_capacity {
        score = cap - 10.0 * progress + (1.0 - tight) * 5.0;
        if fitting_bins_count <= 1 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exponential bonus as post_residual approaches 0
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Harmonic class of post_residual: dead-space classes penalized
    // Residuals in [1..9] are nearly unusable (min item size ~1, but small waste);
    // residuals that are multiples of capacity quarters are "friendly" classes.
    let pr = post_residual;
    if pr > 0 {
        let quarter = bin_capacity / 4;
        let class_penalty = if pr < 5 {
            6.0 // tiny dead space, hard to fill
        } else if pr % quarter == 0 {
            -8.0 // friendly class: divisible residual
        } else if pr % 10 == 0 {
            -4.0 // decade-friendly
        } else {
            2.0
        };
        score += class_penalty;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == pr {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // next item fits but leaves further residual: mild reward scaled by fit quality
        let nr_left = pr - next_item_size;
        score -= 12.0 * (1.0 - nr_left as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > pr {
        // next item won't fit here; residual likely wasted -> penalize large residuals
        score += 0.15 * pr as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is costly unless current fit is bad
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score = 55.0;
        // open new bin if existing fits are poor (item leaves big residual everywhere)
        let poor_fit = post_residual as f64 > 0.5 * bin_capacity as f64;
        if poor_fit {
            score -= 20.0;
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // many open bins with high mean residual -> reuse them instead
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
        if open_bins_count > 8 {
            score += 8.0;
        }
    }

    // Slight preference for fuller bins overall (best-fit flavor)
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (min size 1..10)
    // are pure waste; penalize heavily, most when gap is in the "unusable" band.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 40.0; // dead space below minimum item size
    } else if post_residual < item_size.min(20) {
        score += 15.0; // small gap, likely unusable soon
    } else {
        // residual usable: mild reward scaled by how well it can host the lookahead item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // keeps room for the next item
        }
    }

    // Exact-fit bonus: filling residual precisely with item or item+lookahead
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next < 10 && after_next > 0 {
            score -= 12.0; // lookahead leaves only tiny gap -> good chain
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is excellent
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Last-chance bin: strongly prefer using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if all open bins would leave bad fits
    if bin_residual == bin_capacity {
        let bad_fit_elsewhere = mean_residual < item_size as f64 * 0.5
            || (next_item_size > 0 && mean_residual < next_item_size as f64 * 0.5);
        if bad_fit_elsewhere {
            score -= 20.0;
        } else {
            score += 25.0; // keep using existing capacity when fits are decent
        }
    }

    // Slight tilt toward bins with tighter residual (best-fit flavor)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact 2-step lookahead match (post_residual == next_item_size)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 / (1.0 + diff)) - 12.0; // up to -12 for perfect match
        // Penalize post_residual that is small but unusable by next item
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.35 * post_residual as f64;
        }
        // Bonus if both item and next item fill the bin exactly
        if post_residual == next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 5.0;
    }

    // Relative to mean residual: prefer bins with residual near/below mean (well-packed)
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.25 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating tiny dead space (unusable for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Mild penalty on opening a brand-new bin when fitting bins exist
    if bin_residual == bin_capacity {
        score += 4.0 + 0.05 * open_bins_count as f64;
        // But if mean residual is very low (bins nearly full), new bin is fine
        if mean_residual < 15.0 {
            score -= 6.0;
        }
    }

    // Progression: slightly tighten packing as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * progress * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    score -= 60.0 * (-post_residual as f64 / 20.0).exp();

    // Penalize dead space: post residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits the post residual (chained packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.15 * next_item_size as f64;
        } else if next_item_size > bin_residual {
            // Next item won't fit anywhere here anyway; keep residual flexible.
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Crowding: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score -= crowd * 4.0 * (0.5 + progress);

    // Mean residual coupling: if this bin is below average residual (tighter than average), prefer it.
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Prefer bins whose residual matches item size well (modular fit reward).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.10 * gap;

    // Late stream: consolidate aggressively.
    score -= 20.0 * progress * (post_residual == 0) as i32 as f64;

    // New-bin candidate: make it moderately attractive only when existing bins are poor fits
    // (large gap) or late in stream with scattered residuals.
    if bin_residual == bin_capacity {
        let poor_fit = gap > 30.0;
        if poor_fit || (progress > 0.7 && mean_residual < 25.0) {
            score -= 12.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: tolerate larger residuals (spread items out).
    // Late in the stream: aggressively penalize wasted space.
    let t = progress;
    let w = 0.5 + 2.5 * t * t * (3.0 - 2.0 * t); // smoothstep-like weight in [0.5, 3.0]
    score += w * (pr * pr) / cap;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize when this is the only fitting bin (last-chance placement is valuable).
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = pr - nx;
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit here; slight penalty proportional to overflow.
            score += 1.5 * (nx - pr) / cap;
        }
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably
    // from the mean (below mean residual = tighter bin, good to fill).
    score += 3.0 * (mean_residual - bin_residual as f64) / cap;

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when open bins exist and could fit.
    if bin_residual == bin_capacity {
        let base = 20.0 + 30.0 * (1.0 - t);
        if open_bins_count > 0 {
            score += base + 10.0 * (open_bins_count as f64).ln();
        } else {
            score += 5.0;
        }
    }

    // Mild penalty for leaving many open bins with fragmented space.
    score += 0.5 * (pr / cap) * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals in low classes (small
    // leftover) are good; large leftover classes are penalized super-linearly.
    let cls = post_residual / 10; // harmonic class 0..10
    score += (cls as f64) * (cls as f64) * 1.7;

    // Perfect-fit bonus (residual falls into dead-space class 0..=5)
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Modulo-arithmetic coupling: does the leftover resonate with the
    // lookahead item? If post_residual can host next_item_size, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.35 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // leftover wasted w.r.t. lookahead: penalize by mismatch mod 10
        let m = post_residual % 10;
        score += 3.0 + 0.5 * m as f64;
    }

    // Integer-division threshold on item size: big items (>= half capacity)
    // prefer fresh bins to avoid fragmentation of partially filled bins.
    if item_size >= bin_capacity / 2 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when current item is
    // large and existing residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = (mean_residual < item_size as f64 * 1.2) as i32;
        let penalty = 15.0 + 30.0 * (1.0 - poor_fits as f64);
        score = post_residual as f64 + penalty - 8.0 * progress;
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer fuller bins overall: compare against mean residual.
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Mild pressure to consolidate when many bins are open.
    score += 0.4 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny dead space is a total waste
        } else if post_residual < 20 {
            score += 18.0;
        } else if post_residual > 60 {
            score -= 12.0; // large residual keeps flexibility
        }
    } else {
        score -= 30.0; // perfect fit reward
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish, slightly penalized unless current bin wastes space.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
        if post_residual < 20 {
            score += 20.0; // fresh bin wasted on small item
        }
    }

    // Lookahead: favor bins whose post_residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Stream progression: early on, be pickier about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward post_residual matching next_item_size
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let match_err = (post_residual as f64 - nx).abs();
        // Perfect chain fit: post_residual == next_item_size -> big reward
        if post_residual as f64 == nx {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // next item still fits in this bin afterwards
            score -= 12.0 - 0.15 * match_err;
        } else {
            // next item won't fit; penalize proportionally to shortfall
            score += 0.3 * (nx - post_residual as f64);
        }
    } else {
        // Last item: just minimize waste
        score = post_residual as f64;
    }

    // Penalize creating unusable dead space relative to smallest possible item (1..100, assume small floor)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny dead space is nearly worthless
    }

    // Compare against mean residual: prefer bins that keep residual near the mean
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        // early in stream, new bins are cheaper to open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference to fill bins that are already partially used heavily
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize high fill ratio less.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fill * fill;

    // Penalize dead space: small post_residual that can't hold typical items is fine,
    // but mid-range leftovers (~20-40) are prime waste.
    let pr = post_residual as f64;
    if pr > 0.0 {
        let dead = (pr / cap - 0.25).abs();
        score += 12.0 * dead * (1.0 - pr / cap);
    }
    if post_residual == 0 { score -= 30.0; }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: leftover is dead for the horizon
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_residual as f64 / cap);

    // Global state: many open bins with high mean residual -> favor packing into existing bins.
    if open_bins_count > 2 {
        score -= 0.5 * (open_bins_count as f64).ln() * (mean_residual / cap);
    }

    // New-bin candidate: only attractive when the item is huge relative to capacity
    // or nothing fits well (poor fit into open bins).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let big_item = item_size as f64 / cap;
        score += 55.0 - 40.0 * big_item;
        if fitting_bins_count <= 1 { score -= 20.0; }
    } else if item_size >= 70 {
        // large items fit almost anywhere; prefer the emptiest bin
        score -= 5.0 * (bin_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear penalty on waste
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Stream-progress coupling: as the stream advances, penalize residual more strongly
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += progress_coupling * norm_pr * cap * 0.6;

    // Interaction with mean residual: avoid bins far from the fleet average (fragmentation)
    let dev = (pr - mean_residual).abs();
    score += 0.35 * dev * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        let compat = if pr >= n { 1.0 - gap / cap } else { -0.5 * gap / cap };
        score -= 8.0 * compat * (0.3 + 0.7 * progress);
    } else {
        // Last item: maximize fill, minimal penalty
        score -= 15.0;
    }

    // Mild penalty for spreading across too many open bins late in the stream
    score += 0.02 * open_bins_count as f64 * progress;

    // Smooth new-bin handling: a fresh bin has pr == cap; make it unattractive
    // unless the fit into open bins is poor (large post_residual elsewhere)
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: coarse integer-division classes.
    // Residuals in [0,10) are dead space -> heavy penalty; larger classes get graded rewards.
    let class = post_residual / 10;
    match class {
        0 => score += 60.0,                              // unusable sliver
        1 => score += 20.0,                              // poor
        2 => score += 5.0,                               // mediocre
        3 => score -= 10.0,                              // decent
        4 => score -= 20.0,                              // good (residual 40-49)
        5 => score -= 30.0,                              // very good
        6 => score -= 35.0,                              // excellent
        _ => score -= 40.0,                              // near-empty bin still fresh
    }

    // Harmonic coupling: does the NEXT item's class align with post_residual class?
    // Reward when next_item_size fits harmonically into post_residual (post_residual % next_item_size small relative).
    if next_item_size > 0 && next_item_size <= post_residual {
        let r = post_residual % next_item_size;
        score -= (10.0 - (r.min(next_item_size - r)) as f64) * 0.5; // near-divisibility bonus
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this leftover: penalize large leftover more.
        score += (post_residual as f64) * 0.3;
    }

    // Exact-fit harmonic classes on capacity fractions: post_residual near multiples of 25/33/50.
    let pr = post_residual as i64;
    let harmonics = [50i64, 33, 25, 20, 34, 66];
    for h in harmonics.iter() {
        let d = (pr - h).abs();
        if d <= 3 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: prefer it only when this item is large and mean residual is small,
    // or when many bins already exist and item is big (fragmentation risk).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size >= 60;
        if big_item || (mean_residual < item_size as f64 * 0.5 && open_bins_count > 3) {
            score -= 15.0 + 10.0 * progress;
        } else {
            score += 30.0; // discourage opening bins for small items
        }
    }

    // Mild pressure toward consolidating: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any future item
    // (items >= 1, but practically gaps below ~10 are near-worthless) are heavily penalized.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Mid-range dead space (10..=20) is also hard to fill: soft penalty.
    if post_residual >= 10 && post_residual <= 20 {
        score += 2.0 * (20.0 - post_residual as f64) as f64;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless it enables a good
    // chain (item + next item pack well together).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            // next item would fit alongside in a fresh bin: encourage opening.
            new_bin_penalty -= 45.0;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            // next item won't fit with this one anyway: discourage.
            new_bin_penalty += 10.0;
        }
        score += new_bin_penalty;
    }

    // Lookahead: if next item exactly consumes the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.5 * next_item_size as f64;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += 0.8 * open_bins_count as f64;

    // Slight preference for filling fuller bins (low residual) early.
    score += 0.3 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches the next item (perfect 2-step fit)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Soft reward: post_residual is close to next item size (near-perfect lookahead fit)
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + gap * 0.15);
    }

    // Penalize residual that can't fit the next item (dead space relative to lookahead)
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Penalize small unusable residuals (< 10, minimum item size)
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but allow it when residuals are tight (mean residual low).
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let tightness = (mean_r / bin_capacity as f64).clamp(0.0, 1.0);
        // If open bins are quite full, opening a new bin is fine; otherwise penalize.
        score += 30.0 - 35.0 * tightness;
        // Never open a new bin if the current bin fits the item well
        if bin_residual >= item_size && fitting_bins_count >= 1 && next_item_size > 0 && bin_residual - item_size >= next_item_size {
            score += 25.0;
        }
    }

    // Prefer filling bins that are already low relative to the mean (compact usage)
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= diff * 0.3;
    }

    // Late in the stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if the next item fits exactly into the post-residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item won't fit here; penalize wasted residual
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // existing residuals are poor fits for the item
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64).powi(2);
        score += 60.0 - 50.0 * tightness;
        // open new bin more readily late in the stream or when many bins open
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * t;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // reward using bins that are already fragmented (below mean residual)
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
        // slight preference for tighter bins (smaller post-residual relative)
        let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 12.0 * fill;
    }

    // Penalize leaving dead space that is too small for the smallest item (1..100 range, min 10 typical)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear dead-space penalty: small post_residual is good unless it's a useless sliver.
    let post_norm = post / cap;
    let dead = (1.0 - post_norm).powi(3) * 12.0; // rewards very tight fits
    score -= dead;

    // Penalize unusable slivers (post_residual too small for any plausible item) with smooth coupling.
    let sliver = (-post_norm * 8.0).exp() * 6.0;
    score += sliver;

    // Lookahead coupling: reward when next item fits exactly-ish into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 10.0 * (-gap / 12.0).exp();
        // penalize if next item cannot fit at all
        if nxt > post {
            score += 3.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - post_norm);
    }

    // New-bin candidate handling: neutral-ish early, discouraged late or when mean residual is ample.
    if bin_residual == bin_capacity {
        let mean_pull = (mean_residual / cap).clamp(0.0, 1.0);
        score += 4.0 + 10.0 * mean_pull * (0.3 + 0.7 * progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild preference for filling more-full bins as stream progresses.
    score += 2.0 * progress * (1.0 - (bin_residual as f64 / cap));

    // Slight penalty for spreading across many open bins.
    score += 0.15 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that form "usable" slots
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Integer division thresholds: classify post_residual into usable size classes
    let class = pr / 10; // harmonic class bucket (0..=10)
    match class {
        0 => score -= 60.0,                 // near-perfect fit
        1 => score -= 35.0,                 // excellent
        2 => score -= 20.0,                 // good (fits medium items)
        3 => score -= 12.0,
        4 => score -= 6.0,
        5 => score -= 2.0,
        6 => score += 2.0,
        7 => score += 5.0,
        8 => score += 9.0,
        9 => score += 14.0,
        _ => {}                              // class 10 = untouched new bin
    }

    // Modulo arithmetic: residues divisible by 5 or 10 are more "packable"
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: does post_residual harmonically fit next_item_size?
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            // exact divisibility / small residue => strong reward
            let gap = pr - n;
            if gap == 0 {
                score -= 70.0;
            } else if gap % 10 == 0 {
                score -= 45.0;
            } else if gap <= 10 {
                score -= 30.0;
            } else {
                score -= (20.0 - gap as f64 * 0.15).max(4.0);
            }
        } else {
            // next item cannot use this residual: penalize wasted capacity
            score += prf * 0.25;
            // but if bin is small-residual anyway, mild penalty only
            if pr <= 20 {
                score -= 10.0;
            }
        }
    }

    // Tightness relative to capacity fraction
    let fill = (bin_capacity - pr) as f64 / cap;
    score -= fill * fill * 10.0; // reward fuller bins quadratically

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).max(1.0);
        let mean_tight = 1.0 - (mean_residual / cap);
        score = cap as f64 * 0.55
            - mean_tight * 30.0
            - (open_bins_count as f64).ln() * 6.0
            + 40.0 / pressure;
        if next_item_size > 0 && next_item_size >= 40 {
            score -= 12.0; // big upcoming item: fresh bin valuable
        }
        if step_index + 1 == total_items {
            score += 100.0; // last item: never open a bin
        }
    }

    // Progression: early stream, be slightly conservative about sloppy fits
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * prf * 0.05;

    // Mean residual context: avoid leaving residual far from the fleet mean
    score += (prf - mean_residual).abs() * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Small gap: only usable if the next item is tiny.
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 10.0; // gap is actually useful for lookahead item
        } else {
            score += 25.0;
        }
    }

    // Reward tight fits (low post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain of good fits).
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // Next item cannot use this bin's leftover; dead space likely.
        if post_residual > 0 && post_residual < next_item_size as u32 {
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: penalize spreading across many open bins when
    // residuals are large; encourage consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score += 0.6 * open_bins_count as f64 * (1.0 - progress);
    }

    // New-bin candidate handling: only attractive when open bins have poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 12.0 + 1.5 * open_bins_count as f64;
        // If mean residual is large, open bins are wasteful already -> prefer them.
        if mean_residual > (item_size as f64) * 1.5 {
            score += 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        score += 10.0 * progress;
    }

    // Mild preference for bins with residual close to item size (efficient packing).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // --- Aggressive 2-step lookahead: exact match of post_residual with next item ---
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Strong reward when next item fills this bin's remainder exactly
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // Penalize mismatch, scaled by how big the mismatch is
            score += diff * 0.6;
        }
        // Extra reward if next item fits perfectly AND post_residual is small
        if next_item_size <= post_residual && diff < 10.0 {
            score -= 15.0;
        }
        // Penalize leaving a remainder that cannot hold the next item at all
        if post_residual < next_item_size && post_residual > 0 {
            // Dead space: can't be used by next item; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    } else {
        // Last item: minimize final waste strongly
        score += post_residual as f64 * 0.5;
    }

    // --- Relative to mean residual: prefer bins already below-average residual ---
    // (tight bins are more valuable to fill; loose bins can wait)
    let mean_diff = mean_residual - post_residual as f64;
    score -= mean_diff * 0.25;

    // --- Last-chance bonus: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: neutral baseline, but discourage when a good fit exists
        // (score slightly above a perfect-fit open bin, below a terrible fit)
        score += 20.0;
        // Late in the stream, opening new bins is more wasteful
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
        // If few open bins, allow new bins more freely
        if open_bins_count <= 2 {
            score -= 10.0;
        }
        // If next item is large, a fresh bin is attractive
        if next_item_size >= 50 {
            score -= 12.0;
        }
    }

    // Mild penalty for very small unusable remainders (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: early on be exploratory, later consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let urgency = progress * progress;

    // Reward near-perfect fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if fit_ratio > 0.8 {
        score -= 12.0;
    }

    // Penalize leaving dead space that is hard to reuse (small leftover).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size <= bin_residual && next_item_size > item_size {
            // next item would have fit before but not after: mild penalty
            score += 6.0;
        }
        // If next item is large, keep large-residual bins fresh.
        if next_item_size > 60 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins, penalize spreading.
    let crowding = open_bins_count as f64;
    score += crowding * 0.5 * (1.0 - fit_ratio);

    // Mean residual coupling: bins with residual far below mean are precious (close them);
    // bins with residual above mean are good targets for filling.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev * (1.0 + urgency);

    // New-bin candidate: penalize opening a new bin unless the item is large relative
    // to mean residual or the stream is early and bins are crowded.
    if bin_residual == bin_capacity {
        let avg_item = bin_capacity as f64 - mean_residual;
        let worth_opening = (item_size as f64) > avg_item * 1.3
            || (progress < 0.3 && open_bins_count > 4);
        if worth_opening {
            score -= 18.0;
        } else {
            score += 25.0;
        }
    }

    // Late-stream tightening: as we approach the end, minimize waste aggressively.
    score *= 1.0 + urgency * 0.4;

    // Small stabilizer against ties favoring variety across steps.
    score -= ((step_index % 7) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.8 * progress + 0.6 * progress * progress);

    // Penalize dead space that cannot fit the next item (smooth quadratic penalty)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).max(0.0) / cap;
        score += 2.0 * gap * gap * cap * (1.0 - progress);
        // Reward bins whose post-residual closely matches the next item
        let fit_gap = (pr - nxt).abs() / cap;
        score -= 1.5 * (1.0 - fit_gap) * (1.0 - fit_gap);
    }

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 3.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.1 * (mean_residual - pr).abs() / cap;

    // Encourage tight fits (small post residual) with a quadratic term
    score += 0.5 * norm_pr * norm_pr;

    // New-bin candidate: smooth bias that grows late in the stream when residuals are fragmented
    if bin_residual == bin_capacity {
        score += 0.3 + 0.7 * progress * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill classes are heavily rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: near-zero residual is the ideal placement.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0 + 30.0 * (6 - post_residual) as f64;
    }

    // Harmonic classes via integer division thresholds on post_residual.
    // Residuals that are "reusable" by common small items are good; dead zones bad.
    let dead_zone = pr > 0.0 && pr < 10.0;
    if dead_zone {
        score += 120.0; // unusable sliver (min item size is 1, but tiny slots rarely reused)
    }

    // Modulo arithmetic on post_residual w.r.t. capacity fractions.
    // Class residuals into quarters of the capacity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual >= quarter && post_residual < half {
        score -= 20.0; // mid-slot: still useful for medium items
    } else if post_residual >= half {
        score -= 40.0; // large slot remains: very reusable
    }

    // Exact modulo bonus: residual divisible by common item granularities.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 2.0;
        } else {
            // next item won't fit here: mild penalty proportional to overflow gap
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin fits well. Penalize the fresh bin by its full emptiness cost,
    // discounted slightly by stream progression and open-bin pressure.
    if bin_residual == bin_capacity {
        score += 60.0
            + 0.05 * open_bins_count as f64
            + 40.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    } else {
        // Slight preference to keep number of open bins stable.
        score += 0.02 * open_bins_count as f64;
    }

    // Coupling with mean residual: bins far below mean residual are "wasted" space;
    // prefer filling bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) - mean_residual.abs();
    score += 0.1 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever host a
    // meaningful item (min size 1, but practically tiny gaps are waste).
    // Penalize unusable gaps quadratically once below a dead-zone threshold.
    let dead_zone = 12.0f64;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64).powi(2) * 3.0;
    }

    // Reward tight fits: small post_residual relative to capacity is good.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Penalize bins whose residual is much larger than needed (wasteful use
    // of a big gap on a small item) unless it is the only fitting bin.
    if fitting_bins_count > 1 {
        let overshoot = bin_residual as f64 - item_size as f64 - dead_zone;
        if overshoot > 0.0 {
            score += overshoot * 0.25;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins; few open bins -> new bin is cheaper.
    let bin_pressure = open_bins_count as f64 / 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are already open,
        // discount when stream is early or open count is small.
        score += 20.0 * bin_pressure;
        score -= 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    } else {
        score -= bin_pressure * 2.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly (perfect pairing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Prefer bins deviating favorably from the mean residual: a bin with
    // less residual than average absorbs fragmentation.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: post_residual exactly matches next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Lookahead: penalize post_residual that cannot fit the next item (dead space w.r.t. lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space after this placement relative to the next item.
            score += (next_item_size - post_residual) as f64 * 0.5;
        } else {
            // Slack that still accommodates the next item: mild reward scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + slack * 0.1);
        }
    }

    // Reward tight fits overall (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 25.0;

    // Penalize bins far from mean residual (avoid fragmenting the pool unevenly).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement is very wasteful.
    if bin_residual == bin_capacity {
        // Waste of the current bin if we skip it: how much space is left behind.
        let waste = post_residual as f64; // residual of new bin
        score += 30.0 + waste * 0.3;
        // Allow new bin if existing bins would leave tiny unusable residuals anyway.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 50.0;
        }
    }

    // Early in the stream, be more liberal about consolidating (slightly favor existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization is quadratic-ish in dead space)
    let waste = post_residual as f64;
    score += 0.02 * waste * waste / bin_capacity as f64;

    // Penalize bins whose post-residual is too small to hold any plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space: unusable fragment
    }

    // Lookahead: reward bins where next item fits perfectly after this placement
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect pair
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 / (1.0 + slack / 20.0); // next item still fits reasonably
        } else {
            score += 8.0; // next item won't fit here; keep flexible bins free
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when fits are poor
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used only when justified
        score += 55.0;
        // Reduce penalty early in stream (exploration) and when open bins are fragmented
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 35.0 * (1.0 - progress);
        if mean_residual < item_size as f64 * 1.2 {
            score -= 20.0; // open bins are all tight; fresh bin is fine
        }
    } else {
        // Reward filling existing bins more when many bins are open (consolidation pressure)
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins with residual close to item size (best-fit flavor, non-linear)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    // Slight preference for bins below mean residual (balance the pool)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer small post residual, with non-linear shaping
    let mut score = r * (1.0 + 0.8 * progress * progress);

    // Smooth penalty on very small residuals (dead space), stronger late in stream
    let dead = (1.0 - rn).powi(3);
    score += 25.0 * dead * (0.3 + 0.7 * progress);

    // Coupling: mid-range residuals are valuable; penalize extremes smoothly
    let mid = (rn * (1.0 - rn) * 4.0).sqrt();
    score -= 12.0 * mid * (1.0 - progress);

    // Last-chance bonus: avoid opening new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 10.0 * progress;
    }

    // New-bin candidate handling: allow early / when next item needs space
    if bin_residual == bin_capacity {
        let need_new = next_item_size as f64 > r
            || open_bins_count == 0
            || (progress < 0.25 && mean_residual < 0.35 * cap);
        if need_new {
            score -= 20.0 + 15.0 * (1.0 - progress);
        } else {
            score += 15.0 * progress;
        }
    }

    // Lookahead: reward residual that can hold the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 + 6.0 * (1.0 - progress);
    }

    // Mild preference to keep mean residual high (balanced bins)
    score -= 0.05 * mean_residual * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of 10, and small leftovers) are rewarded.
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let fill = 1.0 - (pr as f64) / cap;

    // Reward high fill ratio (small post residual) non-linearly.
    score -= 40.0 * fill * fill;

    // Harmonic class: post_residual divisible by 10 leaves room for typical items.
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    // Dead-space penalty: tiny unusable leftovers.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Modulo-5 classes of next_item_size: can the next item fit in the leftover?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0;
            // Exact harmonic match: next item leaves another clean residue.
            if (pr - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += 5.0;
        }
        // Penalize leaving space that is awkwardly just above the next item's class.
        let next_class = (next_item_size / 10) * 10;
        if pr > next_class && pr < next_class + 5 {
            score += 4.0;
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer using existing bins when many are open (encourage bin consolidation).
    score -= (open_bins_count as f64).sqrt() * 0.5;

    // New-bin candidate: penalize opening a fresh bin unless the item is huge
    // and would leave a clean residue elsewhere anyway.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size > 70 {
            score -= 25.0;
        }
        // Harmonic check: item_size in a "good" class (multiple of 10) is fine in a new bin.
        if item_size % 10 == 0 {
            score -= 5.0;
        }
    }

    // Mild stream-progression pressure: tighten packing as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * fill;

    // Coupling with mean residual: prefer bins below mean residual (tighter bins).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // Penalize if next item would not fit in the residual (wasted future space).
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 1.5;
        // But if residual is very tight everywhere, opening a bin may be fine.
        if mean_residual < (item_size as f64) * 0.5 {
            score -= 10.0;
        }
    }

    // Prefer tighter bins overall (relative to mean residual).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Mild stream progression: late in stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Post residual can fit the next item (partial lookahead match)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0 * (post_residual as f64 - next_item_size as f64).min(20.0);
    } else if next_item_size > 0 {
        // Dead space that cannot fit next item: penalize proportionally
        score += 0.5 * (next_item_size as f64 - post_residual as f64).min(30.0);
    }

    // Reward tight fits (small post residual)
    score -= 1.5 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Relative to mean residual: prefer bins with residual below mean (consolidate space)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New empty bin candidate: penalize mildly unless nothing else fits well
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate harder, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual closely matches the item.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize tiny dead space that no future item (min size 1..100) can use productively,
    // but allow small post_residual if it's near zero (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item: prefer zero-waste closure.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer fuller bins overall: couple with global mean residual.
    // A bin whose residual is below the mean residual is "fuller" -> reward.
    let residual_gap = mean_residual - bin_residual as f64;
    score -= 0.15 * residual_gap;

    // Time horizon: early in the stream, be conservative (avoid fragmenting bins);
    // later, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 5.0 * (bin_residual as f64 / bin_capacity as f64);

    // Crowding: with many open bins, discourage spreading into low-fill bins;
    // encourage consolidation.
    if open_bins_count > 4 {
        score += 0.4 * (open_bins_count as f64).ln() * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if existing fits are terrible
        // (large post_residual waste) or no bin fits well.
        let waste_existing = post_residual as f64; // for a new bin, post_residual = C - item
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalize new bins moderately; small items should never open new bins.
        score += 10.0 + 12.0 * item_frac;
        // But if the stream is early and many bins are open with low mean residual,
        // opening fresh space can help future large items.
        if progress < 0.3 && mean_residual < 30.0 && item_size >= 60 {
            score -= 14.0;
        }
        // Late in stream: strongly discourage new bins.
        if progress > 0.7 {
            score += 15.0;
        }
        let _ = waste_existing;
    }

    // Nonlinear coupling: reward near-exact fills with a sharp valley.
    let exactness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * exactness * exactness * exactness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: non-linear polynomial in post_residual, scaled by stream progress.
    // Later in the stream, tight fits matter more (dead space is costlier).
    let mut score = norm_pr.powf(1.0 + 1.5 * progress) * cap;

    // Smooth coupling: penalize residuals that waste capacity relative to mean residual
    let mean_gap = pr - mean_residual;
    score += 0.35 * mean_gap * (0.5 + progress);

    // Quadratic dead-space term: strongly punish mid-range residuals (unusable gaps)
    score += 0.8 * norm_pr * (1.0 - norm_pr) * cap * (1.0 - progress);

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 6.0 * snug * (0.4 + 0.6 * progress);
    } else if next_item_size > 0 {
        // post-residual too small for next item: penalize proportionally to wasted space
        score += 3.0 * norm_pr * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate handling: opening a bin is costly, but acceptable early
    // or when this bin would be left with a very awkward residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let awkwardness = if next_item_size > 0 {
            (next_item_size as f64 / cap).powf(2.0)
        } else {
            0.0
        };
        score = cap * (0.9 + 0.6 * progress) - 20.0 * awkwardness * (1.0 - progress);
        // More open bins => less eager to open yet another
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    // Class 1: post_residual in 1..=10 (nearly full, dead space) -> mild penalty.
    // Class 2: post_residual divisible cleanly into common item sizes -> reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // dead-space penalty grows for tiny unusable leftovers
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 2.0;
        }
        // harmonic divisibility: leftover that can host typical small items is valuable
        let mut div_bonus = 0.0;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                div_bonus += 6.0;
            }
        }
        score -= div_bonus;
        // integer-division class: leftover in high quarter of capacity is roomy
        let quarter = bin_capacity / 4;
        if post_residual >= 3 * quarter {
            score -= 8.0;
        } else if post_residual >= quarter {
            score -= 3.0;
        } else {
            score += 4.0;
        }
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chaining possible: reward proportional to how snugly next item fills
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 20.0 - chain_waste * 0.2;
        } else {
            // next item won't fit here; leftover likely becomes dead space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Prefer filling existing bins over opening new ones as stream matures
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many bins open or early on
        score += 15.0 + 10.0 * progress + open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 10.0; // existing capacity is plentiful; don't open a bin
        }
    } else {
        // mild reward for tightening residual spread toward the mean
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 5.0 / (1.0 + dev);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        // Items are >= 1; treat gaps below a "usable threshold" as pure waste.
        let usable_threshold = 12.0;
        if (post_residual as f64) < usable_threshold {
            // Dead space: penalize heavily, worse the smaller the gap relative to threshold.
            score += (usable_threshold - post_residual as f64) * 6.0;
        }
        // Reward large leftover space mildly (it stays flexible for future items).
        score -= (post_residual as f64) * 0.25;
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading into new bins
    // and encourage using existing residual mass.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += bin_pressure * (0.5 + progress);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item fits
    // very poorly everywhere (handled by the above rewards/penalties).
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * progress;
        // If the next item would fit perfectly in the fresh residual, soften a bit.
        if next_item_size > 0 && next_item_size == bin_residual {
            score -= 20.0;
        }
    }

    // Lookahead coupling: if next item exactly fills the post_residual,
    // reward this placement (chained perfect fit).
    if next_item_size > 0 && next_item_size as f64 == post_residual as f64 {
        score -= 18.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // Next item cannot use the leftover: leftover risks becoming dead space.
        score += (post_residual as f64) * 0.35;
    }

    // Mean-residual coupling: bins far below mean residual are less attractive
    // (keep "roomy" bins roomy, fill tight bins first).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small leftover (<=10).
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 30.0 - 2.0 * slack;
        } else {
            score += 0.5 * slack;
        }
    }
    // Next item cannot fit in this residual: mild penalty, worse if residual is small dead space.
    else if next_item_size > 0 {
        score += 5.0;
    }

    // Prefer bins whose residual is below the mean (tighter bins get packed first),
    // keeping larger residuals available for bigger future items.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fitting options exist, especially
    // early/mid stream where consolidation matters most.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 40.0 - 10.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // a fresh bin perfectly accommodates the next item too
        }
    }

    // Slight preference to fill bins with many open bins (reduce bin count pressure).
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post;

    // Reward tight fills: the fuller the bin after placement, the better.
    score -= 30.0 * (1.0 - post / cap);

    // Lookahead: if the next item can also fit here, chain placement is valuable.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 18.0 * (1.0 - (next_item_size as f64) / cap);
    }

    // Penalize tiny dead space that likely nothing can use (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Brand-new empty bin candidate: default penalty so it's chosen only on merit.
    if bin_residual == bin_capacity {
        score += 30.0 + 25.0 * t;
        // A large item with no other option, or early stream, justifies a fresh bin.
        if item_size >= 50 && (fitting_bins_count <= 1 || t < 0.2) {
            score -= 60.0;
        }
    }

    // Mild global-pressure coupling: prefer bins below the mean residual
    // (drain the emptiest usable bins first to consolidate).
    score += 0.08 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer tight fits (small post residual), with non-linear sharpening
    let mut score = r + 40.0 * rn * rn;

    // Smooth stream-progress coupling: early on, tolerate larger residuals;
    // late in the stream, aggressively minimize post residual.
    let progress_shaping = 1.0 + 2.5 * t * t;
    score *= progress_shaping;

    // Interaction: post residual vs mean residual of open bins.
    // If this bin's post residual is far below the mean, it's a good compacting placement.
    let mean_gap = (mean_residual - r) / cap;
    score -= 15.0 * mean_gap * (1.0 - t);

    // Penalize bins whose post residual is awkwardly small-but-nonzero (dead space)
    // that no plausible item (>=1) can use well; smooth via quadratic in normalized residual.
    score += 8.0 * rn * (1.0 - rn) * (1.0 - rn);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * t);
    }

    // Lookahead: if next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= r {
        let snug = 1.0 - ((r - next_item_size as f64) / cap).abs();
        score -= 10.0 * snug * snug;
    }

    // Mild penalty for proliferating bins relative to stream progress.
    score += 0.5 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 classes capture
    // "how nicely" the leftover space aligns with typical item granularities.
    let post_class = (post_residual % 10) as f64;
    score += post_class * 0.35;

    // Harmonic bonus: post_residual divisible by common item sizes (10,20,25,50)
    // leaves space reusable by likely future items.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        else if post_residual % 25 == 0 { score -= 4.5; }
        else if post_residual % 5 == 0 { score -= 2.0; }
        else { score += 3.0; } // awkward leftover
    } else {
        // Perfect fit is ideal.
        score -= 15.0;
    }

    // Integer-division threshold on post_residual: classify leftover into
    // harmonic bands of capacity quarters.
    let quarter = bin_capacity / 4;
    if post_residual < quarter / 2 {
        // Small dead space: penalize moderately unless it's zero.
        score += 2.0;
    } else if post_residual >= quarter && post_residual <= bin_capacity / 2 {
        // Sweet spot: reusable mid-size space.
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward (chained harmonic packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportional to how tightly the next item nests.
            score -= (10.0 - (slack / 10.0).min(10.0)) * 0.6;
            // Harmonic check: residual after chaining in a good class.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 2.5;
            }
        } else {
            // Next item won't fit here: mild penalty if this bin becomes stranded.
            score += 1.5;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin has huge residual, so its raw
    // score is already high; add extra penalty unless open bins are nearly full
    // (mean residual low), in which case relax the penalty.
    if bin_residual == bin_capacity {
        let pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 25.0 - 20.0 * pressure;
        // Late in the stream, prefer closing out open bins rather than spreading.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
    }

    // Mild preference for fuller bins overall (tight packing).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Many open bins with high mean residual: encourage consolidation.
    if open_bins_count > 3 && mean_residual > bin_capacity as f64 * 0.4 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps below the minimum item size (1..100 interface, min item = 1) that cannot
    // hold the lookahead item are dead space; penalize quadratically.
    let progress = step_index as f64 / (total_items.max(2) as f64);
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 2.5 * dead * (1.0 + progress);
    }

    // Reward near-perfect fits strongly (post_residual small relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 4.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins late in stream.
    score += 0.35 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: penalize unless item is large relative to capacity or
    // current bin fits are poor (post_residual large).
    if bin_residual == bin_capacity {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 12.0 - 0.05 * item_size as f64 - 0.15 * spread;
        if post_residual as f64 > mean_residual + 10.0 {
            score -= 4.0;
        }
    }

    // Mild preference for bins tighter than the mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
