pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers are bad
    }

    // Lookahead: if the next item fits exactly in the post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 * (post_residual as f64 / (next_item_size as f64 + 1.0)).min(1.0);
        } else {
            // wasted space relative to lookahead item
            score += 8.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: only fitting bin, avoid opening new bin unless residual is huge.
    if fitting_bins_count == 1 {
        score -= 25.0;
        if bin_residual as f64 > mean_residual * 1.5 {
            score += 10.0; // but this bin is unusually full already; mild penalty
        }
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is only
    // chosen when open bins would waste too much space.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheaper (future items can fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If current item is large, a fresh bin is attractive.
        score -= (item_size as f64 / 100.0) * 15.0;
    } else {
        // Favor filling bins that are already below average residual (denser bins).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score += 2.0 * (open_bins_count as f64).ln();
        if bin_residual != bin_capacity {
            score -= 5.0;
        }
    }

    // Mild preference for bins whose residual is close to the item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress) - 1.5 * norm_pr * norm_pr * (1.0 - progress);

    let mut score = pr + 10.0 * poly;

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Penalize if this placement wastes space needed by the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (nxt - pr).max(0.0) / cap;
        score += 12.0 * waste * (1.0 + progress);
        // Reward bins that can also fit the next item exactly
        let fits_next = (pr >= nxt) as i32 as f64;
        score -= 6.0 * fits_next * (1.0 - (pr - nxt) / cap).max(0.0);
    }

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Slight penalty when many bins are open with large mean residual (fragmentation)
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap) * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline, penalized mildly to prefer existing bins
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify by capacity fractions (integer division thresholds)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (post_residual / (bin_capacity / 4)) as f64; // 0..4 harmonic class
    let eighth = (post_residual / (bin_capacity / 8)) as f64;

    // Reward near-perfect fits: post_residual in lowest harmonic class
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= bin_capacity / 8 {
        score -= 20.0 - 1.5 * pr; // tiny dead space is fine
    } else if post_residual <= bin_capacity / 4 {
        score -= 8.0 - 0.5 * pr;
    } else {
        // Larger leftovers: penalize dead space that likely cannot fit future items
        score += 0.35 * (pr - cap * 0.25);
    }

    // Modulo arithmetic on post_residual: penalize awkward residues
    let mod10 = post_residual % 10;
    if mod10 > 0 && mod10 < 3 {
        score += 3.0; // awkward remainder class
    } else if mod10 == 0 {
        score -= 2.0; // nicely divisible residual
    }

    // Lookahead coupling: does post_residual fit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact or near-exact chain fit is very desirable
            let chain_gap = post_residual - next_item_size;
            if chain_gap <= bin_capacity / 16 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            // leftover too small for the next item: dead space penalty scaled by next item size
            score += 0.25 * (next_item_size as f64 - pr).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin late in the stream
    // when mean residual across open bins is low (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - pr).max(0.0);
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        } else if fragmentation < 5.0 && progress > 0.5 && next_item_size > item_size {
            score -= 6.0; // open fresh bin when open bins are nearly full
        } else {
            score += 10.0 + 0.1 * open_bins_count as f64; // discourage new bins otherwise
        }
    }

    // Mild pressure to consolidate: prefer bins with below-average residual (fuller bins)
    score += 0.15 * (mean_residual - pr);

    // Eighth-class refinement: even harmonic classes of leftover space get small bonuses
    if eighth % 2.0 == 0.0 && post_residual > 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual that cannot fit even the smallest plausible item (1..10)
    // is pure waste; the smaller the gap, the worse the waste density.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Dead space is worse if the next item cannot use it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Leaving room for the known next item is valuable.
        score -= 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it unattractive unless the item is huge
    // relative to residual or all fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if item is large, opening fresh may be fine.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 45.0;
        }
        // Late in the stream, opening new bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Prefer bins tighter than average (good fit relative to fleet state).
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (early vs late regime)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward exact/near-exact match of post_residual to next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect chain: next item fits exactly into the leftover space
        if post_residual as f64 == nxt {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward closeness of fit
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item does NOT fit the leftover: penalize dead space proportionally
            score += 10.0 + 0.5 * (nxt - post_residual as f64);
        }
    } else {
        // Last item: pure tightness reward
        score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // --- Tight fit reward: filling most of the bin is good ---
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill * fill;

    // --- Penalize creating tiny unusable residuals (dead space) ---
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // --- Relative to mean residual: prefer bins tighter than average ---
    score += 0.3 * (post_residual as f64 - mean_residual);

    // --- Last-chance bin: strongly favor using the only fitting bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling: keep it attractive early / when open bins fit poorly ---
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin has full residual; baseline penalty so it's chosen only when
        // no open bin offers a good 2-step fit. Relax as stream progresses.
        score += 20.0 - 15.0 * progress;
        // If many bins already open and none fit well, opening new is fine
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Lookahead: a fresh bin can host the next item perfectly too
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // --- Mild pressure to close out bins as stream ends ---
    score -= 5.0 * progress * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: heavily favor bins whose post_residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead coupling: reward leaving just enough room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain placement
        } else if post_residual >= next_item_size {
            score -= 6.0; // next item still fits
        } else {
            // post_residual is dead space relative to lookahead; penalize proportionally
            let waste = post_residual as f64 / (bin_capacity as f64);
            score += 10.0 * waste;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate handling: opening a bin is discouraged when the stream is
    // early or few bins are open, encouraged when many open bins have large mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = (open_bins_count as f64).ln().max(0.5);
        score += 20.0 + 15.0 * (1.0 - progress) - 8.0 * (mean_residual / bin_capacity as f64) - 2.0 * openness;
    }

    // Penalize bins with residual far from mean (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late-stream consolidation: prefer filling existing bins more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let mut score = x;

    // non-linear polynomial coupling of post residual with stream progress
    let shape = x * x * (1.0 - 2.0 * progress) + x * (0.5 + progress);
    score += shape * 6.0;

    // reward tight fits more strongly as stream progresses
    let tightness = 1.0 - x;
    score -= tightness * tightness * (1.0 + progress) * 4.0;

    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += (gap / cap) * 2.0;
    }

    // penalize spreading across many open bins late in the stream
    score += (open_bins_count as f64 / (1.0 + progress)) * 0.05;

    // new-bin candidate: mild penalty so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 1.5 + mean_residual * 0.01;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by integer division.
    // Classes: 0 (perfect fill), tiny (1..=9), small (10..=30), medium (31..=60), large (>60).
    let post = post_residual;
    let class = match post {
        0 => 0u8,
        1..=9 => 1,
        10..=30 => 2,
        31..=60 => 3,
        _ => 4,
    };

    // Reward perfect fills strongly.
    if post == 0 {
        score -= 60.0;
    }

    // Penalize tiny dead space (unusable fragments) proportionally to its awkwardness.
    if class == 1 {
        score += (10 - post) as f64 * 1.5;
    }

    // Medium residuals are valuable: reward keeping them, but only if the lookahead item
    // can actually use them (harmonic pairing of post_residual with next_item_size).
    if next_item_size > 0 {
        let fits_next = next_item_size <= post;
        if fits_next {
            // Reward when post_residual is a "harmonic" multiple/remainder pairing
            // with the next item: leftover after next item is small (good cascade).
            let second_left = post - next_item_size;
            if second_left == 0 {
                score -= 45.0;
            } else if second_left <= 10 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Lookahead cannot use this residual: penalize wasting the space.
            score += 6.0 + (next_item_size - post) as f64 * 0.25;
        }
    }

    // Large residuals: prefer filling big bins early (best-fit flavor already via post_residual,
    // but nudge toward consuming large residual space to avoid bin sprawl).
    if class == 4 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, mildly prefer tighter fits (already via post_residual).
        score += (fitting_bins_count as f64 - 1.0) * 1.0;
    }

    // New-bin candidate logic: an empty bin should only win when no open bin offers
    // a decent fit. Give the empty bin a mild penalty so only good open fits beat it.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; relax late in the stream when sprawl is cheap,
        // tighten early when consolidation matters.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 18.0 + 25.0 * (1.0 - progress);
        // If the next item is large and this fresh bin could host a cascade, ease opening.
        if next_item_size >= 50 {
            score -= 6.0;
        }
        // Many open bins: discourage adding more.
        score += open_bins_count as f64 * 0.8;
    }

    // Mean-residual coupling: if this bin's residual is far above mean, it is underused;
    // nudge score to prefer bins below/at the mean residual.
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score += (residual_f - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - residual_f) * 0.05;
    }

    // Modulo-flavored tie-breaking: residual divisible by common item sizes (10, 20, 25, 50)
    // is more reusable; reward divisibility of post_residual.
    if post % 10 == 0 { score -= 3.0; }
    if post % 25 == 0 { score -= 2.0; }
    if post % 50 == 0 { score -= 2.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual as i32) as f64 * 8.0;
    }

    // Reward tight fits: post_residual near zero but usable (perfect fit best).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residual sizes that can still host typical small items (>=10).
    if post_residual >= 10 {
        score -= 15.0;
        // Extra reward if the lookahead item can exactly fit the leftover.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
            if post_residual == next_item_size {
                score -= 10.0;
            }
        }
    }

    // Penalize bins that are much emptier than the fleet average (poor consolidation).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.35;

    // Open-bin pressure: discourage opening new bins when many bins exist,
    // scaled by stream progress (early stream tolerates more bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (30.0 + open_bins_count as f64 * 2.5 * (0.4 + 0.6 * progress));

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mild preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

