    }

    // New-bin candidate: penalize opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // pairing future big item with fresh bin can be good
            score -= 20.0;
        }
    }

    // Contextual: relative to mean residual, prefer bins tighter than average
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
