    // Penalize dead space: small post-residuals that can't fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless nothing fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 20.0;
        // If the item fills a large chunk of a fresh bin, opening is reasonable.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 40.0 * fill * fill;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If many bins are open with high mean residual, prefer filling existing ones.
        score += (open_bins_count as f64) * 0.5 + mean_residual * 0.2;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it uses leftover space.
            let next_fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 15.0 * next_fill;
        } else {
            // Next item won't fit here: slight penalty for leaving a tempting-but-useless gap.
            score += 5.0;
        }
    }

    // Prefer bins with below-average residual (more "wasted" bins get used first).
    let bin_residual_f = bin_residual as f64;
    if bin_residual_f < mean_residual {
        score -= 8.0 * (mean_residual - bin_residual_f) / bin_capacity as f64;
    } else {
        score += 4.0 * (bin_residual_f - mean_residual) / bin_capacity as f64;
    }

    // Dynamic time horizon: late in the stream, be conservative — avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.85 && bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    // Prefer fuller bins overall (best-fit flavor with saturation).
    let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * used * used;

    // Small tie-breaking nudge toward bins with exactly-fitting potential.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with a non-linear penalty on wasted space.
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth coupling: waste penalty grows as stream progresses (less time to fill leftovers).
    let urgency = 1.0 + 2.0 * progress * progress;
    score += urgency * norm_pr * norm_pr * cap * 0.5;

    // Reward near-perfect fits smoothly (post_residual close to 0).
    score -= 30.0 * (-pr / 15.0).exp();

    // Penalize large residuals relative to mean residual across bins (dead-space creation).
    score += 0.5 * (pr - mean_residual).abs();

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving a residual that can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap).min(1.0);
        } else {
            // Next item won't fit here; mild penalty scaled by how much is wasted.
            score += 6.0 * norm_pr;
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless few bins fit the item
    // or the item is large enough that a fresh bin is genuinely efficient.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        let big_item = item_size as f64 / cap;
        score += 20.0 * (1.0 - scarcity) * (1.0 - big_item);
        score -= 15.0 * scarcity * big_item * (1.0 - progress);
    }

    // Mild penalty for many open bins with a poor fit (fragmentation control).
    score += 0.3 * open_bins_count as f64 * norm_pr * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: how well does post_residual decompose into capacity fractions?
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward post-residuals that are "harmonic" (nice divisors of capacity):
    // residual leaving room for a future item of a common class is good.
    for class in [10u32, 20, 25, 50] {
        if post_residual >= class && post_residual % class == 0 {
            score -= 4.0 * (class as f64 / 10.0);
        }
    }
    if post_residual == 0 {
        score -= 12.0; // perfect fill
    }

    // Penalize dead space: residual smaller than the minimum plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 8.0; // perfect two-item fill
            }
        } else {
            // next item won't fit here: penalize proportionally to wasted fraction
            score += 3.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Modulo threshold on post_residual: awkward zones (just above half) are bad.
    let half = bin_capacity / 2;
    if post_residual > half && post_residual <= half + 10 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bin unless it promises harmonic structure.
        score += 5.0;
        if item_size % 25 == 0 || item_size % 50 == 0 {
            score -= 4.0;
        }
        let post = (bin_capacity - item_size) as f64;
        if post >= 10.0 && (post as u32) % 10 == 0 {
            score -= 2.0;
        }
        // Late in stream, prefer filling existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild pressure toward bins below mean residual (consolidate waste).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Integer-division threshold: reward residuals in "reusable" decade bands.
    let decade = post_residual / 10;
    if decade >= 1 && decade <= 9 {
        score -= 0.5 * decade as f64;
    }

    // Tie-breaker: prefer tighter fit relative to item.
    score -= 0.02 * item_size as f64 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min size 1, but practically small gaps) are waste.
    // Penalize unusable small gaps heavily.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: how well the item fills the bin relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 5.0 + 10.0;
    } else {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item cannot fit post residual and this bin is the only fit, still ok;
    // otherwise slight penalty if we strand the next item.
    if next_item_size > post_residual as u32 && fitting_bins_count == 1 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins get used first).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Stream progression: early on, be more willing to open bins (spread items);
    // late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the leftover exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // leftover can still host next item: mild reward proportional to slack
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // leftover too small for next item: penalize dead space
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual to mean residual: avoid making bins much tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let waste = bin_capacity as f64 - item_size as f64;
        // Opening a new bin is attractive only if the item is large (little waste)
        score += 50.0 + waste;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Progression: early in stream, be more tolerant of opening bins; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 100.0 * (1.0 - progress);
    } else {
        score -= 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tight * tight;

    // Lookahead: if the next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mildly penalize leaving mid-range gaps
            let gap = post_residual as f64;
            if gap >= next_item_size as f64 * 0.5 && gap < next_item_size as f64 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * t;
    }

    // Prefer bins below mean residual (i.e., fill emptier bins less, keep tight bins).
    if open_bins_count > 0 {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 5.0 * dev;
    }

    // Penalize dumping items into nearly-full bins when many bins are open
    // (preserve flexibility), except when the fit is exact.
    if post_residual == 0 {
        score -= 20.0;
    }

    // New empty bin candidate: moderate default so it only wins when open fits are bad.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.85 - 5.0 * t;
        if fitting_bins_count <= 2 {
            score += 10.0; // discourage new bin when decent options exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer low post_residual, with smooth non-linear penalty on large waste
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Polynomial coupling of post_residual with stream progress:
    // late in stream, waste matters more; early, flexibility matters
    let coupling = post * (progress * progress) * 1.5 - post * progress * 0.5;
    score += coupling;

    // Reward tight fits smoothly (item nearly fills bin)
    let fill_ratio = item_size as f64 / cap;
    score -= fill_ratio * fill_ratio * 20.0;

    // Penalize leaving residual close to small item sizes (dead space), smooth via sin-free poly
    let dead = norm_post * (1.0 - norm_post);
    score += dead * dead * 30.0 * (1.0 - progress);

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    } else {
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits in post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_quality = 1.0 - ((post - next_item_size as f64) / cap);
        score -= 10.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 {
        score += 5.0 * progress;
    }

    // Mean residual deviation: prefer bins whose residual deviates from mean (consolidation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Slight penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * (open_bins_count as f64);
        // But late in stream with big item, new bin can be fine
        score -= 8.0 * progress * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" divisors
    // of capacity (multiples of 10/25/50) are reusable -> reward (subtract).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, ideal
    } else if pr % 50 == 0 {
        score -= 45.0;
    } else if pr % 25 == 0 {
        score -= 35.0;
    } else if pr % 10 == 0 {
        score -= 25.0;
    } else if pr % 5 == 0 {
        score -= 10.0;
    } else {
        score += 8.0; // awkward residual class
    }

    // Integer-division threshold: small dead space (< 10) is unusable for
    // typical items -> heavy penalty scaled by how dead it is.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 6.0;
    }

    // Harmonic coupling with the next item: if the next item fits the
    // post-residual exactly or harmonically (post_residual % next_item_size == 0),
    // reward strongly; if next item cannot fit at all, penalize mildly.
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt <= pr {
            if pr % nxt == 0 {
                score -= 30.0;
            } else if nxt >= pr / 2 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    // (large item leaving large awkward residual) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        let penalty = 40.0 + waste * 0.6 - progress * 15.0
            + (open_bins_count as f64) * 2.0;
        score += penalty.max(5.0);
    }

    // Mild pressure toward tighter bins when many bins are open.
    score += mean_residual * 0.05 - (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero post-residuals are the worst
    // outcome (unusable gaps). Penalize gaps in the "dead zone" (1..=15).
    if post_residual > 0 && post_residual <= 15 {
        score += 60.0 * (1.0 - post_residual as f64 / 16.0);
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    }

    // Reward residuals that can still fit the lookahead item (keep useful space).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // Post-residual can't fit next item: it's likely dead space.
            score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Open-bin pressure: fewer open bins is better; mildly prefer filling
    // existing bins over opening new ones as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 1.5 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (better fits).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 55.0 - 50.0 * desperation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size exactly
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits into post_residual (good chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual as f64 - next_item_size as f64).min(20.0) * 0.5;
    }
    // Next item does NOT fit: post_residual becomes dead space for the lookahead
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (small post residual relative to capacity)
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Penalize wasting a large residual on a small item when other bins exist
    let waste = post_residual as f64 - (bin_capacity as f64 - item_size as f64 * 0.5);
    if waste > 0.0 && fitting_bins_count > 1 {
        score += waste * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Compare against mean residual: bins below mean residual (tighter) preferred
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Late in the stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and many bins open
        score += 30.0 + progress * 40.0 + (open_bins_count as f64 * 2.0);
        // But allow a new bin if no open bin chains with the next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
    } else {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward placing larger items (fills bins more completely)
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Lookahead coupling: if the next item can reuse this bin's residual,
    // strongly reward; otherwise penalize dead space proportionally.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += post_residual as f64 * 0.35;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Slight preference for bins that are on average fuller (consolidation).
    score -= mean_residual * 0.1;

    // Mild pressure from number of open bins (encourage closing them out).
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of opening a new bin
        score += 60.0;
        // Large items justify a fresh bin more than small ones
        score -= item_size as f64 * 0.5;
        // Early in the stream, new bins are cheaper; late, prefer consolidation
        score += t * 30.0;
        // If no open bin fits at all, the new bin is mandatory
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize wasted space, weighted by stream progress (waste matters more later).
    let mut score = pr * (0.8 + 0.6 * progress);

    // Smooth non-linear coupling: dead-space penalty grows super-linearly for small residuals.
    score += 8.0 * norm_pr * norm_pr * (1.0 - norm_pr) * cap * (0.5 + progress);

    // Reward tight fits (post_residual near zero) via smooth negative dip.
    score -= 6.0 * (1.0 - norm_pr).powi(6) * (1.0 + progress);

    // Lookahead coupling: if next item fits the post-residual, reward this bin smoothly.
    if next_item_size > 0 {
        let fit_gap = (pr - next_item_size as f64).abs();
        let fit_norm = 1.0 - (fit_gap / cap).min(1.0);
        score -= 5.0 * fit_norm * fit_norm * (0.6 + 0.4 * progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins; smooth in open_bins_count.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * progress);

    // Alignment with mean residual: prefer bins near the mean (balanced packing).
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: neutral-ish baseline with slight smooth decay over stream.
    if bin_residual == bin_capacity {
        score = 55.0 * (1.0 - 0.3 * progress) + 5.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Residuals divisible by small harmonics (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -40.0 // perfect closure
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 20 == 0 {
        -10.0
    } else if pr % 10 == 0 {
        -7.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Integer-division dead-space threshold: leftovers below the smallest item
    // class are dead space; penalize proportionally to how far below 10 it is.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 3.0;
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward snug fit of next item: small gap means tight packing
            let gap = pr - next_item_size;
            score -= (pr as f64) * 0.5 - (gap as f64) * 0.3;
            if gap == 0 {
                score -= 15.0; // next item closes this bin perfectly
            }
        } else {
            // next item won't fit here: mild penalty scaled by overflow
            score += ((next_item_size - pr) as f64) * 0.2;
        }
    }

    // Last-chance bin: strongly prefer filling the final fitting bin over
    // opening a new one, unless the post-residual would be tiny dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if pr > 0 && pr < 10 {
            score += 20.0; // but not if it just creates dead space
        }
    }

    // New-bin candidate handling: fresh empty bins are a fallback.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin when current item nearly fills it or all fits are bad,
        // otherwise penalize opening bins when good fits exist.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            score -= 25.0; // large item: start fresh bin
        } else {
            score += 30.0 + open_bins_count as f64 * 2.0;
        }
        // Early in stream, be more willing to open bins (build a portfolio).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    // Tie-break toward bins tighter than the mean (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Prefer bins whose residual is in the same harmonic class as the item.
    if item_size % 10 == 0 && pr % 10 == 0 && pr > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot fit the smallest plausible item (or the lookahead item)
    // is wasted capacity.
    let dead_threshold = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual < dead_threshold {
        score += 25.0;
    } else if post_residual < 15 {
        score += 12.0;
    } else if post_residual < 25 {
        score += 5.0;
    } else {
        // Large post-residuals are still usable; mildly reward them.
        score -= (post_residual as f64) * 0.05;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        // Next item fits but leaves a new dead gap: mild penalty.
        score += 6.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // ones; opening new bins when many are open is penalized.
    let pressure = (open_bins_count as f64) * 0.8;
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: penalize proportionally to open-bin pressure,
        // but relax near the end of the stream when future consolidation matters less.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += pressure * (1.0 - 0.5 * progress) + 10.0;
    } else {
        // Reward using existing bins, more so when many bins are open.
        score -= pressure * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits the item, strongly
    // prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "nearly full" bin — using it up is good (removes a fragmented bin).
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.4;
    } else {
        score += (-diff) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step lookahead match: this bin's post
    // residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Partial lookahead match: reward closeness of the gap.
        let gap = (post_residual - next_item_size) as f64;
        score -= (30.0 / (1.0 + gap * 0.25)).min(30.0);
    } else if next_item_size > 0 {
        // Next item cannot use the residual: penalize proportional waste.
        score += 8.0;
    }

    // Reward small post residuals non-linearly (dead-space suppression).
    let pr = post_residual as f64;
    score -= (40.0 / (1.0 + pr * 0.15)).min(40.0);

    // Relative-to-mean coupling: bins tighter than the mean are preferred.
    score += 0.5 * (pr - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins can fit the item, unless the
    // fit is terrible (post_residual leaves a very small unusable sliver).
    if bin_residual == bin_capacity {
        let new_bin_penalty = if next_item_size > 0 && post_residual >= next_item_size {
            10.0
        } else {
            35.0
        };
        score += new_bin_penalty + 0.3 * open_bins_count as f64;
        // Early in the stream, opening bins is cheap; late, it is costly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear (quadratic/cubic) shaping of residual
    let mut score = pr - 0.35 * cap * norm_pr * norm_pr + 0.6 * cap * norm_pr.powi(3);

    // Stream-progress coupling: as stream advances, weight residual more strongly
    // (smooth polynomial interaction rather than piecewise thresholds)
    let progress_coupling = 1.0 + 1.2 * progress - 0.5 * progress * progress;
    score *= progress_coupling;

    // Interaction of post_residual with mean residual: penalize bins whose
    // resulting residual deviates from the fleet mean (keeps residuals homogeneous)
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Lookahead: reward leaving space that the next item can use (smooth gate)
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let tightness = 1.0 - (pr - next_item_size as f64).abs() / cap;
        score -= 8.0 * fits_next * tightness.max(0.0);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: neutral-ish baseline so it wins only when fits are bad
    if bin_residual == bin_capacity {
        score = cap * 0.5 + 10.0 * norm_pr + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how "reusable" is it?
    // Residuals in [0,10) are dead space; residuals in nice bands (multiples of 10,
    // and the 25/50/75 fraction classes) are reusable by common item sizes.
    let dead = if post_residual < 10 { 1.0 } else { 0.0 };
    score += 60.0 * dead;

    // Reward exact / class-aligned fits: post_residual divisible by 10 or 25
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 25 == 0 {
        score -= 8.0;
    }

    // Integer-division thresholds on post_residual: small leftovers are risky
    if post_residual > 0 && post_residual <= 20 {
        score += 15.0;
    } else if post_residual > 20 && post_residual <= 40 {
        score += 4.0;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic match: next item lands exactly or near-exactly
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 40.0;
            } else if gap < 10 {
                score -= 25.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; penalize less if post_residual is still large
            score += 6.0 + (post_residual as f64).min(50.0) * 0.1;
        }
    } else {
        // Last item: just minimize waste
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin only when all open
    // bins would leave terrible dead space, or stream is early and bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
        // Fresh bin has residual 100: treat as a moderately good but not perfect option
        score = 55.0 - 20.0 * progress - 2.0 * crowding.min(10.0);
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0; // fresh bin can absorb next item too
        }
    }

    // Mild pressure to consolidate into few bins
    score -= (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for ANY item are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 40.0; // perfect fit, ideal
    } else if post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Penalize gaps that the lookahead item cannot use either.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            // residual can host the next item: reward usable continuation
            score -= 4.0;
        }
    }

    // Reward tight fits relative to residual (waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Open-bin pressure: with many bins open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    // (large item, high mean residual elsewhere).
    if bin_residual == bin_capacity {
        let poor_fits = (bin_residual - item_size) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // Base penalty so new bins open only when justified.
        score += 30.0;
        // Reward opening when the item would leave a big awkward gap anyway
        // and open bins are already slack-heavy.
        score -= poor_fits * 0.25 + pressure * 20.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near match: next item still fits comfortably with little slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 1.5;
    }

    // Penalize post_residual that is too small for any plausible future item (dead space)
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Compare residual against mean residual across open bins:
    // prefer filling below-average-residual bins (close them out)
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is huge
    // or the item perfectly pairs with a fresh full capacity minus item.
    if bin_residual == bin_capacity {
        score += 90.0;
        if item_size >= 70 {
            score -= 60.0;
        }
        // Opening a new bin is attractive if next item is large and current bin
        // placement would leave awkward residuals everywhere else.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 30.0;
        }
        // Late in stream, avoid bin proliferation
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 20.0;
        }
    }

    // Mild pressure to keep open bin count low
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin filled by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * fill * fill;

    // Strongly penalize wasted post_residual that cannot hold the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual still useful for the next item: mild reward.
            score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to lookahead: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 1.5 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = if fitting_bins_count > 0 {
            (bin_residual - item_size) as f64
        } else {
            0.0
        };
        // Penalize opening a bin when existing bins could take the item,
        // scaled by how many alternatives exist and stream progress.
        let mut new_bin_score = post_residual as f64 - 60.0 * fill * fill;
        if fitting_bins_count > 0 {
            new_bin_score += 30.0 + 10.0 * (fitting_bins_count as f64).sqrt() + 20.0 * progress;
        }
        // Slight bonus early in the stream when mean residual is low (bins mostly full).
        if mean_residual < 20.0 && fitting_bins_count > 0 {
            new_bin_score -= 15.0;
        }
        // Encourage new bin if it would leave a large residual for future big items
        // and the lookahead item is large.
        if next_item_size > 60 && post_residual >= 40 {
            new_bin_score -= 10.0;
        }
        // Suppress new-bin when it would strand tiny residual.
        if post_residual < 10 && post_residual > 0 {
            new_bin_score += 25.0;
        }
        return new_bin_score.max(fit_quality * 0.0 + new_bin_score);
    }

    // Mild global pressure: when many bins are open, prefer consolidating into
    // bins with below-average residual (filling emptier bins).
    if bin_residual as f64 > mean_residual {
        score += 4.0;
    } else {
        score -= 2.0;
    }

    // Late in the stream, tighten packing: penalize any leftover more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling of post_residual with stream progress
    let base = pr * (1.0 + 0.8 * progress * progress);

    // Reward tight fits: quadratic bonus when post_residual is small
    let tight_bonus = -40.0 * ((cap - pr) / cap).powi(3);

    // Penalize post_residual that matches typical item sizes (wasted dead space)
    let dead_penalty = 0.5 * pr * pr / cap;

    // Lookahead: reward leaving space close to the next item's size
    let next = next_item_size as f64;
    let lookahead = if next > 0.0 {
        -15.0 * (1.0 - ((pr - next) / cap).abs())
    } else {
        0.0
    };

    // Last-chance fitting: strongly favor using this bin
    let last_chance = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // Mild penalty for opening new bins when many bins already open
    let crowd = if bin_residual == bin_capacity {
        5.0 * (open_bins_count as f64).sqrt()
    } else {
        0.0
    };

    base + tight_bonus + dead_penalty + lookahead + last_chance + crowd
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a cubic term
    let tightness = 1.0 - pr / cap;
    score -= 14.0 * tightness.powi(3);

    // Harmonic decade classes on post_residual:
    // residuals that are multiples of 10 are "clean" slots, tiny crumbs (1..=5) are dead space
    score += match post_residual % 10 {
        0 => -4.0,
        1..=5 => 3.0,
        6..=9 => 0.5,
        _ => 0.0,
    };

    // Lookahead: if the next item fits into the resulting residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
        // Exact wrap: residual equals next item size perfectly
        if next_item_size == post_residual {
            score -= 16.0;
        }
    }

    // Penalize large residuals that leave awkward half-slots relative to mean
    if pr > mean_residual + 20.0 {
        score += 2.0;
    }

    // New-bin candidate handling
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Default penalty: prefer existing bins when they fit reasonably
        score += 22.0;
        // No open bin can fit -> must open a new bin
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Opening a fresh bin is attractive if all existing fits are very loose
        if fitting_bins_count > 0 && pr < mean_residual * 0.5 {
            score -= 10.0;
        }
        // Late in the stream, consolidate more aggressively
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    } else {
        // Last-chance bin: if this is the only bin that can fit the item, use it
        if fitting_bins_count == 1 {
            score -= 9.0;
        }
    }

    // Mild pressure to keep the number of open bins low
    score += open_bins_count as f64 * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - 3.0 * post_residual as f64; // small gap -> large penalty
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is highly rewarded
    }

    // Reward tight fits generally (low post_residual relative to capacity).
    score -= 0.4 * (bin_capacity as f64 - post_residual as f64);

    // Lookahead: if the next item fits exactly into the post-residual, favor it.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 18.0;
    }
    // Penalize if post_residual is too small for the known next item (dead space for it).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // Mean residual context: prefer bins whose residual is near the mean (balanced packing).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Last-chance bin: if this is the only bin that fits, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the fit
    // into open bins would be terrible. Base cost for the fresh bin:
    if bin_residual == bin_capacity {
        score += 45.0 + 0.5 * open_bins_count as f64;
        // But if the item is large relative to typical residual, a fresh bin is attractive.
        if (mean_residual - item_size as f64) < 15.0 {
            score -= 55.0;
        }
    }

    // Mild stream progression: later in stream, be slightly more conservative about new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches
    // the next item size exactly (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 500.0;
        } else {
            // Penalize post_residuals that are too small for the next item
            // (dead space), reward post_residuals slightly above next size.
            let diff = post_residual as f64 - nxt;
            if diff < 0.0 {
                score += (-diff) * 2.0; // dead space penalty
            } else {
                score -= diff * 0.5;    // usable leftover bonus
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    // (best-fit behavior relative to fleet state).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin bonus: if this is the only bin that fits, use it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 80.0;
    }

    // Penalize new-bin opening: empty bin candidate gets a large penalty
    // unless the item fits very poorly in existing bins (handled above by
    // last-chance bonus). Scale penalty with stream progress.
    if bin_residual == bin_capacity {
        score += 150.0 * (1.0 + step_index as f64 / total_items.max(1) as f64);
    } else {
        // Slight bonus for filling existing bins as the stream matures.
        score -= 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild penalty for large leftover relative to capacity (dead space).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Prefer consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.5 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let wasted = (next_item_size - post_residual) as f64;
        score += 0.8 * wasted;
    }
    // Reward bins whose residual can exactly accommodate the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly, scaled by stream progress and bin count.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 18.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // If mean residual across open bins is large, opening a new bin is worse.
        score += 0.15 * mean_residual;
    }

    // Slight preference for fuller bins relative to global mean residual.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Small time-horizon modulation: early in stream, be more conservative about
    // leaving tiny residuals; late in stream, exploit tight fits harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    // Early on, prefer tight fills (low post_residual); later, dead space matters less,
    // so the polynomial weight on prn grows smoothly with progress.
    let mut score = pr * (1.0 + 1.5 * progress) - 12.0 * prn * prn * (1.0 - progress);

    // Reward compact fits: squared fill ratio bonus (item_size relative to residual).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fill * fill;

    // Penalty if post_residual is a small unusable sliver (non-linear dead-space term).
    let sliver = (8.0 - pr).max(0.0) / 8.0;
    score += 9.0 * sliver * sliver * sliver;

    // Lookahead coupling: bonus if next item fits the post residual (smooth, quadratic).
    if next_item_size > 0 {
        let fits_next = if (pr >= next_item_size as f64) { 1.0 } else { 0.0 };
        let tight = 1.0 - ((pr - next_item_size as f64).abs() / cap).min(1.0);
        score -= 5.0 * fits_next * tight * tight;
    } else {
        // Last item: strongly reward using remaining space.
        score -= 4.0 * (1.0 - prn);
    }

    // Last-chance bin: reward using it before opening a new one (smooth in count).
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Mild penalty for proliferation of open bins with large mean residual (fragmentation).
    score += 0.05 * (open_bins_count as f64).ln() * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill classes and small-dead-space classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0; // perfect fill
    } else if pr <= 5 {
        score -= 120.0; // near-perfect fill
    } else if pr <= 15 {
        score -= 40.0;
    } else {
        // modulo classes: residuals divisible by common item sizes are reusable
        if pr % 10 == 0 { score -= 60.0; }
        else if pr % 5 == 0 { score -= 30.0; }
        else if pr % 25 == 0 { score -= 45.0; }
        else { score += 10.0; }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 2.0;
        } else {
            // next item cannot use the residual: penalize wasted space scaled by leftover
            score += (next_item_size - pr).min(20) as f64 * 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize creating dead space relative to mean residual of open bins.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.8;

    // Early in stream: prefer keeping bins tight; late: consolidate to close bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: neutral-ish baseline; only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        score = 60.0 + 0.5 * mean_residual - 10.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never host the smallest
    // plausible item are pure waste; penalize them hard.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 50.0 + (dead_threshold - post_residual) as f64 * 3.0;
    } else if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        // Gap too small for the lookahead item: partially dead until later.
        score += 12.0 + 0.3 * (next_item_size - post_residual) as f64;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 20.0 * tightness * tightness;
    }

    // Lookahead synergy: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after == 0 {
            score -= 45.0;
        } else if after < dead_threshold {
            score += 8.0; // would create new dead space
        } else {
            score -= 15.0 * (1.0 - after as f64 / bin_capacity as f64);
        }
    }

    // Last-chance pressure: if this is the only bin that fits, using it avoids
    // opening a new bin; reward it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins over opening
    // new ones, but only when the fit is reasonable.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // Opening a new bin is acceptable late in the stream when residuals are
        // fragmented (mean residual high relative to item size).
        if mean_residual > 1.5 * item_size as f64 {
            score -= 15.0;
        }
    } else {
        score -= 1.0 * open_bins_count as f64;
    }

    // Mild stream-progression term: early on, be conservative about wasting
    // large residuals; later, prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), slight non-linear penalty.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64) * 0.3;

    // 2-step lookahead: strongly reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item consumes leftover space
            let waste_after_next = post_residual - next_item_size;
            score -= 40.0 * (1.0 - waste_after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize small unusable leftovers
            if post_residual < 10 {
                score += 15.0; // dead space likely
            }
            // mild bonus if residual is large enough to be generally useful
            score -= (post_residual as f64) * 0.1;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let good_fit_exists = fitting_bins_count > 0 && (post_residual as f64) <= mean_residual;
        if good_fit_exists {
            score += 50.0; // keep using existing bins when fit is decent
        } else {
            score -= 10.0 + 10.0 * (1.0 - progress); // early stream: opening bins is fine
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: squared dead-space penalty.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Reward bins whose post-residual can host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (next_item_size as f64) * 0.15;
        } else if post_residual > 0 {
            // Penalize stranding small dead space that the next item cannot use.
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins: prefer consolidating into existing bins (avoid bin proliferation).
    if bin_residual < bin_capacity {
        // This is an existing (non-empty) bin candidate.
        score -= 4.0 + 0.05 * open_bins_count as f64;
        // Reward filling bins whose residual is close to the mean (harmonize state).
        let diff = (bin_residual as f64 - mean_residual).abs();
        score -= 6.0 / (1.0 + diff * 0.05);
    } else {
        // Brand-new bin candidate: penalize unless current item is large relative
        // to typical residual space or open bins are few.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 10.0 + 0.25 * open_bins_count as f64;
        // If item is large, a fresh bin is reasonable; if small, prefer existing bins.
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 14.0;
        // Later in the stream, be more conservative about opening bins.
        score += new_bin_penalty - large_item_bonus + 6.0 * progress;
    }

    // Prefer bins where the item consumes a large fraction of residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 5.0;

    // Mild penalty for leaving exactly awkward residuals (e.g., 1..=5 dead space).
    if post_residual > 0 && post_residual <= 5 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post-residual (tight fit), non-linearly
    let mut score = 10.0 * norm_pr + 6.0 * norm_pr * norm_pr;

    // Smooth stream-progress coupling: early on, tolerate slack; late, demand tightness
    let tightness = 0.5 + 1.5 * progress;
    score *= tightness;

    // Interaction: post-residual vs mean residual — penalize bins far below/above mean slack
    let mean_norm = mean_residual / cap;
    score += 3.0 * (norm_pr - mean_norm) * (norm_pr - mean_norm);

    // Lookahead: reward residual that can still fit the next item smoothly
    if next_item_size > 0 {
        let gap = norm_pr - norm_next;
        if gap >= 0.0 {
            score -= 2.5 * gap * (1.0 - progress);
        } else {
            score += 2.0 * (-gap) * (1.0 - gap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 4.0 + 3.0 * norm_item;
    } else {
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0) * norm_pr;
    }

    // New-bin candidate: mild penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * (1.0 - progress) + 3.0 * norm_item;
    }

    // Fill-ratio reward, non-linear in item size
    score -= 4.0 * norm_item * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "usable" classes (>= 10, multiples of 10) are less penalized.
    let post_i = post_residual;
    let class = post_i % 10;
    if post_i == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_i < 10 {
        score += 45.0; // dead space below minimum item size
    } else {
        // reward post-residuals that are "harmonic" with capacity fractions
        if class == 0 { score -= 12.0; }
        else if class <= 3 { score += 6.0; }
        // fraction of capacity remaining
        let frac = post / cap;
        if frac > 0.5 { score -= 4.0; }
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_i {
            score -= 50.0;
        } else if next_item_size <= post_i {
            let next_post = post_i - next_item_size;
            if next_post < 10 { score += 8.0; } else { score -= 10.0; }
        } else {
            // next item cannot use this bin's leftover: slight penalty
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to capacity or existing bins are very tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = (item_size as f64 / cap) > 0.6;
        let tight_bins = mean_residual < (item_size as f64 * 1.2);
        score += 70.0;
        if large_item { score -= 55.0; }
        if tight_bins { score -= 20.0; }
        if progress > 0.8 { score += 10.0; } // late stream: consolidate
        if open_bins_count == 0 { score -= 100.0; }
    }

    // Mild consolidation pressure: prefer bins tighter than the mean.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Integer-division threshold on item size: big items prefer fullest bins.
    if item_size / 20 >= 3 {
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A post_residual is "dead" if it's too small to plausibly hold a future item.
    let min_plausible_item = 1.0f64;
    let dead_zone_threshold = 15.0f64;
    if (post_residual as f64) > min_plausible_item && (post_residual as f64) <= dead_zone_threshold {
        // Non-linear penalty: worst at the smallest usable-but-wasted gaps.
        let r = post_residual as f64;
        score += 60.0 * (1.0 - r / dead_zone_threshold).powi(3) + 10.0;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits (post_residual small relative to capacity) smoothly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0; // next item can still go here
    } else if next_item_size > post_residual && post_residual > 0 {
        // post_residual too small for the next item -> mild dead-space penalty
        score += 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., filling fuller bins first), pushing emptier bins to stay flexible.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev.max(0.0) - 0.05 * (-dev).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fits are terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 55.0 + 1.5 * open_bins_count as f64;
        // More acceptable early in the stream or when many bins are already open.
        score -= 25.0 * progress;
        // If next item is large, a fresh bin is fine.
        if next_item_size > 60 {
            score -= 10.0;
        }
        // If the only fitting bin leaves a dead gap, allow new bin to compete.
        if post_residual > 0 && (post_residual as f64) <= dead_zone_threshold {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize dead space nonlinearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let tightness = 1.0 - (pr / cap);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            // Next item fits perfectly after this placement -> big reward.
            let perfect = (1.0 - (diff / cap)).max(0.0);
            score -= 30.0 * perfect * perfect;
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            score += 0.35 * (-diff);
        }
        // Coupled lookahead: reward when post_residual matches next item relative to mean residual.
        let mean = if mean_residual > 0.0 { mean_residual } else { cap };
        let rel = (pr - nxt) / mean;
        score -= 8.0 * (-rel.abs()).exp();
    } else {
        // Last item: just prefer minimal residual.
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins already below mean residual (consolidate waste in few bins).
    score += 0.15 * (pr - mean_residual);

    // Early in stream: be more willing to open new bins for flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, allow late when fits are poor.
        score += 20.0 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) > pr {
            score -= 10.0; // new bin guarantees room for lookahead item
        }
    }

    // Slight preference for bins with more residual used among many open bins.
    score -= 0.5 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with mild non-linearity.
    let pr = post_residual as f64;
    score = pr * (1.0 + 0.004 * pr);

    // Lookahead: reward bins whose leftover can host the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 + 0.10 * next_item_size as f64 - 0.03 * slack;
    } else if next_item_size > 0 {
        // Penalize leftovers that are almost-but-not-quite usable (dead space).
        let gap = (next_item_size as f64 - pr).min(30.0);
        score += 0.15 * gap;
    }

    // Perfect-fill bonus: exact fit is always excellent.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    } else if post_residual < 10 {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 8.0 * (1.0 - progress);
    }

    // Crowding pressure: many open bins with large mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    if bin_residual != bin_capacity {
        let crowding = (open_bins_count as f64).ln() * mean_residual / bin_capacity as f64;
        score -= 3.0 * crowding;
    } else {
        // New-bin candidate: penalize opening a bin, more so early and when
        // decent alternatives exist; relax penalty late in the stream.
        let alt_pressure = if fitting_bins_count > 0 { 1.0 } else { 0.2 };
        score += (14.0 + 10.0 * (1.0 - progress)) * alt_pressure;
        // Opening a bin is fine if current item is huge relative to capacity
        // (it will consume most of the new bin anyway).
        score -= 0.08 * item_size as f64;
    }

    // Slight preference for bins already below mean residual (balancing).
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: post residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.5 * prn * prn);

    // Stream-progress coupling: later in stream, waste penalized more strongly
    score += prn * prn * (100.0 + 200.0 * progress * progress);

    // Reward tight fits (small post residual) with non-linear bonus
    score -= (1.0 - prn) * (1.0 - prn) * 40.0;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        let nxt = next_item_size as f64;
        score -= 30.0 + 40.0 * (nxt / cap) * (1.0 - progress);
    }

    // Penalize opening a brand-new bin when good fits exist, smoothly by progress
    if bin_residual == bin_capacity {
        score += 60.0 + 120.0 * (1.0 - progress) * (1.0 - progress);
        // But if existing bins are very fragmented (high mean residual spread), soften
        score -= (mean_residual / cap).min(1.0) * 50.0 * progress;
    }

    // Mean residual interaction: prefer bins whose residual is below mean (tighter bins)
    let diff = (bin_residual as f64 - mean_residual) / cap;
    score += diff * 25.0 * (0.5 + 0.5 * progress);

    // Many open bins: mildly favor consolidation into existing bins
    score += (open_bins_count as f64).ln().max(0.0) * prn * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // integer division into capacity-fraction buckets.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class = post_residual / eighth; // 0..=8 harmonic class

    // Reward tight fits: small post_residual classes get strong bonuses.
    match post_class {
        0 => score -= 40.0,                 // near-perfect fit
        1 => score -= 25.0,
        2 => score -= 12.0,
        3 => score -= 4.0,
        4 => score += 3.0,                  // half-full leftover: mediocre
        5 => score += 6.0,
        6 => score += 10.0,
        7 => score += 14.0,
        _ => {}
    }

    // Modulo arithmetic on post_residual: residues divisible by common
    // item sizes (10/20/25/50) are more reusable.
    if post_residual > 0 {
        let reusable = (post_residual % 10 == 0) as f64 * 6.0
            + (post_residual % 20 == 0) as f64 * 4.0
            + (post_residual % 25 == 0 || post_residual % 50 == 0) as f64 * 5.0;
        score -= reusable;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly
    // or comfortably, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 - (slack as f64).min(15.0);
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot class
            let over_class = (next_item_size - post_residual) / quarter;
            score += 2.0 + over_class as f64 * 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // are nearly full or the item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_frac = mean_residual / bin_capacity as f64;
        let mut new_bin_penalty = 30.0;
        // If mean residual is small (bins nearly full), new bin is fine.
        new_bin_penalty -= (1.0 - mean_frac) * 10.0;
        // Large items late in the stream: fresh bin slightly preferable.
        new_bin_penalty -= item_frac * 8.0 + progress * 4.0;
        // If nothing else fits, opening is inevitable.
        if fitting_bins_count == 0 {
            new_bin_penalty = -20.0;
        }
        score += new_bin_penalty.max(-25.0);
    }

    // Prefer filling bins that are already committed (more open bins =>
    // consolidate to avoid proliferation).
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Dead-space guard: leftover that no plausible item (>=1) can use well.
    if post_residual > 0 && post_residual < eighth {
        score += 8.0; // tiny slivers are wasted space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a meaningful future item are heavily penalized.
    let dead_threshold = 9.0; // below typical minimum item size (1..100 unknown, treat small gaps as dead)
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    }

    // Reward placements where the item dominates the residual (tight fit).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += open_bins_count as f64 * 0.8;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a scarce small gap; using it well is valuable.
    let res_gap = mean_residual - bin_residual as f64;
    score += res_gap * 0.5;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual cannot host the next item: mild penalty scaled by dead-ness.
        score += (post_residual as f64) * 0.3;
    }

    // New-bin candidate: prefer opening a fresh bin only when no open bin offers
    // a reasonable fit; otherwise penalize slightly so existing bins win ties.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.2;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is the right move
        }
    }

    // Late-stream consolidation: as the stream progresses, tighten up.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving awkward small residual
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += 8.0 * (1.0 - waste / 100.0);
            }
        }
    } else {
        // last item: prefer tightest fit
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins below-average residual (fuller bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin boost
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a perfect chain
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 45.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Dead-space penalty: small residuals unlikely to be usable later
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward if next item can use the post_residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64));
        } else {
            score += 3.0;
        }
    } else {
        // Last item: prefer filling existing bins completely.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64).sqrt() * 2.0;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * mean_residual * (1.0 - progress);

    // Prefer bins whose residual deviates from mean (keep some bins for large items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.02 * dev;

    // Mild preference for fuller bins as stream progresses.
    score -= 5.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth polynomial coupling: penalize small post-residuals quadratically (dead space),
    // reward tight fits, modulated by stream progress.
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 4.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    // Lookahead coupling: penalize if next item fits exactly in post residual (favor reserving)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_gap = pr - next_item_size as f64;
        score -= 3.0 * (1.0 - fit_gap / cap);
    } else if next_item_size > 0 {
        score += 2.0 * (next_item_size as f64 / cap);
    }
    // Last-chance bonus: strongly favor using a bin when few fitting bins remain
    if fitting_bins_count <= 1 {
        score -= 6.0;
    } else {
        score -= 1.5 / fitting_bins_count as f64;
    }
    // New-bin candidate: penalize opening a new bin, more so early in the stream
    if bin_residual == bin_capacity {
        score += 15.0 * (1.2 - progress) + 0.5 * open_bins_count as f64;
    }
    // Mean residual deviation: prefer bins whose residual differs from mean (diversity)
    let dev = (pr - mean_residual).abs() / cap;
    score += 2.0 * dev * (1.0 - progress);
    // Mild preference for filling larger residual bins as stream progresses
    score -= progress * 2.0 * (bin_residual as f64 / cap);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by integer division
    let class = post_residual / 10; // classes 0..10
    // Penalize small-but-unusable residuals (dead space) more than large usable ones
    score += match class {
        0 => 0.0,                      // perfect fit
        1 => 8.0,                      // 1-9: nearly dead
        2 => 4.0,                      // 10-19: fits tiny items only
        3 => 1.0,                      // 20-29
        4 => 0.0,
        5 => -1.0,                     // 50-59: half-full, reusable
        6 => 0.0,
        _ => -0.5,
    };

    // Lookahead: reward bins whose post_residual fits the next item well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // tightness of the follow-up fit
            let slack = post_residual - next_item_size;
            score -= 6.0 - (slack as f64 * 0.15).min(6.0);
        } else {
            // post residual can't host next item: mild penalty proportional to gap
            score += 1.5;
        }
        // harmonic coupling: next item class vs post_residual class
        let next_class = next_item_size / 10;
        if post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            score -= 5.0; // chain of tight fits
        }
        let _ = next_class;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin
        score += 20.0;
        // if many bins already fit the item, discourage opening a new one
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64).min(4.0);
        }
        // early in stream: opening bins is cheaper (build diversity)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // large items relative to capacity favor a fresh bin
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Prefer filling bins whose residual is close to mean (balance)
    score += ((post_residual as f64 - mean_residual) * 0.05).abs();

    // Slight preference for bins with larger residual when item is large
    score -= (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 / bin_capacity as f64) * 2.0;

    // Many open bins: encourage consolidation
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space relative to smallest plausible item (1..100 interface).
    let dead = post_residual as f64;
    if dead > 0.0 && next_item_size > 0 && (dead as u32) < next_item_size {
        score += 3.0 * (next_item_size as f64 - dead);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins
    // over opening new ones (new-bin candidate gets residual = capacity = 100).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        score += 15.0 + pressure;
    } else {
        score -= 0.15 * pressure;
    }

    // Prefer bins tighter than average (consolidation of small residuals).
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tightest fit
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step fill (post_residual == next_item_size) is heavily rewarded
        if lookahead_gap == 0.0 {
            score -= 60.0;
        } else {
            // Penalize proportionally to mismatch, scaled by lookahead size
            score += lookahead_gap * 0.35;
            // If next item cannot fit in the residual, mild penalty (dead space likely)
            if (post_residual as u64) < (next_item_size as u64) {
                score += 8.0;
            }
        }
    } else {
        // Last item: just minimize waste
        score -= 5.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving residual well below mean means we consumed scarce space well
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.15;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so when many bins are open or it's late
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        // But if the best existing fit would leave a big mismatch with lookahead,
        // opening fresh is less penalized (handled implicitly by others' penalties)
    }

    // Slight penalty for very small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large residuals relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post_residual is good, but zero post_residual is perfect.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0 * (1.0 - post_residual as f64 / 10.0);
    } else {
        // Usable leftover space is valuable if it can host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 45.0;
        // Early in the stream, opening bins is cheap (many items remain to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 35.0 * (1.0 - progress);
        // If many bins are open and mean residual is large, prefer reusing existing space.
        score += 0.4 * open_bins_count as f64;
        score += 0.3 * (mean_residual - post_residual as f64).max(0.0);
        // If no open bin fits well (item large relative to mean residual), new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
    }

    // Global pressure: when open bins are nearly full on average, reuse matters more.
    let fullness = 1.0 - mean_residual / bin_capacity as f64;
    score += 8.0 * fullness * (post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if next item is huge, keep large residuals intact.
    if next_item_size >= 60 && post_residual >= next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with smooth polynomial shaping
    let mut score = post;

    // Non-linear coupling: mid-range residuals become more penalized as stream progresses
    let bump = x * (1.0 - x); // peaks at 0.25 (x=0.5)
    score += 40.0 * bump * (0.5 + progress) * cap;

    // Reward tight fits increasingly over time
    score -= (1.0 - x) * (1.0 - x) * (20.0 + 60.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 50.0 * progress;
    }

    // Lookahead coupling: if next item fits into post residual, reward leaving useful space
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = x - nx;
        if gap >= 0.0 {
            score -= 15.0 * gap * (1.0 - progress);
        } else {
            score += 10.0 * (-gap) * progress;
        }
    }

    // Slight pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln() * 3.0 * x;

    // Mean residual context: prefer bins below mean residual (tighter bins)
    score += 0.1 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose residual falls into
    // "small residue" classes are near-full and should be preferred strongly.
    let post = post_residual;
    let class = post % 10;                       // fine-grained harmonic class
    let coarse = post / 10;                      // coarse decade of dead space

    // Reward tiny residues (excellent packing), quadratically.
    if post == 0 {
        score -= 60.0;                            // perfect fill
    } else if post <= 5 {
        score -= 40.0 - (post as f64) * 4.0;
    } else if class == 0 {
        score -= 12.0;                            // residue is a multiple of 10: reusable class
    } else if class <= 3 {
        score -= 6.0;
    } else if class >= 7 {
        score += 8.0;                             // awkward residue class
    }

    // Penalize large dead space quadratically, but modulate by coarse class.
    score += (post as f64) * (post as f64) * 0.02;
    if coarse >= 5 {
        score += 10.0;                            // more than half empty after placement
    }

    // Lookahead coupling: if the next item exactly fits the post-residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 35.0;
        } else if next_item_size <= post {
            let nclass = (post - next_item_size) % 10;
            if nclass == 0 { score -= 15.0; }
            else if nclass <= 3 { score -= 8.0; }
            else { score += 4.0; }
        } else {
            // next item cannot use this bin's residue: slight penalty if residue is large
            if post > bin_capacity / 2 { score += 6.0; }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    // (large item relative to mean residual) or stream is early.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / cap;
        let mean_tight = mean_residual / cap;
        // Opening a new bin is good for big items or when open bins are very full.
        let bonus = 30.0 * pressure + 20.0 * (1.0 - mean_tight);
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap * 0.55 - bonus + 15.0 * progress;
        // Harmonic gate: if item size is in a "nice" class (multiple of 5 or 10),
        // a fresh bin is slightly more attractive.
        if item_size % 10 == 0 { score -= 8.0; }
        else if item_size % 5 == 0 { score -= 4.0; }
    }

    // Slight preference for consolidating among few open bins.
    if open_bins_count > 8 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strict dead-space avoidance with open-bin pressure.
    let mut score = post_residual as f64;

    // Hard penalty for tiny unusable gaps (< 10 units are dead for min item size 10;
    // be extra strict for gaps below 20 since mid-size items dominate).
    if post_residual < 10 {
        score -= 500.0; // perfect fill: excellent
    } else if post_residual < 20 {
        score -= 40.0; // small gap still usable by tiny items
    } else if post_residual < 40 {
        score += 25.0; // awkward mid-gap: dead-space risk
    }

    // Reward tight relative fit (small waste ratio).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Last chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 20.0);
    if bin_residual != bin_capacity {
        score -= 8.0 * pressure;
    } else {
        // New-bin candidate: penalize mildly, but allow it when item is large
        // and no bin fits well (post_residual would be huge in existing bins).
        score += 45.0 + 10.0 * pressure;
        if item_size > 70 {
            score -= 30.0; // large items: a fresh bin is fine
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 120.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    }

    // Prefer bins with residual near mean (balanced packing), avoid extreme outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can exactly (or near-exactly) absorb the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect match: big bonus; decays quickly with slack.
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        // Extra nudge for exact fits.
        if slack == 0.0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in the leftover: penalize dead space,
        // especially small unusable slivers.
        let dead = post_residual as f64;
        score += 10.0 + dead * 0.15;
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual
    // (best-fit flavor), penalize bins that are already loose.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when all open bins are poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we prefer existing bins unless they are hopeless.
        score += 30.0;
        // If no open bin fits the item, opening fresh is attractive.
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count == 1 {
            // Compare: does the single fitting bin leave a useful remainder?
            if next_item_size > 0 && post_residual >= next_item_size {
                // keep using open bin (its score already lowered above)
                score += 10.0;
            } else {
                score -= 20.0;
            }
        }
        // Late in the stream, closing out cleanly matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.9 {
            score -= 5.0;
        }
    }

    // Slight preference for filling larger items into tighter bins overall.
    score += (item_size as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 6.0 * fit_ratio * fit_ratio;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 20 {
        score += 8.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 20.0;
        } else {
            score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && next_item_size <= item_size {
        // Next item won't fit here anyway; mild penalty for wasting large residual.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits poorly everywhere else (large item, few fitting bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // New bins are attractive for very large items or when no good fit exists.
        let mut new_bin_score = 15.0;
        new_bin_score -= 10.0 * item_frac;
        new_bin_score += 5.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0;
        }
        if next_item_size > 0 && next_item_size as f64 > 0.8 * bin_capacity as f64 {
            new_bin_score -= 6.0;
        }
        score = new_bin_score;
    }

    // Global state: many open bins with large mean residual -> prefer reusing
    // bins with residual above the mean (consolidation).
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
        // Few open bins: be frugal, favor reuse even more.
        if open_bins_count <= 3 {
            score -= 5.0;
        }
    }

    // Time horizon: early in the stream, be slightly more willing to spread
    // items (keep flexibility); late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + 0.5 * progress) - norm_pr * (1.0 - progress);
    score += 20.0 * poly;

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0) / cap;
        score += 15.0 * waste * waste * (1.0 + progress);
        // Reward when post residual still fits next item
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        score -= 10.0 * fits_next * norm_pr * (1.0 - progress);
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * (1.0 - norm_pr);
    }

    // Slight preference for bins tighter than average (smooth)
    let dev = (mean_residual - pr) / cap;
    score += 5.0 * dev * dev - 3.0 * dev;

    // Late stream: prefer filling existing bins over opening new ones
    score -= progress * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize mildly unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual near 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Harmonic class logic: classify post_residual by modulo classes.
    // Residuals divisible by 10 (typical item granularity) are "usable" classes.
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -60.0,           // highly reusable residual
        1 | 9 => 25.0,        // awkward dead space
        2 | 8 => 10.0,
        5 => -20.0,           // half-class residual, decent reuse
        _ => 5.0,
    };
    score += class_penalty;

    // Integer-division threshold: residual in [next_item_size, next_item_size + 10]
    // means this bin can host the next item too -> reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 90.0;
        } else {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize proportionally to wasted lookahead.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: residual == capacity. Only attractive when item is large
    // (would leave little residual anyway) or no open bin fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 >= 0.6 * bin_capacity as f64;
        if large_item {
            score -= 40.0;
        } else {
            score += 60.0 + 0.3 * (open_bins_count as f64);
        }
        // If mean residual across open bins is small, prefer new bin.
        if mean_residual < item_size as f64 {
            score -= 50.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins -> prefer existing bins.
    score += 0.05 * open_bins_count as f64;

    // Stream progression: late in stream, tighten up (favor tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // minimum item (1) are pure waste; residuals below the lookahead item size
    // are likely dead too.
    let dead_floor: u32 = 1;
    if post_residual < dead_floor.max(next_item_size.min(bin_residual)) {
        score += 12.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 4.0; // residual probably unusable for the next item
    }

    // Reward tight fits (small post_residual relative to capacity) super-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Perfect fit: overwhelming preference.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Exact room for the next item: chain-friendly placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // already-open bins; the new-bin candidate (residual == capacity) is
    // penalized proportionally to how many bins are already open.
    if bin_residual == bin_capacity {
        score += 3.0 + 1.5 * open_bins_count as f64;
        // Late in the stream, opening new bins is even less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * progress;
    } else {
        // Slight reward for filling fuller (more crowded) bins.
        if (bin_residual as f64) < mean_residual {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr == nxt {
            score -= 60.0; // exact lookahead match: place here
        } else {
            let diff = (pr - nxt).abs();
            score += diff * 0.6; // penalize mismatch with lookahead
            // soft reward if next item still fits after this placement
            if pr >= nxt && pr - nxt <= 10.0 {
                score -= 8.0;
            }
        }
        // If next item cannot fit in this bin after placement, mild penalty
        if pr < nxt {
            score += 5.0;
        }
    } else {
        // Last item: just minimize waste, prefer tightest fill
        score -= 20.0;
    }

    // Reward placements that keep post_residual below the mean residual
    // (tight bins get filled first, loose bins stay flexible).
    if (post_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += ((post_residual as f64) - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize leaving unusable dead space (small post_residual that can't
    // fit typical small items, i.e. 1..10 dead zone is fine, but mid-range
    // stranded residual is wasted).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score -= 3.0; // near-perfect fill
    }

    // Late in the stream, be more aggressive about filling existing bins
    // rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Slight penalty for opening a brand-new bin when other bins fit,
    // unless the item is huge and residual is full capacity (legit new bin).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual relative to capacity.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small to ever be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // wasted slot for the lookahead item
        }
        // Perfect pairing: this fill + next item exactly fills bin
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Time horizon: as the stream progresses, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Global pressure: many open bins -> favor filling existing ones (penalize new bins).
    let empty_bin = bin_residual == bin_capacity;
    if empty_bin {
        score += 4.0 + 0.35 * open_bins_count as f64;
        // Exception: if mean residual across open bins is tiny, opening fresh is fine.
        if mean_residual < 15.0 {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean (more packed bins).
        let dev = mean_residual - bin_residual as f64;
        score += 0.08 * dev;
    }

    // Mild penalty for very large items into already-large-residual bins (save big
    // residuals for big future items).
    if item_size < 30 && bin_residual > 70 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * t * t) - 12.0 * fill * fill * (1.0 + t);

    // Reward near-perfect fits smoothly
    score -= 20.0 * (fill * fill * fill * fill);

    // Penalize tiny dead space that wastes capacity, smoothly
    if pr > 0.0 {
        score += 8.0 * (1.0 - pr / cap) * (pr / cap).exp();
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Lookahead: favor bins whose residual still fits the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 4.0;
    } else if next_item_size > 0 {
        score += 2.0;
    }

    // New-bin candidate: mildly discourage early, encourage late
    if bin_residual == bin_capacity {
        score += 3.0 - 4.0 * t;
    }

    // Pressure term coupling open bins with mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap - fill).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the post_residual, the better (Best-Fit core).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Harmonic class of the leftover: classify post_residual by its remainder mod 10.
    // Leftovers in "high" harmonic classes (>= 10) remain reusable for typical items;
    // sub-10 leftovers are dead space and get penalized.
    let harm = post_residual % 10;
    if post_residual < 10 {
        score += 40.0 - harm as f64 * 2.0; // near-zero leftover is perfect, 1..9 is waste
    } else {
        // Reward leftovers that sit in useful integer-division bands (10..=80 usable)
        let band = post_residual / 10;
        score -= band as f64 * 0.8;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Perfect chain fit: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Harmonic match: next item leaves again a useful band
        if (post_residual - next_item_size) >= 10 {
            score -= 5.0;
        }
    } else if next_item_size > post_residual {
        // Leftover too small for the next item: mild penalty scaled by how far off
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        // But penalize if it creates a tiny dead leftover anyway
        if post_residual < 10 && post_residual > 0 {
            score += 20.0;
        }
    }

    // New-bin candidate handling: an empty bin is a neutral refuge.
    if bin_residual == bin_capacity {
        // Base score for a fresh bin: slightly worse than a decent tight fit,
        // but better than forcing a bad fit into a nearly-full bin.
        score = bin_capacity as f64 * 0.55;
        if next_item_size > 0 {
            // An empty bin can always host the next item: mild bonus
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            // No real alternative: opening a new bin is fine
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        return score;
    }

    // Prefer filling bins that are already far from the mean residual (consolidation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild pressure against proliferating bins mid-stream
    if open_bins_count > 4 {
        score += open_bins_count as f64 * 0.2;
    }

    // Progress-aware: early on be pickier about tight fits (long horizon to exploit leftovers)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_capacity as f64 - post_residual as f64) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold any plausible
    // future item (typical minimum size 10) are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 && post_residual < 20 {
        // Small-but-usable gaps are mildly risky.
        score += 6.0;
    }

    // Reward tight fits: item filling most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 25.0;
    } else if fill_ratio > 0.75 {
        score -= 12.0;
    }

    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            // Placing here leaves a gap the next item nearly fills but
            // would strand a dead space afterwards.
            score += 8.0;
        }
    }

    // Open-bin pressure: with few open bins, prefer consolidating into
    // existing bins; with many open bins, avoid spreading waste.
    let ob = open_bins_count as f64;
    score += 2.0 * ob.ln().max(0.0);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < 10 {
            score -= 10.0; // even a dead-space fit beats a new bin here
        }
    }

    // New-bin candidate: only attractive when the item is large and would
    // otherwise strand significant dead space in every existing bin.
    if bin_residual == bin_capacity {
        score -= 15.0;
        if item_size >= 70 {
            score -= 10.0;
        }
        if post_residual < 10 && post_residual > 0 {
            score += 30.0; // opening a bin that immediately strands space is bad
        }
    }

    // Mild drift: later in the stream, prefer tighter packing overall.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact chain fits (item + next item).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item chain fill
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetically placing next item, scaled by slack
            score += slack * 0.35;
            if post_residual - next_item_size < 10 {
                score -= 25.0; // near-perfect chain, small dead space
            }
        } else {
            // next item cannot follow: dead space penalty grows with post_residual smallness
            let wasted = post_residual as f64;
            if wasted < 10.0 {
                score += 45.0; // tiny unusable residual
            } else {
                score += (10.0 - wasted.min(10.0)) * 0.0 + (100.0 - wasted) * 0.0;
            }
        }
    } else {
        // last item: prefer minimal post residual strongly
        score -= 40.0;
    }

    // Relative-to-mean coupling: bins tighter than mean are valuable, reward using them.
    let res = post_residual as f64;
    let dev = mean_residual - res;
    if dev > 0.0 {
        score -= dev * 0.5; // this bin ends tighter than average -> good
    } else {
        score += (-dev) * 0.2;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Discourage opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 20.0; // new bin can't even chain next item well
        }
    }

    // Mild progression term: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - res) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tightness: reward small waste relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Penalize very large post-residuals that no typical item can use
    if post_residual > 80 {
        score += (post_residual - 80) as f64 * 1.5;
    }

    // Lookahead: bonus if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize wasting this bin's residual
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 20.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many fitting bins: mild penalty for picking a crowded-choice bin; prefer diversity
    if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64 - 3.0) * 2.0;
    }

    // Global state coupling: if mean residual is high, prefer filling existing bins
    if mean_residual > item_size as f64 {
        score -= 5.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (item barely fits) or few bins exist.
    if bin_residual == bin_capacity {
        let desperation = (open_bins_count == 0) as i32;
        let poor_fit = (bin_residual - item_size) < 10;
        if desperation == 1 {
            score -= 1000.0; // must open a bin
        } else if poor_fit {
            score -= 15.0; // opening a fresh bin beats a bad squeeze
        } else {
            score += 50.0 + (open_bins_count as f64).sqrt() * 3.0; // prefer existing bins
        }
    }

    // Time horizon: early in stream, be conservative (keep bins flexible);
    // late in stream, exploit tight fits aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);
    if progress > 0.8 {
        score -= post_residual as f64 * 0.4; // squeeze hard at the end
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    let mut score = post;

    // Non-linear waste penalty: small residuals are valuable dead space.
    let norm_post = post / cap;
    score += 40.0 * (1.0 - norm_post) * (1.0 - norm_post) * norm_post;

    // Smooth coupling with stream progress: tighten packing later in the stream.
    score -= 12.0 * progress * (post as f64 / cap).sin() * (post as f64 / cap);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize bins far below the mean residual (fragmentation pressure).
    score += 0.15 * (mean_residual - post).abs();

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let gap = post - nxt;
            score -= 8.0 * (-gap / 30.0) * (-gap / 30.0);
        } else {
            score += 6.0 * (1.0 - post / nxt.max(1.0));
        }
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: only attractive when current fit is very poor.
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover into coarse slots.
    // Classes: 0 (perfect), 1..=5 (tiny), 6..=15 (small), 16..=30 (medium), >30 (large).
    let class: f64 = if post_residual == 0 { 0.0 }
        else if post_residual <= 5 { 1.0 }
        else if post_residual <= 15 { 2.0 }
        else if post_residual <= 30 { 3.0 }
        else { 4.0 };
    score += class * 6.0;

    // Perfect fit: strong reward.
    if post_residual == 0 { score -= 40.0; }

    // Near-perfect: residual could pair with small future items (harmonic partners).
    if post_residual >= 1 && post_residual <= 10 { score -= 8.0; }

    // Dead space penalty: leftover that no plausible item (1..=100) pairs with well.
    if post_residual > 50 { score += 12.0; }

    // Reward tight fits: item fills most of the residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= (fill - 0.5) * 10.0;

    // Lookahead coupling: if next item exactly fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 35.0; }
        else if next_item_size <= post_residual {
            let nxt_fill = next_item_size as f64 / post_residual.max(1) as f64;
            if nxt_fill > 0.6 { score -= 10.0; }
        }
        // Next item cannot use this leftover at all -> mild penalty for large leftovers.
        if next_item_size > post_residual && post_residual > 25 { score += 5.0; }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 20.0; }

    // Many open bins with fat residuals: discourage hoarding space here.
    if open_bins_count > 3 && (bin_residual as f64) > mean_residual + 10.0 {
        score += 4.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (many fitting bins means we should reuse), or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_penalty = 25.0 + 30.0 * progress;
        if fitting_bins_count >= 2 { new_penalty += 20.0; }
        if item_size as f64 / cap > 0.8 { new_penalty -= 15.0; }
        score += new_penalty;
    }

    // Modulo-harmonic bonus: residuals divisible by common item granularities (5, 10)
    // are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 { score -= 4.0; }
    else if post_residual % 5 == 0 && post_residual > 0 { score -= 2.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A residual gap is "dead" if it cannot hold even the smallest plausible item.
    let min_useful = 12.0; // small gap threshold: gaps below this are near-dead
    if (post_residual as f64) < min_useful {
        // 0..12 residual: waste — penalize proportionally to how close to full
        score += (min_useful - post_residual as f64) * 18.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward
        score -= 120.0;
    }

    // Non-linear penalty on wasted fraction of the bin's useful space
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 60.0;

    // Reward tight fits relative to current residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 40.0;

    // Last-chance bin: if only this bin fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
        // Extra pressure late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 25.0;
    }

    // Open-bins pressure: many open bins -> prefer consolidating into existing
    // bins rather than spreading out; few open bins -> new bins are cheaper.
    let bin_pressure = open_bins_count as f64 / 8.0;
    score += bin_pressure * 10.0;

    // New-bin candidate handling: an empty bin is attractive when the fit into
    // existing bins is poor (large post_residual) or when next item is large.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 30.0;
        // But if the current item would leave a big gap in any open bin,
        // opening fresh is competitive: the empty-bin post_residual is
        // bin_capacity - item_size which is naturally large, so discount it
        // when next_item_size is big (it may fill the fresh bin well).
        if next_item_size > 0 {
            let next_fits_new = (bin_capacity - item_size) >= next_item_size;
            if next_fits_new {
                score -= 35.0;
            }
        }
        // Late-stream: fewer chances to consolidate, slightly discourage new bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    }

    // Lookahead: if next item would exactly fit the post_residual, reward this placement
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 70.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        // next item fits but leaves near-dead space: mild penalty
        score += 12.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is the "most full" bin — finishing it off is good.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary objective: minimize post_residual (tight fit), with a mild power shaping.
    score = score.powf(1.15);

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain bonus: proportional to how well the next item also fills the bin.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 12.0 + 0.6 * (bin_capacity as f64 - chain_waste);
        } else {
            // Penalize dead space that the next item cannot use.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.9 * dead;
            // Extra penalty if dead space is small-but-unusable (worst kind of gap).
            if post_residual > 0 && post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    let rel = post_residual as f64 - mean_residual;
    score += 0.35 * rel;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin
    // would leave a very poor fit.
    if bin_residual == bin_capacity {
        // Empty-bin baseline: slightly worse than a decent existing fit.
        score += 5.0;
        // But if the item fits perfectly in a fresh bin, make it attractive.
        if post_residual == 0 {
            score -= 60.0;
        }
        // If many bins are open and fragmented, a fresh bin is less costly.
        score -= 0.15 * open_bins_count as f64;
    }

    // Perfect fit celebration.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Late-stream pressure: consolidate as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins with small post residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot plausibly hold the next item.
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as f64) > post_residual as f64 {
            // Dead space relative to the lookahead item.
            score += 0.35 * (post_residual as f64 - next_item_size as f64).abs();
        } else {
            // Bonus when the next item exactly slots into the leftover space.
            score -= 0.25 * (post_residual as f64 - next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize new-bin candidate instead).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        let poor_fit = (item_size as f64 / bin_capacity as f64) > 0.6;
        if open_bins_count == 0 || (poor_fit && fitting_bins_count <= 2) {
            score -= 6.0;
        } else if crowded > 3.0 && mean_residual < item_size as f64 {
            score -= 2.0;
        } else {
            score += 15.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Global state coupling: as mean residual grows, prefer reusing large
    // residual bins rather than fragmenting them.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += 0.10 * (bin_residual as f64 - mean_residual) * (0.5 + t);

    // Slight late-stream conservatism: waste less early, pack tighter later.
    score += (1.0 - t) * 1.5 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post residual, with non-linear sharpening.
    let mut score = post + 12.0 * (post / cap).powi(3);

    // Smooth stream-progress coupling: late in the stream, waste is more costly.
    score += 30.0 * progress * (post / cap).powi(2);

    // Reward tight fits (small post_residual relative to item size) smoothly.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness * tightness;

    // Lookahead: bonus if the next item fits the post residual (good chaining).
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_frac = next_item_size as f64 / post.max(1.0);
        score -= 10.0 * fit_frac;
    } else if next_item_size > 0 {
        // Penalize leaving a gap the next item cannot use, scaled by gap size.
        score += 6.0 * (1.0 - post / (next_item_size as f64)).max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
        score -= 10.0;
    }

    // Mild penalty for proliferation of open bins relative to mean residual.
    score += 0.5 * (open_bins_count as f64).ln1p() * (mean_residual / cap);

    // New-bin candidate adjustment: make empty bins less attractive unless
    // open bins are badly fragmented (high mean residual waste).
    if bin_residual == bin_capacity {
        score += 18.0 - 15.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 create
    // "dead-space bands". Residues in {0,1,2} are excellent (tiny or zero gap),
    // mid residues are wasteful.
    let residue = post_residual % 10;
    let harmonic = match residue {
        0 => -18.0,
        1 => -12.0,
        2 => -8.0,
        3 | 4 => 4.0,
        5 => 10.0,
        6 | 7 => 14.0,
        _ => 18.0,
    };
    score += harmonic;

    // Integer-division threshold: reward bins whose post residual falls in
    // the lowest quarter-decade of capacity.
    let decade = (post_residual / 10) as f64;
    score -= (10.0 - decade).max(0.0) * 0.8;

    // Lookahead coupling: if the next item can fit exactly into the post
    // residual, strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let chain_res = post_residual - next_item_size;
            score -= (chain_res % 10 == 0) as i32 as f64 * 10.0;
            score += chain_res as f64 * 0.3;
        } else {
            // next item cannot follow; slight penalty scaled by wasted potential
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 12.0 + (item_size as f64 / bin_capacity as f64) * 8.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // is large and would leave a poor fit everywhere. Empty-bin call has
    // post_residual == bin_capacity, so its harmonic penalty is neutralized
    // and we add a strong opening cost that decays as the stream matures.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 10.0 * progress;
        // opening is more attractive when the item nearly fills the bin
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // if many bins are open, prefer consolidating into one of them
        score += open_bins_count as f64 * 1.5;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter packs).
    score += (mean_residual - post_residual as f64) * 0.25;

    // Mild consolidation pressure with stream progression.
    score += (step_index as f64 / (total_items.max(1) as f64)) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fill: strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Strict dead-space avoidance: unusable tiny gaps are heavily penalized
        if post_residual < 10 {
            score += 18.0;
        }
        // Gap too small for even the current item class => dead space
        if post_residual < item_size {
            score += 10.0 + 0.3 * post_residual as f64;
        }
        // Gap that cannot fit the lookahead item wastes the slot
        if next_item_size > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Tightness reward: fraction of residual consumed by this item
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 12.0 * tightness;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
    }

    // Open-bin pressure: with many bins open, discourage adding another
    if is_new_bin {
        score += 15.0 + 1.5 * open_bins_count as f64 + 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 25.0; // never open a bin when a fit exists, unless truly forced
        }
    }

    // Coupling with mean residual: placing into a bin below-average residual
    // (i.e., filling the emptiest bins) keeps the bin pool balanced
    if !is_new_bin {
        if (post_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // reward chains: leftover after placing next item small
            let two_step_left = post_residual - next_item_size;
            score -= 2.0 * (two_step_left as f64).min(50.0);
        } else {
            // next item won't fit here; penalize dead space relative to next item
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when decent fits exist, unless current fit is terrible
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // new bin leaves full residual; make it unattractive unless fit is poor
        score += 150.0 * (item_size as f64 / bin_capacity as f64).recip() - 50.0;
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 400.0; // opening a new bin sets up a perfect next fit
        }
    }

    // Slight preference for filling larger bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: early on, be more willing to open new bins.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let time_pressure = progress * progress;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: residuals too small for the smallest plausible item are waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(100)) {
        // post_residual unusable for the next item -> penalize dead space
        score += (post_residual as f64) * 0.5;
    }

    // Lookahead: reward if the next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to leftover.
            score += 5.0;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 200.0 * (0.5 + time_pressure);
    }

    // Penalize opening new bins when existing bins have room, more so late in stream.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 120.0 * time_pressure + (open_bins_count as f64) * 0.5;
        // But if item is large relative to mean residual, opening may be wise.
        let mean_r = mean_residual;
        if (item_size as f64) > mean_r {
            score -= 25.0;
        }
    } else {
        // Reward using bins whose residual is close to the item (tight packing).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 20.0 * tightness;

        // Prefer bins with residuals near the global mean (balance load).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Slight preference to fill larger-residual bins early (keep small bins flexible).
    score += (bin_residual as f64) * 0.05 * (1.0 - time_pressure);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: post residual, with non-linear polynomial shaping over stream progress.
    // Early on, prefer moderate residuals; late, punish any residual harshly (quadratic).
    let mut score = post * (1.0 + 1.5 * progress * progress);

    // Cubic coupling: residual^2 scaled by progress — dead space matters more later.
    score += 0.02 * post * post * (0.5 + progress);

    // Penalize residuals that are too small to ever fit another item (dead space),
    // but smooth: weight by how close residual is to the minimum item size region.
    let min_item = 1.0f64;
    let unusable = ((min_item - post) / cap).max(0.0);
    score += 30.0 * unusable * unusable * (1.0 + progress);

    // Reward tight fits: small post_residual relative to bin gets a polynomial bonus.
    let tightness = 1.0 - post / cap;
    score -= 25.0 * tightness * tightness * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty scaled by how big the leftover is.
        score += 4.0 * (post / cap) * progress;
    }

    // New-bin candidate: penalize mildly by default, penalize more when many bins open
    // or when an open bin would leave small residual (fragmentation avoidance).
    if is_new_bin {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if all open bins would leave bad residuals, opening a new bin is fine:
        let mean_bad = mean_residual / cap;
        score -= 20.0 * mean_bad * mean_bad;
        // Early stream: opening bins is cheaper (more future items to fill them).
        score -= 25.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (balanced packing), as a smooth quadratic coupling.
    score += 0.05 * (post - mean_residual) * (post - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual buckets via integer division thresholds.
    // Small post_residual => tight fit => reward.
    let post_class = post_residual / 10; // 0..10 harmonic classes
    let class_reward = match post_class {
        0 => -30.0,                      // near-perfect fill
        1 => -18.0,
        2 => -10.0,
        3 => -5.0,
        4 => 0.0,
        5 => 3.0,
        6 => 6.0,
        7 => 9.0,
        8 => 12.0,
        _ => 15.0,                       // huge leftover = dead space
    };
    score += class_reward;

    // Modulo arithmetic on post_residual relative to capacity quarters.
    let quarter = bin_capacity / 4;
    if post_residual % quarter == 0 {
        score -= 6.0; // residual aligned to harmonic grid is reusable
    } else if post_residual < quarter {
        score += 4.0; // sliver below first harmonic class
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 14.0; // chains perfectly with the next item
            // finer: how much of the residual the next item consumes
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * fill_ratio;
        } else if next_item_size <= bin_residual {
            // next item would have fit the bin's pre-state but not post-state
            score += 6.0;
        }
    } else {
        // last item: just minimize waste
        score -= 10.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad fits.
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * (open_bins_count as f64).sqrt();
        // but if nothing fits well, opening is fine: reduce penalty when item is large
        if item_size >= bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Mean-residual coupling: prefer bins deviating from the mean (keep residuals diverse).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 2.0 * dev / cap;

    // Stream progression: late in stream, be greedier (fill tightly).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=10) are pure waste.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 15.0;
    } else if post_residual <= 40 {
        score += 5.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more when pressure is low.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / (step_index as f64 + 1.0)).min(1.0);
        score += 45.0 + 30.0 * (1.0 - pressure);
    }

    // Lookahead: if the next item fits the post-residual, this placement is attractive.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 20.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += 2.0 * open_bins_count as f64;

    // Prefer bins below mean residual (fill emptier bins first keeps tight bins for tight items).
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item well
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight match bonus (decays as gap grows)
        score -= 60.0 / (1.0 + gap * 0.15);
        // Exact next-fit bonus
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // Penalize leaving a residual that is too small to be useful
        if post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.5 {
            score += 25.0;
        }
    }

    // Prefer bins tighter than the mean residual (fill crowded bins)
    let dev = (bin_residual as f64 - mean_residual).max(0.0);
    score += dev * 0.3;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize wasting a nearly-full bin on a tiny item
    if (item_size as f64) < (bin_residual as f64) * 0.2 && bin_residual < bin_capacity {
        score += 30.0;
    }

    // Slight preference for keeping few bins open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0 * (1.0 - (post_residual as f64) / 30.0);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Prefer bins whose residual deviates from the mean in a useful direction
    // (using bins with below-average residual keeps large residual bins flexible).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // New-bin candidate handling: make opening a new bin costly early, cheaper late
    // or when the item fits nothing well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual as f64 / (bin_capacity as f64); // = 1 - item/capacity
        // Open new bin only if it would be very empty-wasteful elsewhere is not the case;
        // base penalty decays with progress and with how poorly it fits existing bins.
        score += 15.0 * (1.0 - progress) + 5.0;
        if poor_fit < 0.25 {
            score -= 10.0; // large item, opening a fresh bin is reasonable
        }
        if next_item_size > 0 && next_item_size as f64 >= item_size as f64 {
            score -= 5.0; // next item is bigger; fresh bin gives flexibility
        }
    }

    // Mild penalty for scattering across many open bins.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late-stream consolidation: as stream ends, prefer filling existing bins fully.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear decay of residual utility: large residuals are increasingly penalized
    let norm_pr = pr / cap;
    score += 8.0 * norm_pr * norm_pr * (1.0 + 2.0 * progress);

    // Reward tight fits (small post_residual) more aggressively as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Lookahead coupling: reward residuals that exactly fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let norm_gap = gap / cap;
        score -= 10.0 * (1.0 - norm_gap.min(1.0)) * (1.0 + progress);
        // Penalize leaving a residual just below the next item size (dead space)
        if pr < nx {
            score += 6.0 * (1.0 - pr / nx) * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to use the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Crowding penalty: with many open bins, prefer consolidating (lower score for bins below mean residual)
    let crowd = (open_bins_count as f64).ln().max(1.0);
    let dev = (mean_residual - pr) / cap;
    score += 3.0 * crowd * dev * dev;

    // New-bin candidate: penalize opening a fresh bin unless the current item is large
    // relative to capacity (poor fit elsewhere justifies a new bin)
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score += 20.0 * (1.0 - item_frac) * (1.0 + progress);
        // A new bin is more acceptable early in the stream
        score -= 10.0 * (1.0 - progress) * item_frac;
    }

    // Smooth polynomial coupling of item size with residual
    let ifrac = item_size as f64 / cap;
    score -= 5.0 * ifrac * (1.0 - ifrac) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" is the leftover space?
    // Residuals that are multiples of common item sizes (or large enough to hold
    // typical items) are valuable; tiny residuals are dead space.
    let dead = post_residual < 10;
    if dead {
        score += 40.0; // unusable sliver
    } else {
        // reward residuals that are common harmonic sizes
        let r = post_residual;
        let harmonic_bonus: f64 = if r % 10 == 0 {
            12.0
        } else if r % 5 == 0 {
            6.0
        } else if r % 25 == 0 {
            9.0
        } else {
            0.0
        };
        score -= harmonic_bonus;

        // big residuals are flexible
        if r >= 50 {
            score -= 8.0;
        } else if r >= 30 {
            score -= 4.0;
        }
    }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // perfect-ish chain: next item exactly fills remaining space
            if post_residual == next_item_size {
                score -= 25.0;
            } else {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; leftover becomes dead weight
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize spreading across many open bins slightly; encourage consolidation
    score += (open_bins_count as f64) * 0.5;

    // Prefer tight fits overall
    score += (item_size as f64) / (bin_residual as f64).max(1.0) * 10.0 - 10.0;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // open a new bin if current best placement would leave a bad residual
        let poor_fit = post_residual < 15 && post_residual > 0;
        if poor_fit || next_item_size > bin_residual {
            score -= 20.0 + 10.0 * progress;
        } else {
            score += 30.0; // keep using existing bins when fits are decent
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Zero residual is a perfect fit: strong reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance: only this bin fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open bins pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 3.0;
    } else {
        // reward using existing bins more when many are open
        score -= (open_bins_count as f64).min(10.0) * 1.5;
    }

    // Lookahead: if next item fits exactly in the post residual, reward
    if next_item_size > 0 && next_item_size as f64 == post_residual as f64 {
        score -= 30.0;
    }
    // Penalize if post residual is too small for the next item (dead space locked)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Favor bins with residual below mean (compact usage)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Slight progression pressure: later in stream, tighten packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space), non-linear
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == 0 {
            score -= 25.0; // perfect bin closure
        } else if next_item_size == post_residual {
            score -= 30.0; // next item completes this bin perfectly
        } else if next_item_size <= post_residual {
            let after = post_residual - next_item_size;
            score -= 15.0 * (1.0 - (after as f64) / (bin_capacity as f64));
        } else {
            // next item cannot follow here: penalize proportionally to wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / 100.0);
        }
    } else {
        // last item: strongly prefer closing bins
        score += (post_residual as f64) * 0.5;
    }

    // Prefer bins below mean residual (keeps residuals balanced), but reward
    // consuming large-residual bins when fit is decent
    if (bin_residual as f64) > mean_residual + 5.0 {
        score -= 6.0;
    } else if (bin_residual as f64) < mean_residual - 5.0 {
        score += 3.0;
    }

    // Last-chance bin: strong penalty to avoid wasting the only fitting bin on a bad fit
    if fitting_bins_count == 1 {
        if post_residual <= 10 {
            score -= 12.0; // still a great fit, take it
        } else {
            score += 15.0; // consider opening a new bin instead
        }
    }

    // Mild penalty for opening new bins when many bins are open and fit exists
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + 0.5 * open_bins_count as f64;
    }

    // Slight preference to fill earlier bins as stream progresses
    score += 0.02 * (step_index as f64 / total_items.max(1) as f64) * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: favor minimal post-placement waste, with non-linear dead-space penalty
    let dead = post_residual as f64;
    score += 0.35 * (dead * dead) / bin_capacity as f64;

    // Lookahead: reward bins whose post-residual can still host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't chain here; penalize proportionally to the gap
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Crowding pressure: with many open bins, consolidate into existing ones
    score -= 0.15 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins below-average residual (fuller bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Time horizon: early on, allow more exploration (mild new-bin tolerance);
    // late in the stream, tighten packing aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0;
    score -= progress * 5.0;

    // New-bin candidate handling: penalize opening a new bin by default,
    // but relax the penalty when the item is large (poor fit elsewhere likely)
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 18.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_penalty -= 6.0; // fresh bin offers good lookahead room
        }
        if item_size > 60 {
            new_bin_penalty -= 8.0;
        }
        score += new_bin_penalty;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, scaled non-linearly by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress);

    // Non-linear dead-space penalty: small post-residuals are valuable, mid-range waste is bad.
    score += 12.0 * norm_pr * (1.0 - norm_pr) * (1.0 - progress);

    // Reward near-perfect fits more aggressively as stream progresses.
    score -= 20.0 * progress * (1.0 - norm_pr).powi(3);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward residuals that can still host the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 4.0 * norm_pr;
    }

    // Mild penalty for fragmenting when many bins are open relative to mean residual.
    score += 0.5 * (open_bins_count as f64).sqrt() * (pr - mean_residual).abs() / cap;

    // New-bin candidate: neutral-ish baseline with slight progress-aware discount.
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residue modulo common item sizes.
    // Leftovers in "nice" classes (multiples of small harmonics) are more reusable.
    let r = post_residual as i64;
    let nice_bonus = if r == 0 {
        40.0 // perfect fit
    } else if r % 10 == 0 {
        12.0
    } else if r % 5 == 0 {
        6.0
    } else if r % 2 == 0 {
        2.0
    } else {
        -3.0 // odd residue tends to be dead space
    };
    score -= nice_bonus;

    // Penalize tiny unusable slivers (dead space) with a non-linear kick.
    if r > 0 && r < 10 {
        score += (10 - r) as f64 * 2.5;
    }

    // Fraction of capacity consumed by this placement: reward high fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing bins would leave bad residue.
    if bin_residual == bin_capacity {
        // Slight default penalty so good fits in open bins win.
        score += 5.0;
        // If the next item pairs perfectly with this one in a fresh bin, opening is great.
        if next_item_size > 0 && (next_item_size + item_size) == bin_capacity {
            score -= 60.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            // Fresh bin can still host the next item's harmonic class.
            score -= 8.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0 + open_bins_count as f64 * 0.5;
    }

    // Lookahead: if the next item fits the post-residual exactly, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // Partial reward scaled by how well the next item harmonizes with the residue.
        let harmon = 1.0 - ((post_residual - next_item_size) as f64 / 20.0).min(1.0);
        score -= 10.0 * harmon;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; mildly penalize leaving residue it can't use.
        score += 4.0;
    }

    // Prefer placing into bins below mean residual (consolidating emptier space).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
