    } else if post_residual == 0 {
        // Perfect fit is the best outcome: strong reward.
        score -= 25.0;
    }

    // Reward tight fits: fraction of bin used by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Penalize leaving residual that is smaller than the smallest plausible item
    // unless it is exactly zero (dead space beyond the tiny-gap band).
    if post_residual > 0 && post_residual < item_size {
        score += 5.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: prefer packing into existing bins when many are open.
    score -= (open_bins_count as f64) * 0.8;

    // Lookahead: if the next item fits exactly into the post residual, reward;
    // if next item would be blocked by a tiny residual, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 8.0;
        }
    }

    // Progress pressure: as the stream advances, be slightly more conservative
    // about wasting space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins whose residual is below the mean
