    score += 2.0 * (bin_residual as f64 - mean_residual).max(0.0) / bin_capacity as f64
           - 1.0 * (mean_residual - bin_residual as f64).max(0.0) / bin_capacity as f64;

    // New-bin candidate: make an empty bin attractive only when it will be
    // filled substantially and existing bins would leave bad gaps.
    if bin_residual == bin_capacity {
        if fill >= 0.5 {
            score -= 5.0; // large item in a fresh bin is fine
        } else {
