    // Aggressive 2-step lookahead: reward if next item fits into post_residual exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward chains: perfect follow-up placement strongly favored.
            score -= (bin_capacity as f64 - slack) / bin_capacity as f64 * 40.0;
            if post_residual == next_item_size {
                score -= 25.0; // perfect two-item chain
            }
        } else {
            // Next item cannot follow: penalize creating dead space.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Compare against mean residual: prefer bins whose residual deviates usefully.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: neutral baseline, only attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            0.0
        };
        // High mean residual (lots of free space wasted) => new bin is fine.
        // Low mean residual (bins are well-filled) => prefer packing into open bins.
        score += fragmentation * 80.0;
        // Late in the stream, opening bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If next item is large, a fresh bin is useful.
        if next_item_size > item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize creating small, hard-to-use dead space (< 10 is unusable for min item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: bonus if the next item can also fit into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Penalize leaving a gap that just barely misses the next item.
            let gap = (next_item_size as f64 - post_residual as f64).min(30.0);
            score += 0.35 * gap;
        }
        // If next item is huge, prefer conserving large-residual bins for it.
        if next_item_size >= 70 && post_residual < next_item_size as u32 {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin gets a moderate penalty so we
    // only open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early in the stream, opening bins is cheaper (more future to fill them).
        let open_cost = 14.0 + 16.0 * progress;
        // If many bins fit the item, opening a new one is wasteful.
        let crowd = 2.5 * (fitting_bins_count as f64).min(6.0);
        score += open_cost + crowd;
        // If next item is large and this item is small, a fresh bin is more attractive.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 10.0;
