    if open_bins_count > 4 {
        score -= 0.6 * (open_bins_count as f64).min(20.0);
    }

    // Late-stream urgency: near the end, avoid opening bins and finish tight.
    let frac = step_index as f64 / (total_items.max(1) as f64);
    if frac > 0.9 {
        score -= 5.0 * (frac - 0.9) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
