    // Smooth polynomial coupling: penalize large residuals more as stream progresses
    let coupling = norm_pr * norm_pr * (0.5 + progress);
    score += 40.0 * coupling;

    // Reward tight fits via smooth term
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).min(1.0);
    score -= 15.0 * tightness * tightness;

    // Dead-space penalty if residual too small for lookahead item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += 5.0 * (gap / cap) * (1.0 - progress);
        } else if gap > -1e-9 {
            score -= 10.0;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Mild preference toward consolidating into existing bins vs new bin
    if bin_residual < bin_capacity {
        score -= 3.0 + 2.0 * progress;
    } else {
        score += 5.0 * (1.0 - progress);
    }

    // Mean-residual alignment term
    score += 0.3 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets create integer thresholds
    let post_mod = post_residual % 10;
    let post_class = post_residual / 10; // integer division: 0..10 classes

    // Penalize "dead space": residuals too small to ever fit a future item (items >= 1,
    // but small residuals < 10 are nearly dead). Harmonic penalty grows as post_mod shrinks.
    score += (10 - post_mod) as f64 * 0.35 * (post_class as f64).min(3.0);

    // Strong reward for near-exact fills (post_residual in lowest harmonic classes)
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward;
    // if next item does NOT fit, penalize proportionally to wasted opportunity.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            score -= 18.0 - (next_post as f64) * 0.4;
            if next_post % 10 == 0 {
                score -= 6.0; // harmonic alignment: next placement leaves class boundary
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid forcing a bad fit
    // unless the fit is tight; otherwise prefer opening a new bin.
    if fitting_bins_count == 1 && post_residual > 30 {
        score += 15.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual; make it a
    // middle-priority fallback — worse than good fits, better than bad ones.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64) * 0.5;
        // late in the stream, slightly discourage spawning more bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Prefer filling bins whose residual is far below the mean (consolidate waste)
    let dev = mean_residual - post_residual as f64;
    score -= dev * 0.15;

    // Mild pressure to close out well-used bins
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Penalize small unusable dead space heavily.
    // A gap is "dead" if it is too small to hold even the smallest plausible item.
    if post > 0.0 && post < 12.0 {
        score += 60.0 * (12.0 - post) / 12.0; // near-full bins with tiny gaps get penalized
    }

    // Reward exact / very tight fits strongly.
    if post == 0.0 {
        score -= 40.0;
    } else if post <= 5.0 {
        score -= 20.0;
    }

    // Prefer bins whose residual after placement can still fit the next item (lookahead synergy).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0;
        } else if post > 0.0 {
            score += 6.0; // kills the bin's future usefulness
        }
        // Perfect pairing: this item + next item fill bin exactly
        if post == nxt {
            score -= 15.0;
        }
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins,
    // and encourage consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 2.0;

    // Last-chance bonus: if this is the only bin that fits, use it rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when existing bins would waste space badly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, scaled by how tight the best existing fit would be
        let waste_elsewhere = (mean_residual - item_size as f64).max(0.0);
        score = cap - item_size as f64; // residual of fresh bin after placement
        score += 30.0 * pressure;
        if waste_elsewhere > 20.0 {
            score -= 10.0; // existing bins are loose anyway, new bin is fine
        }
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Core dead-space penalty: squared residual discourages wasteful placements.
    score += 0.6 * post * post / cap;

    // Aggressive 2-step lookahead: reward exact/near match between post_residual
    // and next_item_size (this bin becomes "perfectly" reusable next step).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        if diff < 1.0 {
            score -= 45.0;
        } else {
            // Smooth match reward, stronger the closer post_residual is to next item.
            score -= 40.0 * (-diff / 12.0).exp();
        }
        // Penalize leaving residual that neither fits next item nor stays useful.
        if post > 0.0 && post < nxt {
            score += 18.0 * (1.0 - post / nxt);
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 0.5 * post;
    }

    // Relative-to-mean coupling: bins with residual below mean are tighter fits;
    // favor filling tighter bins to consolidate space.
    score -= 10.0 * (mean_residual - post) / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild penalty on opening brand-new bins when open bins exist and fit is poor.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 + 15.0 * progress;
        // But if next item is large and post_residual would be unusable elsewhere,
        // a fresh bin is fine: reduce penalty when item leaves clean state.
        if next_item_size == 0 {
            score -= 20.0;
        }
    }

    // Slight preference for bins that become exactly half or small useful slivers.
    let p = post_residual;
    if p == 0 { score -= 60.0; }
    else if p <= 10 { score -= 20.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize large dead space that few future items could use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score -= 4.0; // usable zone
    } else {
        score += 0.05 * (post_residual as f64);
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.3 * (next_item_size as f64);
        } else if post_residual > 0 {
            score += 6.0; // blocks next item
        }
        // chain fit: residual after hosting next item still usable
        if post_residual >= next_item_size && (post_residual - next_item_size) >= 10 {
            score -= 5.0;
        }
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            60.0
        } else {
            let worst = (bin_residual - item_size) as f64;
            if worst < 5.0 { 35.0 } else { 8.0 }
        };
        // early stream: cheaper to open bins; late stream: consolidate
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let time_bias = 20.0 * (1.0 - progress);
        score += 100.0 - desperation - time_bias;
    }

    // Global state: many open bins with high mean residual -> prefer filling them
    if open_bins_count > 2 {
        let mr_gap = mean_residual - (bin_residual as f64);
        score += 0.15 * mr_gap;
        score -= 0.5 * (open_bins_count as f64).ln();
    }

    // Prefer bins with residual close to item size (best-fit flavor, non-linear)
    let diff = (bin_residual - item_size) as f64;
    score += 0.02 * diff * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 0.8 * progress) - 0.5 * x * x * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = (1.0 - x).powi(3);
    score -= 2.0 * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += (ns - pr) / cap * (1.0 + progress);
        } else {
            score -= 0.3 * (pr - ns) / cap;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 1.5 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * progress;

    // Slight alignment with mean residual to prefer below-average residual usage
    score += 0.2 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: small residuals are good (tight fit)
    // Quantize post_residual into capacity-fraction classes.
    let quarter = bin_capacity / 4; // 25
    let eighth = bin_capacity / 8;  // 12

    // Reward very tight fits (post_residual below one eighth of capacity)
    if post_residual < eighth {
        score -= 30.0;
    } else if post_residual < quarter {
        score -= 12.0;
    }

    // Modulo arithmetic on post_residual: values that divide capacity cleanly
    // (0, 10, 20, 25, 50) leave re-usable "harmonic" gaps.
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Penalize awkward residual classes: 1..9 leftover is nearly dead space
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // small but unrecoverable unless tiny items arrive
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let next_waste = post_residual - next_item_size;
            if next_waste < eighth {
                score -= 10.0;
            }
        } else {
            // next item cannot fit here: residual must survive longer stream;
            // penalize large residual that will likely fragment
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // best open bins would create terrible fragmentation.
    if bin_residual == bin_capacity {
        // Baseline attractiveness of a fresh bin: its "post_residual" is large,
        // so score already high; give a mild discount proportional to stream
        // position (early on, opening bins is cheap; late, prefer consolidation)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // But if many bins are open with lots of mean residual, discourage new bin
        score += open_bins_count as f64 * 2.0 + mean_residual * 0.3;
    }

    // Integer-division threshold: penalize bins whose residual after placement
    // is in a "half-full" awkward class (post_residual between quarter and half)
    if post_residual >= quarter && post_residual < bin_capacity / 2 {
        score += 3.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else {
        // Larger leftovers that could still serve future items: mild reward.
        score -= 0.3 * post_residual as f64;
    }

    // Reward tight fits relative to the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Open-bins pressure: discourage scattering across many bins.
    score += 2.0 * open_bins_count as f64;

    // Mean-residual coupling: prefer bins deviating below mean residual
    // (i.e., fuller bins) when the mean is high.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; prefer leaving larger usable gap.
        score += 0.2 * (next_item_size.saturating_sub(post_residual)) as f64;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    // or the stream is early and bins are scarce.
    if bin_residual == bin_capacity {
        let early = (step_index as f64) / (total_items.max(1) as f64);
        let desperation = if fitting_bins_count == 0 { 120.0 } else { 0.0 };
        score += 25.0 + 30.0 * (1.0 - early) - desperation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor small post_residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness;

    // 2-step lookahead: if next item exactly fills post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits in remaining space: mild reward, better if snug
            let next_waste = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - next_waste / (bin_capacity as f64));
        } else {
            // next item won't fit here: penalize leaving large gaps
            let gap = (next_item_size - post_residual) as f64;
            score += 0.05 * gap;
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    // Favor bins whose residual becomes close to mean (balanced packing),
    // but penalize creating residual far below mean (dead space).
    let diff = post_residual as f64 - mean_residual;
    score += 0.08 * diff.abs();
    if diff < 0.0 {
        score += 0.05 * (-diff);
    }

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer filling bins when many bins are open (reduce fragmentation).
    if open_bins_count > 1 {
        score -= 2.0 * (item_size as f64) / (bin_capacity as f64);
    }

    // Penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // New bin baseline: worse than a good fit, better than a terrible one.
        score += 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.1 * (next_item_size as f64);
        }
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor placements that nearly fill the bin.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * item_size as f64;

    // Lookahead: post residual that cannot host the next item is dead space.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        } else {
            // Reward residuals that remain useful for the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 0.2 * slack / (bin_capacity as f64);
        }
    }

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 4.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, mild preference to keep residuals balanced.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.3 * dev / (bin_capacity as f64);
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current item is large or existing residuals are poor.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = mean_residual < item_size as f64 * 0.5;
        if fitting_bins_count == 0 || poor_fit {
            score -= 10.0 + 5.0 * (item_size as f64 / 100.0);
        } else {
            // Penalize opening a new bin when open bins can host the item;
            // penalty decays late in the stream where consolidation matters.
            score += 12.0 * (1.0 - 0.5 * progress);
        }
    }

    // Slight global pressure: with many open bins, favor consolidation
    // (bins whose residual is small relative to the mean).
    if open_bins_count > 3 {
        let ratio = (bin_residual as f64) / (bin_capacity as f64);
        score += 0.5 * ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let progress_weight = 0.5 + 1.5 * t * t; // later in stream => penalize residual more
    score += progress_weight * norm_pr * norm_pr * cap;

    // Smooth interaction: residual relative to mean residual across open bins
    let mean_term = (pr - mean_residual) / cap;
    score += 10.0 * mean_term * mean_term * (1.0 - t);

    // Reward tight fits with smooth decay
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * tightness;

    // Lookahead coupling: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = ((pr - nx) / cap).max(0.0);
        score -= 20.0 * usable * (1.0 - usable) * 4.0;
        if pr < nx {
            score += 8.0 * (nx - pr) / cap * (0.5 + t);
        }
    }

    // Last-chance bin: strongly favor using it (avoid opening new bins)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - t * 0.5);
    }

    // Mild penalty for many open bins to encourage consolidation early
    score += open_bins_count as f64 * 0.3 * norm_pr * (1.0 - t);

    // New-bin candidate: prefer it only when all open bins would leave bad waste
    if bin_residual == bin_capacity {
        let waste_if_forced = (post_residual as f64) / cap;
        score = cap * (0.35 + 0.4 * waste_if_forced) + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Perfect fit is golden: strong reward.
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Harmonic classes: residual divisible by small harmonics of capacity.
        if cap / prf as f64 == (cap / prf).round() {
            score -= 30.0; // residual is a harmonic fraction of capacity (50, 25, 20, 10...)
        }
        if pr % 10 == 0 {
            score -= 12.0; // residual in the "decimal harmonic" class: likely reusable
        } else {
            score += 8.0; // off-class residual: dead-space risk
        }
        // Integer-division thresholds on post_residual.
        let cls = pr / 10; // coarse class 0..10
        score += (5 - cls.min(5)) as f64 * 6.0; // smaller classes (tighter bins) favored
        // Penalize tiny unusable slivers.
        if pr < 10 {
            score += 40.0;
        }
        if pr == 1 {
            score += 15.0;
        }
    }

    // Lookahead pairing: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0; // perfect chained fit
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            score -= 20.0 - (gap.min(40) as f64) * 0.4; // reward close fits, decay with gap
            if gap % 10 == 0 {
                score -= 10.0; // harmonic gap
            }
        } else {
            score += 10.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        score = 60.0 + mean_residual * 0.5
            - (post_residual as f64 - mean_residual).abs() * 0.1;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open
        }
        if open_bins_count > 0 && post_residual as f64 > mean_residual + 20.0 {
            score += 30.0; // wasteful to open when residuals are tight
        }
    }

    // Mild stream-phase regularization.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += phase * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the next item
    // (and too small to be useful) are heavily penalized.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space relative to the lookahead item: penalize proportionally
            let dead = (next_item_size - post_residual) as f64;
            score += 3.0 * dead;
        } else {
            // Gap still usable by next item: reward slightly
            score -= 2.0;
        }
    }

    // Unusable tiny gaps (below minimum plausible item size) are pure waste
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Tightness reward: fraction of residual consumed by this item
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few bins are open, allow opening new bins more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure
        score = 60.0 + pressure * 2.0 - (mean_residual / bin_capacity as f64) * 10.0;
        // If no open bin fits well, opening a new bin is cheap
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Using an existing bin reduces pressure slightly
        score -= pressure * 0.5;
        // Favor bins with residuals close to the mean (balanced packing)
        score += 0.2 * ((bin_residual as f64 - mean_residual).abs());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Two-step lookahead: reward residuals that exactly host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Residual can host next item: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space smaller than next item: penalize more when it's tiny.
            let dead = post_residual as f64;
            score += 25.0 * (1.0 - dead / 50.0).max(0.0);
        }
    }

    // Reward tight fits relative to the residual before placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * tightness * tightness;

    // Penalize bins with residuals far below the mean (fragmented bins),
    // reward bins with large residuals when mean is low.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: baseline preference so it's chosen only when no
    // open bin offers a decent fit; make empty bins mildly unattractive
    // but keep them viable when post_residual would be large.
    if bin_residual == bin_capacity {
        score += 35.0 - 0.2 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: penalize wasted space non-linearly.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste * waste;

    // Reward tight fits (small post residual) with a bonus.
    if post_residual <= 4 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it, else we open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual <= 10 { score -= 8.0; }
    } else if fitting_bins_count > 1 {
        // Mild penalty so among many candidates we prefer best fit via waste term.
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Dead space that next item can't use: penalize proportionally.
            score += 0.5 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // New-bin candidate logic: only attractive when open bins are quite full.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Early stream: keep some openness; late stream: prefer packing tight.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if avg_fill < 0.55 {
            // Open bins have plenty of room; opening a new bin is wasteful.
            score += 20.0;
        } else if avg_fill < 0.75 {
            score += 6.0 * (1.0 - progress);
        } else {
            // Very full bins: opening a new bin is reasonable.
            score -= 3.0;
        }
        // Many open bins: discourage adding more.
        score += 1.0 * open_bins_count as f64 * 0.3;
    }

    // Global pressure: when mean residual across bins is low, be more tolerant
    // of imperfect fits (avoid opening bins unnecessarily).
    if mean_residual < item_size as f64 {
        score -= 4.0;
    }

    // Time horizon: late in stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: mild penalty for waste; late stream: strong penalty (tighten packing).
    let tightness = 1.0 + 2.0 * progress * progress; // smooth ramp, up to 3x late
    score *= tightness;

    // Cubic dead-space term: residuals near mid-range are least reusable early,
    // tiny residuals are useless late — smooth cubic shaping.
    let dead = pr * (1.0 - pr) * (1.0 - 2.0 * pr); // negative for pr<0.5, positive above
    score -= dead * 20.0 * (0.5 + progress);

    // Reward near-perfect fills smoothly.
    score -= (1.0 - pr) * (1.0 - pr) * (1.0 - pr) * 15.0;

    // Last-chance bin: strong smooth reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Coupling with mean residual: prefer bins whose residual is close to the item need
    // (smooth quadratic divergence penalty).
    let mean_gap = (mean_residual - item_size as f64).abs() / cap;
    score += mean_gap * mean_gap * 25.0 * (0.5 + progress);

    // Lookahead coupling: if next item fits the post residual, reward this placement
    // with a smooth quadratic bonus scaled by how well it fits.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            let fit_q = (post - nx) / cap;
            score -= (1.0 - fit_q * fit_q) * 18.0;
        } else {
            // next item won't fit: penalize proportional to shortfall, smoothly
            let short = (nx - post) / cap;
            score += short * short * 22.0;
        }
    }

    // Mild preference against spreading across too many bins late in the stream.
    score += (open_bins_count as f64).ln() * (1.0 + 3.0 * progress);

    // Smooth nudge to prefer tighter residual bins overall (best-fit flavor).
    score += pr * pr * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify leftover space into
    // capacity fractions (eighths). Residuals in low classes (tiny leftovers)
    // are "dead space" -> penalize; residuals that are clean fractions of
    // capacity are reusable by common item sizes -> reward.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let eighth = cap / 8.0;
    let class = (pr / eighth).floor() as i32; // 0..8

    // Penalize fine-grained dead classes (1..3), reward coarse reusable classes.
    score += match class {
        0 => 12.0,                       // almost-full, likely dead space
        1 => 6.0,
        2 => 3.0,
        3 => 0.0,
        4 => -2.0,                       // half-full: highly reusable
        5 => -1.0,
        6 => 0.0,
        7 => -3.0,                       // nearly empty: very flexible
        _ => -4.0,
    };

    // Exact-fill reward: perfect packing.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic match: if the next item fits exactly into post_residual,
    // strongly favor this bin (lookahead chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 18.0;
        } else {
            // modulo harmony: next item leaves a small remainder
            let rem = post_residual % next_item_size.max(1);
            if rem < 4 {
                score -= 8.0;
            }
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here's leftover: mild penalty scaled by gap
        score += ((next_item_size - post_residual) as f64).min(10.0) * 0.4;
    }

    // Last-chance bin: if this is the only fitting bin, use it rather than
    // opening a new bin (unless residual would be tiny).
    if fitting_bins_count == 1 {
        score -= 7.0;
        if post_residual <= 3 {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it
    // wins only when open bins would create heavy dead space.
    if bin_residual == bin_capacity {
        score = 0.5 * cap - 0.5 * item_size as f64;
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 3.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // Late in the stream, prefer reusing open bins more aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    }

    // Tie-break toward bins already below mean residual (larger holes first,
    // best-fit-decreasing flavor).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space penalty: post_residual that cannot fit the next item is wasted space.
    if !is_new_bin && next_item_size > 0 && post_residual < next_item_size {
        let dead = next_item_size - post_residual;
        score += (dead as f64) * 2.5;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Near-perfect fit reward
    if !is_new_bin && post_residual > 0 && post_residual <= 10 {
        score -= 25.0;
    }

    // Tight fit reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if !is_new_bin {
        if fill_ratio > 0.8 {
            score -= 20.0 * (fill_ratio - 0.8) * 5.0;
        } else if fill_ratio < 0.3 {
            // poor utilization of a large residual: penalize
            score += 15.0 * (0.3 - fill_ratio);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open bins pressure: with many open bins, avoid opening new ones
    if is_new_bin {
        let pressure = open_bins_count as f64 * 8.0;
        score += pressure;
        // Early in stream, opening bins is cheaper; late, expensive
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    } else {
        // Using an existing bin reduces pressure slightly when many bins are open
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

    // Prefer bins below mean residual (consolidate waste into few bins)
    if !is_new_bin {
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.3;
    }

    // Next-item synergy: if post_residual exactly fits next item, big reward
    if !is_new_bin && next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small leftover
    else if next_item_size > 0 && post_residual > next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 25.0 - leftover.min(25.0);
    }
    // Next item cannot fit here: penalize creating dead space, worse if residual small
    else if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        score += (15.0 - dead.min(15.0)) * 2.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Reward tight fits relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // New-bin candidate: only attractive when existing bins would leave very small unusable residuals
    if bin_residual == bin_capacity {
        let open_avg = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // Prefer new bin early in stream or when open bins are fragmented
        let fragmentation = (open_bins_count as f64) * 3.0;
        score = post_residual as f64 + fragmentation - open_avg * 0.4
            + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // If a perfect lookahead match exists in an open bin, discourage new bin
        if next_item_size > 0 && next_item_size <= mean_residual as u32 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Lookahead coupling: residual left behind that cannot host the next item
    // is less valuable than residual that could. Penalize "usable" leftovers.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // dead space relative to the next item -> small bonus
            score -= (next_item_size - post_residual) as f64 * 0.5;
        } else {
            // leftover could host next item; that's fine too, mild reward
            score -= 2.0;
        }
        // If this bin is the ONLY one that can fit the current item, strongly prefer it.
        if fitting_bins_count == 1 && bin_residual >= item_size {
            score -= 30.0;
        }
    }

    // New-bin candidate logic: opening a fresh bin is only attractive when the
    // current bin's post-fit residual would be badly fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when existing residuals
        // are all large (i.e., current bins are cramped).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fragment = mean_residual / (bin_capacity as f64);
        let mut open_cost = 20.0 + 40.0 * avg_fragment;
        // Late in the stream, avoid spawning bins with tiny leftovers later;
        // slightly cheaper early when we can afford consolidation.
        open_cost *= 1.0 - 0.15 * progress;
        // If item exactly fills a fresh bin, opening is great.
        if item_size == bin_capacity {
            open_cost -= 200.0;
        }
        score += open_cost;
    }

    // Penalize bins whose residual is far above item size (loose fit wastes space)
    let slack = (bin_residual - item_size) as f64;
    score += 0.1 * slack * slack / (bin_capacity as f64);

    // Mild preference for bins below mean residual (balance residuals)
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fill = 1.0 - bin_residual as f64 / cap;

    // Base: prefer bins with small post residual (tight fit).
    let mut score = pr;

    // Non-linear reward for tight fits: quadratic coupling of post_residual with fill level.
    score -= 8.0 * (1.0 - pr / cap).powi(2) * (0.5 + fill);

    // Penalize large dead space with a cubic term that grows over the stream.
    let dead = pr / cap;
    score += 12.0 * dead.powi(3) * (0.4 + 2.0 * progress);

    // Interaction: post_residual vs mean residual — placing into a bin whose
    // post residual is close to the mean residual keeps future options balanced.
    let mr = mean_residual.max(0.0);
    score += 0.6 * (pr - mr).abs() / cap;

    // Slight preference for more-filled bins, amplified late in the stream.
    score -= (1.0 + 3.0 * progress) * fill;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - pr / cap);
    }

    // New-bin candidate: penalize opening a new bin, more so early and when
    // open bins already exist; relax penalty if item is large.
    if bin_residual == bin_capacity {
        let open_penalty = if open_bins_count > 0 { 6.0 + 4.0 * (1.0 - progress) } else { 2.0 };
        let large_item_bonus = 10.0 * (item_size as f64 / cap);
        score += open_penalty - large_item_bonus;
    }

    // Lookahead: if next item would fit the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 && (post_residual as u32) > 0 {
        score += 2.0 * (next_item_size as f64 / cap) * (pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic-class logic: classify post_residual into residue classes mod 10
    // and mod 25 to estimate "usefulness" of leftover space.
    let pr = post_residual;
    let r10 = (pr % 10) as f64;
    let r25 = (pr % 25) as f64;

    // Dead-space penalty: leftover that is awkward (small non-zero remainders)
    // is unlikely to host typical items (min size 1, but small odd remainders waste).
    if pr > 0 && pr < 10 {
        score += 12.0 + (10 - pr) as f64;
    }

    // Reward post-residuals that are exact harmonic fractions of capacity:
    // 0, 25, 50, 75 are reusable "clean" states.
    if pr == 0 {
        score -= 30.0; // perfect fill
    } else if pr % 25 == 0 {
        score -= 10.0;
    } else if pr % 10 == 0 {
        score -= 5.0;
    } else {
        // fractional noise penalty
        score += r10 * 0.4 + r25 * 0.2;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here anyway; slight penalty for wasting capacity
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // are congested or fits are poor.
    if bin_residual == bin_capacity {
        let congestion = (open_bins_count as f64).max(1.0);
        let mean_fit = mean_residual / bin_capacity as f64;
        // base cost of opening a new bin
        score = 60.0;
        // cheaper to open a bin early in the stream or when many bins already open
        score -= 10.0 * (step_index as f64 / total_items.max(1) as f64);
        score -= 2.0 * congestion.min(10.0);
        // if current item is large and would leave bad residue elsewhere, new bin attractive
        if item_size % 25 == 0 || item_size % 10 == 0 {
            score -= 6.0;
        }
        // if mean residual across open bins is high, prefer reusing them
        score += 25.0 * mean_fit;
        // if the item would fit next item too in a fresh bin, slight bonus
        if next_item_size > 0 && (next_item_size + item_size) <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild global pressure to consolidate: more open bins -> prefer filling existing ones
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A post_residual that is too small for the smallest possible item (1)
    // is pure waste; gaps below a "usefulness" threshold get superlinear penalty.
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    } else if post_residual < 10 {
        // Dead space: unusable for typical items; penalize superlinearly.
        score += (10.0 - post_residual as f64) * (10.0 - post_residual as f64) * 2.0;
    } else if post_residual < 20 {
        // Marginal gap: mild penalty.
        score += (20.0 - post_residual as f64) * 0.8;
    }

    // Reward leaving a gap that can host the lookahead item (lookahead coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // Extra reward if lookahead then fills this bin nearly exactly.
        let second_residual = post_residual - next_item_size;
        if second_residual < 5 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Gap too small for lookahead: mild dead-space penalty.
        score += 3.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins, especially tight fits.
    let bin_pressure = open_bins_count as f64;
    if fitting_bins_count > 1 {
        // Multiple candidates: reward tighter fits more (post_residual already does).
        score += 0.0;
    } else if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        score -= 12.0;
    }

    // New-bin candidate handling: neutral baseline, but prefer new bin only if
    // this item would create severe dead space in every open bin.
    if bin_residual == bin_capacity {
        // New empty bin: score = post_residual (large, ~capacity - item).
        // Add slight penalty so tight fits into open bins win, but subtract
        // if open bins are crowded (pressure) making new bin attractive.
        score -= bin_pressure.min(20.0) * 1.5;
        // If placing here leaves a huge residual relative to mean, penalize.
        if (post_residual as f64) > mean_residual + 15.0 {
            score += 10.0;
        }
    } else {
        // Existing bin: small bonus scaled by how full the bin already is.
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fullness * 5.0;
    }

    // Late-stream consolidation: as stream progresses, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins where the next item fills the post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here: penalize dead space
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin, more when bins are few or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 + 300.0 * (1.0 - progress) + 20.0 * open_bins_count as f64;
        // still allow opening when no open bin fits well
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post-residual (tight fit), with mild non-linearity.
    score = (post_residual as f64).powf(1.15) * 0.9;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Penalize large dead space, more so later in the stream when consolidation matters.
    let dead = post_residual as f64;
    score += (dead / bin_capacity as f64).powi(3) * 25.0 * (0.5 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if next item exactly fills the remainder.
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Post-residual too small for next item: penalize wasted space relative to next item.
            let waste = post_residual as f64 / next_item_size as f64;
            score += waste * 6.0 * (0.5 + progress);
        }
    } else {
        // Last item: just minimize residual.
        score -= 15.0;
    }

    // Global state coupling: if many open bins with high mean residual, prefer consolidating
    // into existing bins rather than spreading out.
    let consolidation_pressure = (open_bins_count as f64).ln().max(0.0) * (mean_residual / bin_capacity as f64);
    if bin_residual != bin_capacity {
        score -= consolidation_pressure * 4.0;
    } else {
        // New-bin candidate: penalize opening a new bin, scaled by how many bins already fit
        // the item and how much residual capacity exists elsewhere.
        let mut new_bin_score = 30.0 + consolidation_pressure * 6.0;
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            new_bin_score += 20.0; // last chance elsewhere was penalized; make new bin less attractive still
        }
        // If next item is large and post-residual of a fresh bin accommodates it well, slightly favor new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 5.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: normalized waste after placement, with non-linear (quadratic/cubic) shaping.
    let mut score = pr / cap;
    score += 0.35 * (pr / cap) * (pr / cap);
    score += 0.15 * (pr / cap).powi(3);

    // Reward tight fits (small post_residual) more strongly as the stream progresses.
    score -= 0.5 * (1.0 - pr / cap) * (0.5 + progress);

    // Lookahead coupling: if the next item exactly fits the post residual, strongly reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 1.2;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // Partial reward proportional to how well next item would fill remaining space.
        let fill = next_item_size as f64 / pr.max(1.0);
        score -= 0.4 * fill * fill;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space.
        score += 0.3 * (pr / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 0.8;
    }

    // Penalize bins whose residual is far from the mean (fragmentation avoidance),
    // with smooth interaction with progress.
    let dev = (pr - mean_residual).abs() / cap;
    score += 0.25 * dev * (0.5 + progress);

    // Mildly discourage opening new bins when few bins are open (early consolidation),
    // and when the item fits poorly in an existing bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: score is its own residual-based cost plus a
        // smooth penalty that grows with how many bins already exist.
        score += 0.15 * (open_bins_count as f64).sqrt();
        score += 0.4 * progress;
    } else {
        score -= 0.1 * (1.0 - progress);
    }

    // Slight preference for fuller bins overall (best-fit-like pressure).
    score -= 0.2 * (item_size as f64 / cap) * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Class the post-residual into harmonic buckets of the capacity.
    // Residuals that are "nice" fractions (0, 25, 50, 75 mod 100) are more reusable.
    let harmonic = pr % 20; // fine harmonic class (capacity / 5)
    score += harmonic as f64 * 0.35;

    // Strong bonus for near-perfect fills.
    if pr == 0 {
        score -= 500.0;
    } else if pr <= 5 {
        score -= 250.0;
    } else if pr <= 10 {
        score -= 100.0;
    }

    // Penalize residuals that no typical item can use (dead space classes).
    // Items are 1..100; residual < 20 is mostly dead unless exactly consumed.
    if pr > 0 && pr < 20 {
        score += 60.0;
    }

    // Integer division thresholds: post_residual / item_size ratio coupling.
    let ratio = prf / (item_size as f64).max(1.0);
    if ratio < 0.25 {
        score -= 40.0; // bin nearly full relative to item: good packing
    } else if ratio > 2.0 {
        score += 25.0; // item is tiny relative to leftover: wasteful placement
    }

    // Lookahead coupling: can next_item_size fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Chain fit: harmonic match between next item and leftover.
            let chain = (pr - next_item_size) % 20;
            score -= 30.0 + (20 - chain.min(20 - 0)) as f64 * 0.5;
            if pr == next_item_size {
                score -= 120.0; // perfect two-item chain
            }
        } else {
            // Next item won't fit here: leftover likely becomes dead space.
            score += (next_item_size - pr) as f64 * 0.4;
        }
    } else {
        // Last item: strongly prefer zero residual.
        score -= 80.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when open bins would be badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let fragmentation = mean_residual / cap;
        // Prefer new bin when existing bins are highly fragmented and item is large.
        let large_item = item_size as f64 > 0.6 * cap;
        if fragmentation > 0.5 && large_item {
            score -= 70.0 * fragmentation + 30.0 * progress;
        } else {
            score += 90.0 + 40.0 * (1.0 - fragmentation);
        }
    }

    // Mild penalty for spreading across too many open bins when mean residual is low.
    if open_bins_count > 4 && mean_residual < 0.15 * cap && bin_residual != bin_capacity {
        score += 15.0;
    }

    // Small tie-breaker favoring tighter fits among similar residuals.
    score += (bin_residual - item_size.min(bin_residual)) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the typical minimum item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    } else if post_residual < 35 {
        score += 3.0;
    } else {
        // Larger usable gaps are mildly rewarded.
        score -= 2.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Exact match with the next item's size: reserve the gap productively.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 5.0;
    }
    // Gap cannot fit the next item but is not zero: mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    // (lower post_residual already does this); when few bins are open,
    // tolerate spreading to keep residuals balanced.
    let bin_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += bin_pressure * (post_residual as f64) * 0.5;

    // Prefer bins whose residual is below mean (tighter bins) when many bins open.
    score += bin_pressure * (bin_residual as f64 - mean_residual) * 0.3;

    // Early in the stream, mildly encourage opening fresh bins for flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if it keeps a large, flexible residual
        // and current bins are congested.
        score = 40.0 - 12.0 * bin_pressure - 5.0 * (1.0 - progress) + 0.3 * post_residual as f64;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 3.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (bin_capacity as f64);

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // Extra reward if next item fills it nearly perfectly.
        let next_waste = post_residual - next_item_size;
        score -= 4.0 * (1.0 - next_waste as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space unusable by next item: mild penalty scaled by gap.
        score += 0.5 * (next_item_size as f64 - post_residual as f64).min(20.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Penalize opening a new bin when open bins exist, unless stream is early
    // and mean residual is large (plenty of room anyway).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score += 8.0;
        // Early stream with lots of slack: opening fresh bins is cheap.
        score -= 6.0 * (1.0 - progress) * pressure;
        // Late stream: prefer filling existing bins.
        score += 4.0 * progress;
        // Exact fit in a fresh bin is perfect.
        if item_size == bin_capacity {
            score -= 100.0;
        }
    }

    // Mild preference for bins below mean residual (balance load lightly).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight nudge to prefer fuller bins overall.
    score += 0.02 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = post / cap;

    // Base: prefer small post residual, with smooth polynomial shaping
    let mut score = post * (1.0 + 0.8 * fit_frac * fit_frac);

    // Stream-progress coupling: later in the stream, tighten tolerance on wasted space
    let tightness = 1.0 + 2.0 * progress * progress;
    score *= tightness;

    // Reward filling bins whose residual is close to the item (good fit)
    let fit_quality = 1.0 - (bin_residual as f64 - item_size as f64) / cap;
    score -= 12.0 * fit_quality * fit_quality;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize using a bin when many bins fit (keep flexibility), smoothly
    if fitting_bins_count > 1 {
        score += 4.0 * (fitting_bins_count as f64).ln();
    }

    // Mean-residual coupling: if this bin's residual is far above mean, mildly discourage
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev * dev / cap;

    // New-bin candidate: penalize opening unless post residual would be very usable
    if bin_residual == bin_capacity {
        let openness = 1.0 + 1.5 * (open_bins_count as f64).ln();
        let waste_penalty = post * post / (cap * cap);
        score = cap * 1.5 * openness + 40.0 * waste_penalty * (1.0 - progress);

        // If next item could use the leftover of the current best fit, prefer open bins
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 20.0;
        }
        // Late in stream, opening new bins is cheaper
        score -= 25.0 * progress;
    }

    // Lookahead bonus: if this bin's post residual exactly accommodates next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic-class logic: treat residuals modulo capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;
    let nxt = next_item_size as u32;

    // Perfect-fit classes: post_residual divisible by 10 or 20 -> strong reward.
    if pr == 0 {
        score -= 1000.0;
    } else if pr % 20 == 0 {
        score -= 60.0;
    } else if pr % 10 == 0 {
        score -= 30.0;
    }

    // Residual class via integer division thresholds (harmonic bands).
    let band = pr / 10; // 0..=10
    match band {
        0 => score += 25.0,       // tiny dead space
        1 => score -= 10.0,       // 10-19: usable by small items
        2 => score -= 15.0,
        3 => score -= 18.0,
        4 => score -= 20.0,
        5 => score -= 22.0,       // ~50 residual: half-cap class
        6 => score -= 20.0,
        7 => score -= 16.0,
        8 => score -= 12.0,
        9 => score -= 8.0,
        _ => {}
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if nxt > 0 {
        if nxt == pr {
            score -= 80.0;
        } else if nxt <= pr {
            let after = pr - nxt;
            if after % 10 == 0 { score -= 25.0; }
            score -= (pr - nxt) as f64 * 0.3;
        } else {
            // next item won't fit here: penalize leaving large residual
            score += (nxt - pr) as f64 * 0.15;
        }
        // Harmonic modulo check: pr and nxt sharing gcd class
        let g = gcd_u32(pr, nxt);
        if g >= 10 { score -= 8.0; }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: keep it slightly unattractive unless residuals are poor.
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 10.0;
        if fitting_bins_count == 0 {
            score -= 2000.0; // must open a new bin
        } else if mean_residual < 25.0 {
            score -= 30.0; // open bins are crowded; new bin reasonable
        }
    }

    // Progress modulation: later in stream, tighten packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (pr as f64 / cap);

    // Penalize bins deviating far from mean residual (fragmentation balance).
    score += ((post_residual as f64 - mean_residual) * 0.05).abs();

    score
}

fn gcd_u32(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd_u32(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit the minimum
    // item size (1..100 interface => treat < 10 as dead space) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // lookahead item won't fit here -> dead space risk
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and discourage opening new bins.
    let open_pressure = open_bins_count as f64 * 2.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count,
        // but relax pressure late in the stream when mean residual is low.
        score += 20.0 + open_pressure;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual > 40.0 {
            score += 15.0; // plenty of aggregate space already open; don't add more
        }
        if progress > 0.8 {
            score += 10.0; // late stream: consolidation matters more
        }
    } else {
        // Existing bin: mild reward scaled by how well it uses aggregate space.
        score -= open_pressure * 0.4;
        if (post_residual as f64) < mean_residual {
            score -= 5.0; // better-than-average consolidation
        }
    }

    // Prefer bins whose residual is closest to the item (tight fit bonus).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits comfortably in the post-residual
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / 50.0).max(0.0);
    }
    // Next item would NOT fit here: penalize leaving dead space relative to mean residual
    else if next_item_size > post_residual {
        let dead = (post_residual as f64 - mean_residual).max(0.0);
        score += 10.0 + dead * 0.5;
    }

    // Tight fit reward: small post_residual means efficient packing
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 12.0;
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins
    if open_bins_count > 4 {
        score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when item fits poorly everywhere
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (next_item_size > 0 && next_item_size > post_residual && post_residual < item_size);
        if poor_fit {
            score -= 15.0;
        } else {
            score += 20.0 + 0.3 * mean_residual;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual nonlinearly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward partial compatibility, scaled by how much room remains after both
            let two_step_waste = post_residual - next_item_size;
            score -= 25.0 * (1.0 - (two_step_waste as f64) / (bin_capacity as f64));
        } else {
            // next item won't fit here anyway; slight penalty for leaving awkward gaps
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins when many bins are already open with usable space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let usable_open = mean_residual / (bin_capacity as f64);
        score += 30.0 + 20.0 * usable_open + 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Mild penalty when this bin's residual deviates far above the mean (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 10.0 * dev.max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear coupling: waste penalty grows as post_residual shrinks, modulated by progress
    let waste = (norm_pr - 0.5).powi(2);
    score += 40.0 * waste * (0.5 + progress);
    // Reward tight fits, stronger later in the stream
    score -= 30.0 * (1.0 - norm_pr).powi(3) * (0.3 + 0.7 * progress);
    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }
    // Last-chance bin: strong incentive to use it
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 - progress);
    }
    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 35.0 * (1.0 - gap) * (1.0 - progress);
    } else if next_item_size > post_residual {
        score += 8.0 * progress;
    }
    // Prefer bins below mean residual slightly (keep large residuals available)
    score += 6.0 * ((pr - mean_residual) / cap).max(-1.0);
    // New-bin candidate: penalize mildly early, allow later when fits are poor
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * progress;
    }
    // Mild penalty for many open bins
    score += 0.5 * open_bins_count as f64 * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Penalize residuals in "dead" harmonic classes: small unusable slivers
    // Classes: post_residual % 20 -> coarse harmonic bins
    let class = post_residual % 20;
    match class {
        0 => { score -= 6.0; }          // perfectly aligned residual, reusable
        1..=5 => { score += 9.0; }      // tiny sliver, likely dead space
        6..=10 => { score += 2.0; }     // mid-sliver, mildly wasteful
        11..=15 => { score -= 1.0; }    // decent chunk
        _ => { score -= 3.0; }          // large chunk, very reusable
    }

    // Non-linear penalty on tiny residuals (quadratic dead-space term)
    if post_residual > 0 {
        let dead = (10.0 - pr.min(10.0)) / 10.0; // 1.0 when post_residual==0 edge
        score += dead * dead * 4.0;
    }

    // Reward tight fits (best-fit flavor): small post_residual relative to item
    let tightness = item_size as f64 / (item_size as f64 + pr + 1.0);
    score -= tightness * 8.0;

    // Lookahead coupling: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = next_item_size as f64 / cap;
        score -= 5.0 + 10.0 * chain;
        // extra harmonic bonus if post_residual - next_item_size lands on class 0
        if (post_residual - next_item_size) % 20 == 0 {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        // next item cannot use this sliver: penalize leaving it
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Many fitting bins -> less urgency; mild penalty to keep ordering by fit
    if fitting_bins_count > 2 {
        score += 0.5 * (fitting_bins_count as f64 - 2.0).min(4.0);
    }

    // New-bin candidate logic: opening a bin is only good when all open bins fit badly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin (scaled by stream progress & open bins)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 14.0 + 2.0 * open_bins_count as f64 * (0.5 + progress);
        // But if the best open fit would leave a bad harmonic class, new bin wins
        if class >= 1 && class <= 5 && post_residual > 0 {
            score -= 10.0;
        }
        // If next item is large, a fresh bin is attractive
        if next_item_size > 60 {
            score -= 6.0;
        }
    }

    // Mean residual coupling: if this bin's residual deviates badly from mean, nudge
    score += 0.15 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: overwhelming preference.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual <= 20 {
        // Medium gaps are moderately wasteful.
        score += 0.8 * (post_residual as f64 - 10.0);
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // Penalize gaps just barely too small for the next item (dead space trap).
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Pressure grows with number of open bins: discourage bin proliferation.
        score += 2.0 * open_bins_count as f64;
        // If many bins can fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 80.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // If mean residual across open bins is large, use existing space instead.
        if mean_residual > item_size as f64 {
            score += 30.0;
        }
    } else {
        // Favor bins whose residual is close to the item (tight fit).
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += 25.0 * tightness;
        // Prefer bins below the mean residual (already tight bins stay tight).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward if next item fits snugly into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            // Strong reward when the next item exactly fills the remaining space
            score -= 30.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
            // Extra bonus for perfect chain: item + next == residual
            if leftover_after_next == 0 {
                score -= 25.0;
            }
        } else {
            // Next item cannot use the leftover -> penalize wasted space proportionally
            let unusable = post_residual.min(next_item_size - 1) as f64;
            score += 0.35 * unusable;
        }
    } else {
        // Last item: just minimize post residual
        score -= 10.0;
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize new-bin candidate slightly unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 20.0 * (1.0 - tightness);
        // But allow new bin if lookahead suggests a good chain can form
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            if leftover == 0 {
                score -= 35.0;
            }
        }
    }

    // Late-stream consolidation: favor filling existing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // small-but-nonzero gap is nearly useless
    }

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chainability bonus, scaled by how snugly the next item would fit.
            let chain_tight = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * chain_tight;
        } else {
            // Leaving a gap the next item cannot use is wasted space.
            score += 10.0;
        }
        // Bonus if this placement lets BOTH current and next item nest well.
        if post_residual >= next_item_size && post_residual - next_item_size < 10 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a bin is usually wasteful unless
    // open bins are all tight or the item is huge.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let pressure = mean_residual / bin_capacity as f64; // low mean residual => bins are full
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of opening a bin, discounted when existing bins are tight.
        let mut new_cost = 45.0;
        new_cost -= 40.0 * (1.0 - pressure);
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        new_cost -= 15.0 * (1.0 - progress);
        // Large items justify fresh bins more.
        new_cost -= (item_size as f64 - 50.0).max(0.0) * 0.4;
        // If only one fitting bin exists and it is not this new bin, avoid stealing it.
        if fitting_bins_count == 1 { new_cost += 30.0; }
        score += new_cost;
    }

    // Prefer filling bins with lower residual overall (consolidation),
    // but only mildly, so exact fits still dominate.
    score += 0.15 * bin_residual as f64;

    // Slight preference to keep the number of open bins low when many are open.
    score += 0.05 * open_bins_count as f64;

    // Time-horizon modulation: late in the stream, prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_n = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr_n * (1.0 + 0.8 * pr_n) * cap;

    // Smooth polynomial coupling of residual with stream progress:
    // early on, tolerate slack; late, penalize dead space quadratically
    let coupling = pr_n * pr_n * (0.5 + 2.5 * progress) * cap;
    score += coupling;

    // Reward tight fits (non-linear bonus near zero residual)
    score -= (1.0 - pr_n).powi(3) * (10.0 + 20.0 * progress);

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 25.0 * progress;
    }

    // Lookahead: if next item fits exactly in post-residual, bonus; if post-residual
    // is too small for next item, mild penalty for wasting the slot
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - (pr - nx) / cap;
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            score += 0.02 * (pr_n * cap - nx).abs();
        }
    }

    // Prefer bins with residual below mean (consolidate space)
    score += 0.15 * (pr - mean_residual);

    // New-bin candidate: penalize mildly unless residuals are fragmented
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * progress;
        if pr_n * cap == cap {
            // fragmentation pressure: open new bin when open bins are mostly empty-tight
            if mean_residual < cap * 0.2 && open_bins_count > 0 {
                score -= 10.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best-fit core).
    score = post_residual as f64;

    // Harmonic class of post_residual: residual classes modulo capacity fractions.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;

    // Class A: perfect or near-perfect fit -> strong reward.
    if pr == 0 {
        score -= 1000.0;
    } else if pr <= 2 {
        score -= 400.0;
    } else if pr < 10 {
        score -= 150.0;
    }

    // Harmonic residue classes: residuals divisible by small integers are more
    // likely to be filled by future items (unknown distribution -> modular luck).
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 60.0;
        } else if pr % 5 == 0 {
            score -= 30.0;
        } else if pr % 2 == 0 {
            score -= 10.0;
        }
        // Dead-zone penalty: residuals in awkward ranges (1..10 exclusive of lucky classes)
        let dead = (10..20).contains(&pr) || (pr > 60 && pr < 70);
        if dead {
            score += 25.0;
        }
    }

    // Integer-division thresholds on post_residual vs next_item_size lookahead.
    if next_item_size > 0 {
        let nx = next_item_size as i64;
        if nx <= pr {
            // Next item fits here: reward, scaled by how snugly.
            score -= 40.0 + 0.5 * (pr - nx) as f64;
            if pr - nx <= 5 {
                score -= 60.0; // chain two perfect fits
            }
        } else {
            // Next item won't fit: mild penalty proportional to overflow gap.
            score += 0.3 * (nx - pr) as f64;
        }
        // Harmonic pairing: item + next exactly fills bin
        if (item_size as i64 + nx) == cap && bin_residual == cap {
            // handled implicitly via post_residual==0 path
        }
        if pr > 0 && nx % pr == 0 && pr <= 50 {
            score -= 20.0; // next item is a multiple of residual
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current bins are crowded.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 0.5;
        if crowded {
            score -= 80.0 * progress;
        } else {
            score += 120.0 + 50.0 * (open_bins_count as f64).sqrt();
        }
        // Never open a new bin when a snug fit exists elsewhere.
        if post_residual == 0 && item_size == bin_capacity {
            score -= 2000.0; // trivial full pack
        }
        if item_size as f64 >= mean_residual {
            score -= 30.0;
        }
    }

    // Mild preference to consolidate: fewer open bins -> favor existing bins.
    score += 0.5 * open_bins_count as f64;

    // Progress-aware tightening: late in stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    // Tie-break noise-free smoothing via mean residual coupling.
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals too small for the smallest item (1..100 range,
    // but tiny gaps are the real killers) are heavily penalized in a non-linear way.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits: small post_residual relative to item size gets a bonus.
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if (post_residual as f64) < 0.25 * item_size as f64 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0; // dead space blocks the lookahead item
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and prefer filling existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open,
        // or early in the stream where consolidation is cheap.
        score += 20.0 + 2.0 * open_bins_count as f64 + 30.0 * (1.0 - progress);
    } else {
        score -= pressure.min(15.0);
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins),
    // pushing toward compacting the tightest bins first.
    let dev = mean_residual - bin_residual as f64;
    score += 0.5 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild non-linearity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins where the leftover matches next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == 0 {
            // Perfect packing: excellent, nothing wasted.
            score -= 25.0;
        } else if pr >= nxt {
            // Next item fits exactly or nearly into the leftover.
            let gap = pr - nxt;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 10.0; // perfect 2-step chain
            }
        } else {
            // Leftover too small for next item: penalize dead space.
            score += 8.0 * (nxt - pr) / bin_capacity as f64;
        }
    } else {
        // Last item: just minimize post_residual hard.
        score -= 15.0 * tightness;
    }

    // Mean-residual coupling: bins deviating below mean residual are more "used up";
    // favor finishing them off rather than spreading across many bins.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 6.0 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // open bins are nearly full on average and the fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.6;
        let crowded = mean_residual < 25.0;
        if (poor_fit && next_item_size > post_residual) || crowded || progress < 0.05 {
            score -= 14.0;
        } else {
            // Penalize opening new bins when decent fits exist.
            score += 20.0 + 10.0 * progress;
        }
    }

    // Slight preference to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward filling the bin well (small post_residual).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    } else if post_residual > 50 {
        score += 15.0; // large dead space penalty
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, big bonus (chained fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slightly prefer leaving residual
        // close to next_item_size so another bin can host the pair.
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.2 * gap;
    }

    // Prefer bins with small residual relative to the mean (consolidate space).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be selective (penalize mediocre fits);
    // late in stream, just close out bins efficiently.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * (1.0 - t);

    // Many open bins: encourage closing them out (favor tight fits more).
    if open_bins_count > 5 {
        score -= 2.0 * (open_bins_count as f64).ln() * fill_ratio;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let desperate = fitting_bins_count == 0 || (fitting_bins_count == 1 && fill_ratio < 0.2);
        if desperate {
            score -= 10.0;
        } else {
            score += 60.0 + 0.5 * item_size as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;
    let mut score = pr;
    // non-linear coupling of post_residual with stream progress
    let poly = (fit_frac * fit_frac - 2.0 * fit_frac + 1.0) * (1.0 - progress);
    score -= 30.0 * poly;
    // penalize small unusable residuals more as stream progresses
    let tiny = (1.0 - fit_frac).powi(3);
    score += 20.0 * tiny * progress;
    // lookahead: reward bins that leave room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 15.0 * (1.0 - gap / cap) * (1.0 - progress);
        score += 10.0 * (gap / cap) * progress;
    }
    // last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }
    // mild penalty for spreading across many open bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * fit_frac;
    // mean residual coupling: prefer bins near the mean
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are preferred (waste minimization).
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Integer division thresholds: classify post residual into harmonic bands.
    let band = pr / 10; // 0..=10 bands
    match band {
        0 => score -= 30.0,              // perfect or near-perfect fit
        1 => score -= 18.0,              // excellent fit
        2 => score -= 10.0,              // good fit
        3 => score -= 5.0,
        4 | 5 => score += 3.0,           // mid-range leftover, mediocre
        6 | 7 => score += 8.0,
        8 => score += 15.0,              // large dead space forming
        _ => score += 22.0,
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item
    // granularities are reusable by future items.
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 5 == 0 { score -= 3.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 5.0; }
    }

    // Lookahead coupling: if next item fits exactly in post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
            // harmonic compatibility: post_residual % next_item_size small
            if pr % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this leftover; penalize large leftovers more
            score += prf * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when all open bins fit poorly.
    if bin_residual == bin_capacity {
        // base penalty so new bins aren't opened casually
        score += 12.0;
        // open new bin if current item is small relative to mean residual slack
        let slack = mean_residual - item_size as f64;
        if slack > 0.0 && slack < 8.0 {
            score -= 20.0; // open bins would leave awkward slivers
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // early stream: fewer bins open, be more willing to open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 6.0;
    }

    // Slight preference for tighter existing bins (small residual before placement).
    score += (bin_residual as f64 / cap) * 4.0;

    // Mean residual context: if open bins are generally full, prefer packing here.
    if mean_residual < 15.0 && bin_residual >= item_size {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 1u32;
    if post_residual < min_item {
        // perfect fill, great
        score -= 50.0;
    } else if post_residual < 10 {
        // dead space: nothing (>=1) can ever use it
        score += (10 - post_residual) as f64 * 8.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // residual too small for the lookahead item: likely dead space
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Reward residual that exactly fits the next item (chained fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer tight bins.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Prefer bins tighter than the mean residual (compactness).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild preference for using existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Next item fits in the residual left behind -> moderate reward scaled by tightness
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item -> penalize proportionally
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.5;
    }

    // Prefer bins tighter than the mean residual (best-fit-like sharpening)
    let resid_f = post_residual as f64;
    if resid_f < mean_residual {
        score -= 0.3 * (mean_residual - resid_f);
    } else {
        score += 0.2 * (resid_f - mean_residual);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize so it's chosen only when no open bin fits well.
    // Relax the penalty late in the stream when many bins are open (consolidation pressure drops).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can absorb the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: strongly reward filling the bin nearly exactly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual >= 10 && post_residual <= 30 {
        // residual that can host mid-size items is valuable
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; mildly penalize leaving large residual
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding effect: many open bins -> prefer consolidating into existing ones.
    let crowd = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / bin_capacity as f64);
    score += 0.35 * crowd;

    // Mean-residual alignment: prefer bins whose residual is close to the item size.
    let align = (mean_residual - item_size as f64).abs();
    score += 0.08 * align;

    // New-bin candidate handling: empty bin gets a baseline penalty that shrinks
    // late in the stream or when existing bins are all poor fits.
    if bin_residual == bin_capacity {
        let mut penalty = 18.0;
        // if no open bin fits tightly, opening a new bin is more attractive
        if fitting_bins_count == 0 {
            penalty -= 30.0;
        }
        // early in the stream, opening bins is cheap; late, avoid bin sprawl
        penalty *= (1.0 - 0.5 * progress);
        score += penalty;
    } else {
        // existing-bin bonus that grows with progress (consolidation phase)
        score -= 5.0 * progress;
    }

    // Mild preference for bins with larger residual (more flexibility preserved)
    score -= 0.03 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * (progress - 0.5) * 2.0;

    // Tight-fit reward amplified over time
    let tight = 1.0 - pr_norm;
    score -= 20.0 * tight * tight * tight * (0.5 + progress);

    // Penalize creating residuals that next item cannot use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 8.0 * (1.0 - pr / nx.max(1.0)) * (0.5 + progress);
        } else {
            score -= 4.0 * (nx / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // Mild preference for fuller bins relative to mean residual
    score -= (mean_residual - pr) * 0.05;

    // New-bin candidate: penalize slightly unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" the leftover space is.
    // Class A: residual in [0,9]  -> near-perfect fill, strong reward.
    // Class B: residual in [10,30] -> usable for small future items, mild reward.
    // Class C: residual in [31,60] -> awkward middle zone, mild penalty.
    // Class D: residual > 60      -> bin still very open, weak penalty (new-bin-like).
    let pr = post_residual;
    if pr <= 9 {
        score -= 40.0;
    } else if pr <= 30 {
        score -= 12.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 15.0;
    }

    // Modulo-arithmetic harmony: if post_residual is divisible by common small
    // item granularities (10, 20, 25), the leftover pairs well with future items.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 4.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 10.0;
            // Perfect two-item packing: post_residual == next_item_size exactly.
            if pr == next_item_size {
                score -= 15.0;
            }
        } else {
            score += 5.0;
        }
    }

    // Last-chance logic: if this is the ONLY bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits (post_residual already does this,
        // add a small tie-breaker toward fuller bins via fraction of capacity used).
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * fill_frac;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or
    // mean residual is too small to matter, or late in the stream.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64;
        let scarcity = (mean_residual / bin_capacity as f64).max(0.0);
        // Penalize new bins by default; discount penalty when mean residual is low
        // (open bins are nearly full) or when many bins exist (fragmentation).
        let mut new_penalty = 30.0 + 20.0 * (1.0 - scarcity);
        new_penalty -= 10.0 * progress; // slightly more willing to open late
        if crowd > 4.0 {
            new_penalty -= 5.0; // already fragmented, fresh bin may consolidate
        }
        if next_item_size > 0 && bin_residual as f64 >= next_item_size as f64 + item_size as f64 {
            new_penalty -= 8.0; // fresh bin can host current + next item cleanly
        }
        score += new_penalty.max(0.0);
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (push toward filling the emptier-relative bins and consolidating).
    let bin_residual_f = bin_residual as f64;
    if bin_residual_f < mean_residual {
        score -= 4.0;
    } else if bin_residual_f > mean_residual * 1.5 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // even the smallest plausible item (<=10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // "Awkward zone": residual in (10, 30) can only host small items;
    // penalize moderately, scaled by how tight the fit was.
    if post_residual >= 10 && post_residual < 30 {
        score += 8.0 * (1.0 - (post_residual as f64) / 30.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; with few, mild pressure still applies.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins with residual below the mean (tighter bins first),
    // which packs large residual bins for later big items.
    score += 0.5 * ((bin_residual as f64) - mean_residual).max(-50.0).min(50.0);

    // Lookahead: if the next item fits exactly into the post residual,
    // reward leaving that gap; if next item cannot fit, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 6.0;
        }
    }

    // New-bin candidate handling: an empty bin has large post_residual
    // naturally; adjust so it is chosen only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin relative to its post residual.
        score -= 10.0;
        // Discourage opening new bins when decent fitting bins exist.
        if fitting_bins_count > 0 {
            score += 12.0 + 2.0 * fitting_bins_count.min(5) as f64;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild tightness reward: the tighter the fit, the better.
    score -= 0.3 * (item_size as f64) / (bin_residual as f64).max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Reward closeness to next item size (lookahead matching)
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Penalize residuals that are too small for the next item (dead space)
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else {
            // Small bonus for leaving room the next item can still use
            score -= 4.0;
        }
    }

    // Relative to mean residual: prefer bins whose post residual deviates favorably
    let mean_post = mean_residual - item_size as f64;
    score += 0.35 * (post_residual as f64 - mean_post);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fits exist
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
    }

    // Slight preference to fill tighter bins (smaller residual) first
    score += 0.1 * bin_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for leaving little behind.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness * tightness;

    // Perfect fill is highly desirable.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: penalize if the leftover cannot host the next item (dead space),
    // but reward if the leftover is a perfect cradle for the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post < next {
            // dead space unless post is tiny (unavoidable)
            if post >= next * 0.5 {
                score += 6.0 * (1.0 - post / next);
            }
        } else if (post - next).abs() < 5.0 {
            score -= 12.0; // this bin becomes perfectly tight next step
        } else {
            score -= 3.0; // leftover remains usable
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a fresh bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize opening a new bin when good fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bins are more acceptable early (exploration) and when open bins are crowded.
        let openness = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let penalty = 18.0 + 30.0 * (1.0 - progress) * (1.0 - openness) + 2.0 * open_bins_count as f64;
        score += penalty;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin can absorb the next item too
        }
    } else {
        // Slight preference for filling bins that are already heavily loaded
        // (reduces number of partially-filled bins left at the end).
        let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 4.0 * fill_ratio;

        // Prefer bins whose residual is below mean residual (compact bins first),
        // keeping large-residual bins flexible for future big items.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5;
        }
    }

    // Discard tiny unusable slivers mildly (they are wasted capacity).
    if post_residual > 0 && post_residual < 5 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * (1.0 - progress);
    score += 3.0 * poly * (1.0 + 0.5 * progress);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 2.0 * (0.5 + progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 4.0 * (1.0 - norm_pr) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Reward leaving space that exactly accommodates next item
        let gap = (pr - next_item_size as f64) / cap;
        score -= 1.5 * (1.0 - gap * gap);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.1 * open_bins_count as f64 * progress;

    // New-bin candidate: prefer it only when residuals elsewhere are large
    if bin_residual == bin_capacity {
        let open_pen = if open_bins_count == 0 { 0.0 } else { mean_residual / cap };
        score += 25.0 - 30.0 * open_pen - 10.0 * progress;
    }

    // Slight preference for bins below mean residual (consolidation)
    score += 0.5 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that are "clean"
    // fractions of capacity (0, 25, 50, 75) since they pair well with common sizes.
    let class = post_residual % 25;
    score += match class { 0 => -12.0, 1 => 4.0, _ => 0.0 };

    // Integer division thresholds: bins with residual in low bands become dead space.
    if post_residual < 10 { score += 30.0; }          // near-full bin: excellent, reward more
    if post_residual >= 10 && post_residual < 20 { score += 8.0; }
    if post_residual > 60 { score += 6.0; }           // wasteful placement leaving a huge hole

    // Perfect fit bonus via modulo coupling of item_size into residual.
    if bin_residual % item_size == 0 && item_size > 0 { score -= 15.0; }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size { score -= 25.0; }
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score -= 10.0;
    }
    // Penalize if next item cannot use the leftover (dead space chain).
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 18.0; }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize the virgin bin by its untouched capacity.
    if bin_residual == bin_capacity {
        score += bin_capacity as f64 * 0.5;
        if fitting_bins_count == 0 { score -= bin_capacity as f64 * 0.9; }
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.1 { score -= 10.0; }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (tighter than average = better packing).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny gap: nearly dead space
        } else if post_residual < 20 {
            score += 30.0;
        } else if post_residual < 30 {
            score += 12.0;
        }
        // Perfect fit reward
        if post_residual == 0 {
            score -= 200.0;
        }
    }

    // Reward leaving a gap that can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + (next_item_size as f64) * 0.5;
    }

    // Penalty if post_residual is too small for the next item (dead end).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = 20.0 + open_bins_count as f64 * 3.0 + mean_residual * 0.4;
        score += pressure * (0.5 + progress);
    }

    // Prefer filling bins with larger residual (less fragmentation).
    score += (bin_residual as f64) * 0.05;

    // Mild preference for tight fits relative to item size.
    score -= (item_size as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}
